// ============================================================================
// ROBUST MOBILE AUDIO MANAGER & SINGLETON (Prevents Safari 16-player & 6-context limits)
// ============================================================================
window._globalAudioCtx = window._globalAudioCtx || null;
window._sharedAudioInstance = window._sharedAudioInstance || null;

window.getGlobalAudioContext = function () {
    try {
        if (!window._globalAudioCtx) {
            const AudioCtx = window.AudioContext || window.webkitAudioContext;
            if (AudioCtx) window._globalAudioCtx = new AudioCtx();
        }
        if (window._globalAudioCtx && window._globalAudioCtx.state === 'suspended') {
            window._globalAudioCtx.resume().catch(() => { });
        }
    } catch (e) { }
    return window._globalAudioCtx;
};

window.getSharedAudioInstance = function () {
    if (!window._sharedAudioInstance) {
        window._sharedAudioInstance = new Audio();
        window._sharedAudioInstance.preload = 'auto';
    }
    return window._sharedAudioInstance;
};

// Global First-Touch Unlocker for Mobile Browsers (iOS Safari / Android Chrome)
window.unlockMobileAudioSubsystem = function () {
    const ctx = window.getGlobalAudioContext();
    if (ctx && ctx.state === 'suspended') {
        ctx.resume().catch(() => { });
    }
    const audio = window.getSharedAudioInstance();
    if (audio && !audio.hasBeenUnlocked) {
        audio.hasBeenUnlocked = true;
        // Silent 1-sample WAV buffer
        audio.src = 'data:audio/wav;base64,UklGRigAAABXQVZFZm10IBIAAAABAAEARKwAAIhYAQACABAAAABkYXRhAgAAAAEA';
        const p = audio.play();
        if (p) {
            p.then(() => { audio.pause(); audio.currentTime = 0; }).catch(() => { });
        }
    }
    if ('speechSynthesis' in window) {
        try {
            if (window.speechSynthesis.paused) window.speechSynthesis.resume();
        } catch (e) { }
    }
};

['touchstart', 'touchend', 'pointerdown', 'mousedown', 'keydown'].forEach(ev => {
    window.addEventListener(ev, window.unlockMobileAudioSubsystem, { passive: true });
});

window.sebutAudio = function (teks, onEnd) {
    if (!teks) return;
    window.unlockMobileAudioSubsystem();

    // Hentikan audio sebelumnya dahulu
    if (typeof window.hentikanAudioSemasa === 'function') {
        window.hentikanAudioSemasa();
    }

    const audio = window.getSharedAudioInstance();
    currentAudioInstance = audio;
    window.currentAudioInstance = audio;

    var audioPath = window.getAudioPath(teks);
    if (audioPath) {
        audio.src = encodeURI(audioPath);
        audio.onended = function () {
            currentAudioInstance = null;
            window.currentAudioInstance = null;
            if (typeof onEnd === 'function') onEnd();
        };
        var fallbackDone = false;
        var triggerFallback = function () {
            if (fallbackDone) return;
            fallbackDone = true;
            fallbackTTS(teks, onEnd);
        };
        audio.onerror = triggerFallback;
        const playPromise = audio.play();
        if (playPromise !== undefined) {
            playPromise.catch(function (err) {
                // Jangan fallback jika dibatalkan oleh pengguna (cth navigasi / tekan kembali)
                if (err && err.name === 'AbortError') return;
                console.warn('Audio play failed, falling back to TTS:', err);
                triggerFallback();
            });
        }
    } else {
        fallbackTTS(teks, onEnd);
    }
};

function fallbackTTS(teks, onEnd) {
    if ('speechSynthesis' in window) {
        try {
            window.speechSynthesis.cancel();
            if (window.speechSynthesis.paused) window.speechSynthesis.resume();
        } catch (e) { }

        if (window._ttsTimeout) {
            clearTimeout(window._ttsTimeout);
            window._ttsTimeout = null;
        }

        window._ttsTimeout = setTimeout(() => {
            window._ttsTimeout = null;
            var s = new SpeechSynthesisUtterance(String(teks).replace(/[-_]/g, ' '));
            s.lang = 'ms-MY';
            s.rate = 0.88;
            s.pitch = 1.05;
            window._activeUtterance = s;

            let called = false;
            const done = () => {
                if (called) return;
                called = true;
                window._activeUtterance = null;
                if (typeof onEnd === 'function') onEnd();
            };

            s.onend = done;
            s.onerror = done;
            setTimeout(() => { if (!called && typeof onEnd === 'function') done(); }, 3500);

            try {
                window.speechSynthesis.speak(s);
            } catch (e) {
                done();
            }
        }, 30);
    } else if (typeof onEnd === 'function') {
        onEnd();
    }
}
function sebutAudio(teks, onEnd) {
    window.sebutAudio(teks, onEnd);
}
function sebutAudioHighlight(teks, id) {
    sebutAudio(teks);
    const el = document.getElementById(id);
    el.classList.add('active');
    setTimeout(() => el.classList.remove('active'), 1500);
}

// --- ANIMASI BERJAYA & BUNYI TADA ---
function playTada() {
    if (!audioCtx) audioCtx = new (window.AudioContext || window.webkitAudioContext)();
    if (audioCtx.state === 'suspended') audioCtx.resume();

    const now = audioCtx.currentTime;

    // Chord pertama
    const osc1 = audioCtx.createOscillator(); const gain1 = audioCtx.createGain();
    const osc2 = audioCtx.createOscillator();
    const osc3 = audioCtx.createOscillator();

    osc1.type = 'triangle'; osc2.type = 'triangle'; osc3.type = 'triangle';
    osc1.frequency.setValueAtTime(400, now); // G4
    osc2.frequency.setValueAtTime(500, now); // B4
    osc3.frequency.setValueAtTime(600, now); // D5

    gain1.gain.setValueAtTime(0, now);
    gain1.gain.linearRampToValueAtTime(0.55, now + 0.05);
    gain1.gain.setValueAtTime(0.55, now + 0.15);
    gain1.gain.linearRampToValueAtTime(0, now + 0.2);

    osc1.connect(gain1); osc2.connect(gain1); osc3.connect(gain1); gain1.connect(audioCtx.destination);
    osc1.start(now); osc2.start(now); osc3.start(now);
    osc1.stop(now + 0.2); osc2.stop(now + 0.2); osc3.stop(now + 0.2);

    // Chord kedua (lebih tinggi)
    const osc4 = audioCtx.createOscillator(); const gain2 = audioCtx.createGain();
    const osc5 = audioCtx.createOscillator();
    const osc6 = audioCtx.createOscillator();

    osc4.type = 'triangle'; osc5.type = 'triangle'; osc6.type = 'triangle';
    osc4.frequency.setValueAtTime(500, now + 0.2); // B4
    osc5.frequency.setValueAtTime(600, now + 0.2); // D5
    osc6.frequency.setValueAtTime(800, now + 0.2); // G5

    gain2.gain.setValueAtTime(0, now + 0.2);
    gain2.gain.linearRampToValueAtTime(0.55, now + 0.25);
    gain2.gain.setValueAtTime(0.55, now + 0.6);
    gain2.gain.exponentialRampToValueAtTime(0.01, now + 1.2);

    osc4.connect(gain2); osc5.connect(gain2); osc6.connect(gain2); gain2.connect(audioCtx.destination);
    osc4.start(now + 0.2); osc5.start(now + 0.2); osc6.start(now + 0.2);
    osc4.stop(now + 1.2); osc5.stop(now + 1.2); osc6.stop(now + 1.2);
}

function triggerSuccessAnimation(mesej, callback, retryCallback, starsCount) {
    playTada();
    if (window.confetti) {
        confetti({
            particleCount: 150,
            spread: 70,
            origin: { y: 0.6 },
            zIndex: 99999
        });
    }
    const celebration = document.getElementById('ganjaran-celebration');
    const titleEl = document.getElementById('ganjaran-celebration-title');
    const textEl = document.getElementById('ganjaran-celebration-text');
    const retryBtn = document.getElementById('ganjaran-retry-btn');
    const continueBtn = document.getElementById('ganjaran-continue-btn');

    const numStars = starsCount !== undefined ? Math.max(starsCount, 0) : 3;

    if (titleEl) {
        titleEl.innerText = numStars >= 3 ? "Tahniah Anda Hebat!" : "Cuba Lagi!";
    }

    const subheadEl = document.getElementById('ganjaran-celebration-subhead');
    if (subheadEl) {
        subheadEl.innerText = numStars >= 3 ? "Tahniah, Anda Hebat!" : "Teruskan usaha anda!";
    }

    const starCountEl = document.getElementById('ganjaran-celebration-star-count');
    if (starCountEl) {
        starCountEl.innerText = numStars.toString();
    }

    // Update 3 Stars SVG fills
    const leftPath = document.getElementById('ganjaran_star_left_path');
    const centerPath = document.getElementById('ganjaran_star_center_path');
    const rightPath = document.getElementById('ganjaran_star_right_path');
    if (leftPath) leftPath.setAttribute('fill', numStars >= 1 ? 'url(#starGold_gc_1)' : '#cbd5e1');
    if (centerPath) centerPath.setAttribute('fill', numStars >= 2 ? 'url(#starGold_gc_2)' : '#cbd5e1');
    if (rightPath) rightPath.setAttribute('fill', numStars >= 3 ? 'url(#starGold_gc_3)' : '#cbd5e1');

    if (celebration) {
        if (textEl) {
            textEl.innerText = "Pembelajaran akan menjadikan anda lebih baik.";
            textEl.style.display = 'block';
        }

        celebration.style.display = 'flex';

        const lencanaBtn = document.getElementById('ganjaran-lencana-btn');
        if (lencanaBtn) {
            lencanaBtn.style.display = 'inline-flex';
            lencanaBtn.onclick = () => {
                celebration.style.display = 'none';
                if (typeof window.tutupARSukuKata === 'function') {
                    window.tutupARSukuKata();
                }
                if (typeof window.paparSkrin === 'function') {
                    window.paparSkrin('lencana-screen');
                }
            };
        }

        if (continueBtn) {
            continueBtn.onclick = () => {
                celebration.style.display = 'none';
                if (callback) callback();
            };
        }

        if (retryBtn) {
            if (retryCallback) {
                retryBtn.style.display = 'inline-flex';
                retryBtn.onclick = () => {
                    celebration.style.display = 'none';
                    retryCallback();
                };
            } else {
                retryBtn.style.display = 'none';
            }
        }
    } else {
        if (callback) setTimeout(callback, 3000);
    }
}

