window.renderParentDashboard = function () {
    const childNames = (Array.isArray(window.parentChildNames) ? window.parentChildNames.slice() : [])
        .sort((a, b) => a.localeCompare(b, 'ms', { sensitivity: 'base' }));

    if (!window.anakTerpilih && childNames.length > 0) {
        window.anakTerpilih = childNames[0];
    }
    const childName = window.anakTerpilih || (childNames.length > 0 ? childNames[0] : 'Tiada Anak');
    const data = (window.studentData && window.studentData[childName]) ? window.studentData[childName] : studentRecord();

    // Update header info
    const nameTitle = document.getElementById('ibubapa-nama-anak-title');
    if (nameTitle) nameTitle.textContent = childName;

    const famTitle = document.getElementById('ibubapa-nama-keluarga-title');
    if (famTitle) famTitle.textContent = localStorage.getItem('bunyiKataNamaKeluarga') || '-';

    const famKod = document.getElementById('ibubapa-kod-keluarga-title');
    if (famKod) famKod.textContent = localStorage.getItem('bunyiKataKodKeluarga') || '-';

    const kelasTitle = document.getElementById('ibubapa-nama-kelas-title');
    if (kelasTitle) kelasTitle.textContent = localStorage.getItem('bunyiKataNamaKelas') || '-';

    const avatarEl = document.getElementById('ibubapa-avatar-icon');
    if (avatarEl && typeof updateAvatarElement === 'function') {
        updateAvatarElement(avatarEl, data.avatar || selectedAvatarIcon);
    }

    // Populate select
    const select = document.getElementById('ibubapa-dashboard-child-select');
    if (select) {
        select.innerHTML = '';
        if (childNames.length === 0) {
            const opt = document.createElement('option');
            opt.value = '';
            opt.textContent = '-- Belum Ada Anak --';
            select.appendChild(opt);
        } else {
            childNames.forEach(n => {
                const opt = document.createElement('option');
                opt.value = n;
                opt.textContent = n;
                if (n === childName) opt.selected = true;
                select.appendChild(opt);
            });
        }
    }

    // Stats calculation
    const totalScore = typeof jumlahMarkah === 'function' ? jumlahMarkah(data) : 0;
    const earnedBadges = typeof kiraLencanaMurid === 'function' ? kiraLencanaMurid(data) : (data.badges || []);
    const badgesCount = earnedBadges.length;

    let completedCount = 0;
    if (data.belajar) {
        Object.values(data.belajar).forEach(val => { if (val) completedCount++; });
    }
    if (data.latihan) {
        Object.values(data.latihan).forEach(val => { if (val) completedCount++; });
    }

    const scoreEl = document.getElementById('ibubapa-jumlah-markah');
    if (scoreEl) scoreEl.textContent = totalScore;

    const badgeEl = document.getElementById('ibubapa-jumlah-lencana');
    if (badgeEl) badgeEl.textContent = badgesCount;

    const actEl = document.getElementById('ibubapa-aktiviti-selesai');
    if (actEl) actEl.textContent = completedCount;

    let levelText = 'Perlu Bimbingan';
    let levelColor = '#e11d48';
    if (badgesCount >= 5 || totalScore >= 100) {
        levelText = 'Cemerlang';
        levelColor = '#16a34a';
    } else if (badgesCount >= 2 || totalScore >= 40) {
        levelText = 'Sederhana';
        levelColor = '#d97706';
    }

    const levelEl = document.getElementById('ibubapa-tahap-penguasaan');
    if (levelEl) {
        levelEl.textContent = levelText;
        levelEl.style.color = levelColor;
    }

    // AI Content
    const aiEl = document.getElementById('ibubapa-ai-content');
    const aiModalEl = document.getElementById('ibubapa-ai-content-modal');
    let advice = `Anak anda, <span style="color:#0284c7; font-weight:bold;">${childName}</span>, telah mengumpul <span style="color:#d97706; font-weight:bold;">${totalScore} markah</span> dan <span style="color:#16a34a; font-weight:bold;">${badgesCount} lencana</span> secara keseluruhan.<br/>`;
    if (badgesCount >= 5) {
        advice += `Tahniah! <strong>${childName}</strong> menunjukkan prestasi yang sangat baik dan konsisten dalam pembacaan suku kata. Galakkan mereka mencuba aktiviti yang lebih mencabar!`;
    } else if (badgesCount >= 2) {
        advice += `Bagus! <strong>${childName}</strong> membuat kemajuan yang baik. Teruskan sokongan dan latihan harian selama 10 minit untuk memantapkan sebutan dan kelancaran.`;
    } else {
        advice += `<strong>${childName}</strong> memerlukan lebih banyak latihan asas. Adalah digalakkan untuk bersama-sama anak mendengar modul Cerita Audio dan Kad 3D untuk membina keyakinan sebutan.`;
    }
    if (aiEl) aiEl.innerHTML = advice;
    if (aiModalEl) aiModalEl.innerHTML = advice;

    // Table calculation for Peta Cabaran
    const petaId = window.ibubapaPetaFilter || '1';
    const petaSelect = document.getElementById('ibubapa-peta-select');
    if (petaSelect) petaSelect.value = petaId;

    const mapObj = (typeof MAP_CHALLENGES !== 'undefined' && MAP_CHALLENGES[petaId])
        ? MAP_CHALLENGES[petaId]
        : {
            title: "Cabaran Kenal Huruf",
            modules: [
                { id: "kenali_huruf", title: "Cabaran Kenali Huruf" },
                { id: "vokal_konsonan", title: "Cabaran Vokal dan Konsonan" },
                { id: "fonik_abc", title: "Cabaran Fonik ABC" },
                { id: "pengenalan_nombor", title: "Cabaran Asas Nombor" },
                { id: "konsep_tambah", title: "Cabaran Tambah Nombor" },
                { id: "konsep_penolakan", title: "Cabaran Tolak Nombor" }
            ]
        };

    const tbody = document.getElementById('ibubapa-aktiviti-tbody');
    if (tbody) {
        tbody.innerHTML = '';
        mapObj.modules.forEach(mod => {
            const key = mod.id;
            const maxScore = typeof getMaxScore === 'function' ? getMaxScore(key) : (key === 'suku_kata_v_kv' || key === 'suku_kata_kvkk' ? 6 : 10);
            const stars = (data && data.stars && data.stars[key] !== undefined) ? Number(data.stars[key] || 0) : 0;
            const score = (data && data.scores && data.scores[key] !== undefined) ? Number(data.scores[key] || 0) : (stars > 0 ? Math.round((stars / 3) * maxScore) : 0);
            const isDone = (score >= maxScore && maxScore > 0);

            const tr = document.createElement('tr');

            let statusBadge = '';
            if (isDone) {
                statusBadge = `<span style="background:#dcfce7; color:#15803d; font-size:0.75rem; font-weight:bold; padding:4px 10px; border-radius:8px; border:1px solid #166534; display:inline-flex; align-items:center; gap:5px; white-space:nowrap;">
                            <i class="fa-solid fa-circle-check"></i> ${score}/${maxScore}
                        </span>`;
            } else {
                statusBadge = `<span style="background:#fee2e2; color:#b91c1c; font-size:0.75rem; font-weight:bold; padding:4px 10px; border-radius:8px; border:1px solid #991b1b; display:inline-flex; align-items:center; gap:5px; white-space:nowrap;">
                            <i class="fa-solid fa-circle-xmark"></i> ${score}/${maxScore}
                        </span>`;
            }

            tr.innerHTML = `
                        <td style="font-weight:bold; color:var(--color-dark); text-align:left; vertical-align:middle; padding:8px 12px;">${mod.title}</td>
                        <td style="text-align:center; vertical-align:middle; padding:8px 12px;">${statusBadge}</td>
                    `;
            tbody.appendChild(tr);
        });
    }
};

