// --- SISTEM PENGIRAAN LENCANA RASMI (5 LENCANA) ---
function kiraLencanaMurid(data) {
    if (!data) return [];
    const earned = [];
    if (typeof MAP_CHALLENGES === 'undefined') return earned;

    const badgeKeys = {
        1: 'badge_peta_1',
        2: 'badge_peta_2',
        3: 'badge_peta_3',
        4: 'badge_peta_4'
    };

    const sName = (data.nama || data.name || '').trim().toLowerCase();
    const activeStudentName = (window.namaMuridAktif || (typeof namaMuridAktif !== 'undefined' ? namaMuridAktif : '') || localStorage.getItem('muridAktif') || '').trim().toLowerCase();
    const isThisActiveStudent = Boolean(activeStudentName && sName && activeStudentName === sName);

    let mapsQualifiedCount = 0;
    for (let petaId = 1; petaId <= 4; petaId++) {
        const mapObj = MAP_CHALLENGES[petaId];
        if (!mapObj || !Array.isArray(mapObj.modules)) continue;

        let fullStarCount = 0;
        mapObj.modules.forEach(mod => {
            const key = mod.id;
            let stars = 0;
            if (data.stars && data.stars[key] !== undefined) {
                stars = Number(data.stars[key] || 0);
            } else if (data.scores && data.scores[key] !== undefined) {
                const maxScore = typeof getMaxScore === 'function' ? getMaxScore(key) : 10;
                const sc = Number(data.scores[key] || 0);
                if (sc >= maxScore * 0.9) stars = 3;
            } else if (isThisActiveStudent) {
                const lsStar = Number(localStorage.getItem('stars_' + key) || 0);
                if (lsStar > 0) stars = lsStar;
            }
            if (stars >= 3) {
                fullStarCount++;
            }
        });

        // Kriteria sah: Sekurang-kurangnya 3 aktiviti dalam cabaran utama mendapat 3 bintang penuh
        // ATAU lencana sah tersimpan dalam rekod murid (jika murid memang mempunyai markah/bintang)
        const badgeKey = badgeKeys[petaId];
        const hasStudentRecord = (data.totalBintang && data.totalBintang > 0) || (data.stars && Object.keys(data.stars).length > 0) || (data.scores && Object.keys(data.scores).length > 0);
        const alreadyEarned = (hasStudentRecord && data.badges && Array.isArray(data.badges) && data.badges.includes(badgeKey));
        if (fullStarCount >= 3 || alreadyEarned) {
            earned.push(badgeKey);
            mapsQualifiedCount++;
        }
    }

    // Lencana Ke-5: Master Badge "Kapten Harta Karun" (bila kesemua 4 cabaran peta utama selesai)
    const hasStudentRecord = (data.totalBintang && data.totalBintang > 0) || (data.stars && Object.keys(data.stars).length > 0) || (data.scores && Object.keys(data.scores).length > 0);
    if (mapsQualifiedCount >= 4 || (hasStudentRecord && data.badges && Array.isArray(data.badges) && data.badges.includes('badge_master'))) {
        earned.push('badge_master');
    }

    return Array.from(new Set(earned));
}
window.kiraLencanaMurid = kiraLencanaMurid;

function getCurrentProfileData() {
    const studentName = window.namaMuridAktif || (typeof namaMuridAktif !== 'undefined' ? namaMuridAktif : '') || localStorage.getItem('muridAktif') || localStorage.getItem('bunyiKataCurrentMurid') || localStorage.getItem('bunyiKataNamaMurid') || '';
    if (!studentName) return null;
    let s = null;
    if (typeof studentData !== 'undefined' && studentData && studentData[studentName]) {
        s = studentData[studentName];
    } else if (typeof window.studentData !== 'undefined' && window.studentData && window.studentData[studentName]) {
        s = window.studentData[studentName];
    } else {
        try {
            const raw = localStorage.getItem('bunyiKataStudentData');
            if (raw) {
                const parsed = JSON.parse(raw);
                if (parsed && parsed[studentName]) {
                    s = parsed[studentName];
                    if (typeof studentData !== 'undefined' && studentData) studentData[studentName] = s;
                    if (typeof window.studentData !== 'undefined' && window.studentData) window.studentData[studentName] = s;
                }
            }
        } catch (e) { }
    }
    if (s && (!s.badges || s.badges.length === 0) && typeof kiraLencanaMurid === 'function') {
        const earned = kiraLencanaMurid(s);
        if (Array.isArray(earned) && earned.length > 0) {
            s.badges = earned;
        }
    }
    return s;
}
window.getCurrentProfileData = getCurrentProfileData;

function isPetaCompleted(petaId, data) {
    if (!data) data = getCurrentProfileData();
    if (!data) return false;
    const existingBadges = (data && Array.isArray(data.badges)) ? data.badges : [];
    if (petaId === 'all' || petaId === 'master' || petaId === 5) {
        if (existingBadges.includes('badge_master')) return true;
    } else {
        const numId = Number(petaId);
        if (numId >= 1 && numId <= 4 && existingBadges.includes(`badge_peta_${numId}`)) return true;
    }
    const earned = (typeof kiraLencanaMurid === 'function') ? kiraLencanaMurid(data) : [];
    if (petaId === 'all' || petaId === 'master' || petaId === 5) {
        return earned.includes('badge_master');
    }
    const numId = Number(petaId);
    if (numId >= 1 && numId <= 4) {
        return earned.includes(`badge_peta_${numId}`);
    }
    return false;
}
window.isPetaCompleted = isPetaCompleted;

// --- SISTEM PENGECAMAN PINTAR NAMA MURID (SMART PARSING) ---
function parseStudentNamesInput(rawText) {
    if (!rawText || typeof rawText !== 'string') return [];

    let text = rawText.replace(/\r\n/g, '\n').replace(/\r/g, '\n');

    // Tangani format nombor turutan atas satu baris, cth: "1. Siti Aishah, 2. Muhammad Amir" atau "1) Ali 2) Abu"
    text = text.replace(/(?:^|[\s,;])(?:no\.?|bil\.?|)\s*(\d+)[\.\)\-\:]\s*/gi, '\n');

    // Ganti bullet points dengan baris baru
    text = text.replace(/[\u2022\u2023\u25E6\u2043\u2219\*\•\-\–\—\>]\s*/g, '\n');

    // Pecahkan mengikut baris baru, koma, atau titik bertindih
    const rawItems = text.split(/[\n,;\t]+/);
    const cleanedNames = [];
    const seen = new Set();
    const GHOST_NAMES = ['TETAMU', 'MURID', 'GUEST', 'STUDENT', 'NAMA', 'NAME', 'BIL', 'NO', 'LELAKI', 'PEREMPUAN', 'JANTINA', 'KELAS'];

    for (let item of rawItems) {
        if (!item) continue;
        // Buang nombor turutan di awal, simbol, dan tanda baca
        let clean = item
            .replace(/^(?:no\.?|bil\.?|)\s*\d+[\.\)\-\:\s]*/i, '')
            .replace(/^[•\*\-\–\—\>\[\]\(\)\.\,\:\;\s]+/, '')
            .replace(/[•\*\-\–\—\>\[\]\(\)\.\,\:\;\s]+$/, '')
            .replace(/\s+/g, ' ')
            .trim();

        // Buang no KP / IC jika disalin dari fail sekolah
        clean = clean.replace(/\b\d{6}-?\d{2}-?\d{4}\b/g, '').trim();
        // Buang perkataan jantina jika disalin terus dari lajur Excel
        clean = clean.replace(/\b(lelaki|perempuan)\b/gi, '').trim();
        clean = clean.replace(/\s+/g, ' ').trim();

        // Pastikan nama mempunyai sekurang-kurangnya 2 huruf
        const alphaOnly = clean.replace(/[^a-zA-Z\u00C0-\u024F]/g, '');
        if (alphaOnly.length < 2) continue;

        const upper = clean.toUpperCase();
        if (GHOST_NAMES.includes(upper)) continue;

        if (!seen.has(upper)) {
            seen.add(upper);
            cleanedNames.push(upper);
        }
    }

    return cleanedNames;
}
window.parseStudentNamesInput = parseStudentNamesInput;

function filterProfileChallenges(petaIdStr) {
    const petaId = Number(petaIdStr) || 1;
    const data = (namaMuridAktif && studentData[namaMuridAktif]) ? studentData[namaMuridAktif] : studentRecord();
    const mapObj = MAP_CHALLENGES[petaId] || MAP_CHALLENGES[1];

    let htmlContent = '';
    let completedCount = 0;

    mapObj.modules.forEach((modul) => {
        const key = modul.id;
        let stars = 0;
        if (data && data.stars) {
            stars = Number(data.stars['extra_' + key] || data.stars[key] || 0);
        }
        const maxScore = (petaId === 5) ? 3 : ((typeof getMaxScore === 'function') ? getMaxScore(key) : 10);

        let score = 0;
        if (data.scores && data.scores[key] !== undefined) {
            score = data.scores[key];
        } else if (stars > 0) {
            score = Math.round((stars / 3) * maxScore);
        } else if ((data.latihan && data.latihan[key]) || (data.belajar && data.belajar[key])) {
            score = maxScore;
        }
        if (score > maxScore) score = maxScore;

        const isDone = Boolean((data.latihan && data.latihan[key]) || (data.belajar && data.belajar[key]) || stars > 0 || score > 0);
        const isFullScore = (score >= maxScore && maxScore > 0);

        if (isFullScore) completedCount++;

        let starsHTML = `<div style="display:flex; gap:2px; font-size:0.75rem;">`;
        for (let i = 0; i < 3; i++) {
            const earned = i < stars;
            starsHTML += `<i class="fa-solid fa-star" style="color:${earned ? '#ffc107' : '#cbd5e1'}; ${earned ? 'filter:drop-shadow(0 0 2px rgba(255,193,7,0.6));' : ''}"></i>`;
        }
        starsHTML += `</div>`;

        htmlContent += `
                <div class="neo-box" style="padding: 12px 14px; display: flex; align-items: center; justify-content: space-between; gap: 10px; background: white; border: 2.5px solid var(--color-dark);   0 var(--color-dark); border-radius: 16px;">
                    <div style="display: flex; align-items: center; gap: 10px; overflow: hidden; flex: 1;">
                        <div style="font-size: 1.1rem; width: 38px; height: 38px; display: flex; align-items: center; justify-content: center; background: ${modul.color}; border-radius: 50%; color: white; border: 2px solid var(--color-dark); flex-shrink: 0;">
                            <i class="fa-solid ${modul.icon}"></i>
                        </div>
                        <div style="text-align: left; overflow: hidden;">
                            <h4 style="margin: 0; font-size: 0.85rem; font-weight: bold; color: var(--color-dark); white-space: nowrap; overflow: hidden; text-overflow: ellipsis;" title="${modul.title}">${modul.title}</h4>
                            <div style="display: flex; align-items: center; gap: 8px; margin-top: 3px; flex-wrap: wrap;">
                                ${starsHTML}
                            </div>
                        </div>
                    </div>
                    <div>
                        <span style="background: ${isFullScore ? '#dcfce7' : '#fee2e2'}; color: ${isFullScore ? '#166534' : '#991b1b'}; font-size: 0.8rem; font-weight: bold; padding: 4px 10px; border-radius: 12px; border: 1.5px solid ${isFullScore ? '#166534' : '#991b1b'}; display: inline-flex; align-items: center; justify-content: center; gap: 5px; width: 90px; box-sizing: border-box; white-space: nowrap;">
                            <i class="fa-solid ${isFullScore ? 'fa-trophy' : 'fa-circle-xmark'}"></i> ${score} / ${maxScore}
                        </span>
                    </div>
                </div>`;
    });

    const container = document.getElementById('incomplete-modules-container');
    if (container) {
        container.innerHTML = htmlContent;
    }

    const countBadge = document.getElementById('map-progress-count');
    if (countBadge) {
        countBadge.innerText = `${completedCount} / ${mapObj.modules.length} Disiapkan`;
    }
}
window.filterProfileChallenges = filterProfileChallenges;

