// --- 3D MISI CARDS SWIPER ENGINE ---
window.currentMisiModules = [];
window.currentMisiActiveIndex = 0;
window.currentMisiUnlockedIndex = 0;

function getMisiCircularOffset(idx, active, total) {
    let diff = idx - active;
    while (diff < -total / 2) diff += total;
    while (diff > total / 2) diff -= total;
    return diff;
}

window.updateMisi3DSlots = function () {
    const stage = document.getElementById('misi-3d-stage');
    if (!stage || !window.currentMisiModules || window.currentMisiModules.length === 0) return;

    const modules = window.currentMisiModules;
    const total = modules.length;
    const activeIdx = window.currentMisiActiveIndex || 0;
    const stageWidth = (stage && stage.clientWidth > 0) ? stage.clientWidth : window.innerWidth;
    const isMobile = window.innerWidth <= 768 || stageWidth <= 640;
    const stepX = isMobile ? Math.min(92, Math.floor(stageWidth * 0.26)) : 205;

    modules.forEach((modul, i) => {
        const slot = document.getElementById('misi-slot-' + i);
        if (!slot) return;

        const offset = getMisiCircularOffset(i, activeIdx, total);
        const absOffset = Math.abs(offset);

        const xPos = offset * stepX;
        const rotateY = offset * (isMobile ? -14 : -12);
        const scale = isMobile
            ? Math.max(0.70, 1.05 - absOffset * 0.25)
            : Math.max(0.72, 1.04 - absOffset * 0.22);

        let opacity = 0;
        let isVisible = false;
        if (absOffset < 0.5) {
            opacity = 1;
            isVisible = true;
        } else if (absOffset <= 1.25) {
            opacity = isMobile ? 0.75 : 0.85;
            isVisible = true;
        } else if (absOffset <= 2.2 && !isMobile) {
            opacity = 0.35;
            isVisible = true;
        } else {
            opacity = 0;
            isVisible = false;
        }

        const zIndex = Math.round(30 - absOffset * 8);
        const isCenter = absOffset < 0.5;

        slot.style.transform = 'translate(-50%, -50%) translateX(' + xPos + 'px) rotateY(' + rotateY + 'deg) scale(' + scale + ')';
        slot.style.opacity = opacity;
        slot.style.visibility = isVisible ? 'visible' : 'hidden';
        slot.style.zIndex = zIndex;
        slot.style.pointerEvents = (isVisible && opacity > 0.1) ? 'auto' : 'none';

        if (isCenter) {
            slot.classList.add('is-center');
            slot.classList.remove('is-side');
        } else {
            slot.classList.remove('is-center');
            slot.classList.add('is-side');
        }
    });

    // Update Dots
    const dotsContainer = document.getElementById('misi-3d-dots');
    if (dotsContainer) {
        const dots = dotsContainer.querySelectorAll('.misi-3d-dot');
        dots.forEach((dot, i) => {
            if (i === activeIdx) {
                dot.classList.add('active');
            } else {
                dot.classList.remove('active');
            }
        });
    }
};

