// BUTANG TINDAKAN DALAM POPUP INFO ADMIN (Reset Kata Laluan / Lanjutan Tempoh)
// Fungsi pelayan didedahkan melalui window.__adminApi (lihat adminService.ts).
// ---------------------------------------------------------------------------

function _tutupInfoAdmin() {
    const overlay = document.getElementById('app-admin-info-modal-overlay');
    if (overlay) overlay.style.display = 'none';
}

/**
 * Tunggu sehingga jambatan __adminApi tersedia.
 *
 * PUNCA BUTANG "TAK BERFUNGSI": app-logic.js dimuatkan secara DINAMIK dalam
 * useEffect React (lihat App.tsx), manakala __adminApi hanya wujud selepas
 * bundle React selesai dimuatkan (adminService.ts). Jika admin menekan butang
 * sebelum bundle siap (atau cache basi), api == null dan fungsi terus gagal
 * dengan mesej "Sesi admin tidak aktif" — walaupun sesi sebenarnya sah.
 *
 * Di sini kita menunggu sehingga ~5 saat sebelum menyerah.
 */
function _tungguAdminApi() {
    return new Promise(function (resolve) {
        let cuba = 0;
        const periksa = function () {
            const api = window.__adminApi;
            if (api && typeof api.panjangkanTempohAdmin === 'function') return resolve(api);
            cuba += 1;
            if (cuba >= 50) return resolve(null); // ~5s
            setTimeout(periksa, 100);
        };
        periksa();
    });
}

/**
 * Selesaikan rujukan profil untuk API pelayan.
 *
 * Senarai admin menggunakan `id` yang boleh jadi UID Firebase ATAU kekunci
 * profil (cth. emel yang disanitasi). Endpoint pelayan mencari `profiles/<uid>`,
 * jadi jika id itu bukan UID, kita HANTAR EMAIL sebagai ganti supaya pelayan
 * boleh mencari profil melalui carian emel. Tanpa ini, admin yang dicipta
 * melalui aliran lama menerima "Profil tidak dijumpai".
 */
function _rujukanProfilAdmin(uid, type) {
    const email = _emailPenggunaAdmin(uid, type);
    return { uid: uid, email: email };
}

function _emailPenggunaAdmin(uid, type) {
    try {
        const list = type === 'ibubapa' ? getAdminParentsList() : getAdminTeachersList();
        const rec = list.find(function (item) { return String(item.id) === String(uid); });
        if (rec && rec.email) return String(rec.email).trim();
    } catch (e) { }
    return '';
}

/** Set semula kata laluan pengguna dan paparkan kata laluan baharu. */
window.resetKataLaluanAdminPopup = async function (uid, type) {
    if (!uid) { window.showAppToast('Ralat', 'ID pengguna tidak dijumpai.'); return; }
    const api = await _tungguAdminApi();
    if (!api || typeof api.resetKataLaluanAdmin !== 'function') {
        window.showAppToast('Ralat', 'Sesi admin tidak aktif. Sila muat semula halaman dan masuk semula.');
        return;
    }

    _bukaModalResetKataLaluan(uid, type);
};
/**
 * Modal reset kata laluan admin.
 *
 * Membenarkan admin SAMA ADA menaip kata laluan baharu sendiri, ATAU
 * membiarkannya kosong supaya pelayan menjana kata laluan rawak. Ini penting
 * kerana pengguna yang terlupa kata laluan tidak dapat masuk untuk menukarnya
 * sendiri, jadi admin perlu boleh menetapkan kata laluan baharu bagi pihak
 * pengguna.
 */
function _bukaModalResetKataLaluan(uid, type) {
    let modal = document.getElementById('app-admin-reset-pass-overlay');
    if (!modal) {
        modal = document.createElement('div');
        modal.id = 'app-admin-reset-pass-overlay';
        modal.style.cssText = 'position:fixed; top:0; left:0; width:100%; height:100%; background:rgba(0,0,0,0.65); z-index:100001; display:flex; align-items:center; justify-content:center; padding:15px; box-sizing:border-box;';
        document.body.appendChild(modal);
    }
    modal.innerHTML = `
        <div class="neo-box" style="background-color:#ffffff; background-image:radial-gradient(circle, rgba(16, 24, 47, 0.12) 1.8px, transparent 1.8px); background-size:16px 16px; max-width:420px; width:100%; box-sizing:border-box; padding:24px 20px 20px; border-radius:20px; border:3px solid var(--color-dark, #10182f); box-shadow:0 6px 0 var(--color-dark, #10182f); position:relative; text-align:left;">
            <button type="button" class="neo-btn bg-red" style="position:absolute; top:12px; right:12px; width:34px; height:34px; min-width:34px; min-height:34px; padding:0; border-radius:10px; border:2px solid var(--color-dark); display:flex; align-items:center; justify-content:center; cursor:pointer; color:#fff;" onclick="document.getElementById('app-admin-reset-pass-overlay').style.display='none'">
                <i class="fa-solid fa-xmark"></i>
            </button>
            <div style="text-align:center; margin-bottom:16px;">
                <div class="neo-btn" style="background-color:#168f81; color:white; font-size:1rem; margin:0 auto; display:inline-flex; align-items:center; gap:8px; pointer-events:none; padding:8px 22px; font-weight:bold; border-radius:12px;">
                    <i class="fa-solid fa-key"></i> Reset Kata Laluan
                </div>
            </div>
            <p style="margin:0 0 12px 0; font-size:0.86rem; color:#475569; font-weight:bold; text-align:center;">
                Adakah anda pasti ingin menetapkan <strong>kata laluan baharu</strong> untuk pengguna ini?
            </p>
            <div style="background:#fffbeb; border:2px solid #fcd34d; border-radius:10px; padding:10px; margin-bottom:14px; font-size:0.8rem; color:#92400e; font-weight:bold; text-align:center;">
                <i class="fa-solid fa-triangle-exclamation"></i>
                Kata laluan lama akan terus tidak sah.
            </div>
            <label style="display:block; font-size:0.8rem; font-weight:bold; color:#334155; margin-bottom:5px;">Kata Laluan Baharu</label>
            <input id="admin-reset-pass-input" type="text" autocomplete="off" placeholder="Kosongkan untuk jana automatik" style="width:100%; padding:10px 12px; border-radius:10px; border:2px solid #cbd5e1; font-size:0.95rem; font-family:monospace; outline:none; box-sizing:border-box; margin-bottom:12px; background:#ffffff;" />
            <label style="display:block; font-size:0.8rem; font-weight:bold; color:#334155; margin-bottom:5px;">Sahkan Kata Laluan Baharu</label>
            <input id="admin-reset-pass-confirm" type="text" autocomplete="off" placeholder="Taip semula kata laluan" style="width:100%; padding:10px 12px; border-radius:10px; border:2px solid #cbd5e1; font-size:0.95rem; font-family:monospace; outline:none; box-sizing:border-box; margin-bottom:8px; background:#ffffff;" />
            <div id="admin-reset-pass-err" style="display:none; color:#b91c1c; font-size:0.8rem; font-weight:bold; margin-bottom:8px; text-align:center;"></div>
            <div style="display:flex; gap:10px; margin-top:6px;">
                <button type="button" class="neo-btn bg-white" style="flex:1; padding:11px; font-weight:bold; border-radius:10px; border:2px solid var(--color-dark); cursor:pointer; font-size:0.9rem;" onclick="document.getElementById('app-admin-reset-pass-overlay').style.display='none'">Batal</button>
                <button type="button" id="admin-reset-pass-ok" class="neo-btn" style="flex:1; padding:11px; font-weight:bold; border-radius:10px; border:2px solid #0b5c53; background:#168f81; color:#fff; cursor:pointer; font-size:0.9rem; display:inline-flex; align-items:center; justify-content:center; gap:7px; box-shadow:0 3px 0 #0b5c53;">
                    <i class="fa-solid fa-check"></i> Sahkan
                </button>
            </div>
        </div>
    `;
    modal.style.display = 'flex';

    const input = document.getElementById('admin-reset-pass-input');
    const confirm = document.getElementById('admin-reset-pass-confirm');
    const err = document.getElementById('admin-reset-pass-err');
    const okBtn = document.getElementById('admin-reset-pass-ok');

    const tunjukErr = (m) => {
        if (!err) return;
        err.textContent = m;
        err.style.display = 'block';
    };

    if (okBtn) {
        okBtn.onclick = async function () {
            const pass = (input && input.value || '').trim();
            const konf = (confirm && confirm.value || '').trim();
            if (err) err.style.display = 'none';

            // Jika admin taip kata laluan, ia mesti sepadan dengan pengesahan.
            if (pass || konf) {
                if (pass.length < 6) { tunjukErr('Kata laluan mesti sekurang-kurangnya 6 aksara.'); return; }
                if (pass !== konf) { tunjukErr('Kata laluan tidak sepadan. Sila taip semula.'); return; }
            }

            if (okBtn.disabled) return;
            okBtn.disabled = true;
            const asal = okBtn.innerHTML;
            okBtn.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i> Menyimpan...';

            // Kosong -> pelayan menjana kata laluan rawak.
            // Hantar emel juga supaya pelayan boleh cari profil sekiranya `uid`
            // sebenarnya ialah kekunci profil (cth. emel disanitasi) dan bukan UID.
            const hasil = await api.resetKataLaluanAdmin(uid, pass || '', _emailPenggunaAdmin(uid, type));
            if (!hasil || !hasil.berjaya) {
                okBtn.disabled = false;
                okBtn.innerHTML = asal;
                window.showAppToast('Gagal', (hasil && hasil.mesej) || 'Operasi gagal. Sila cuba lagi.');
                return;
            }
            modal.style.display = 'none';
            _tutupInfoAdmin();
            _paparKataLaluanBaharu(hasil.password || pass || '', type);
        };
    }
}



/** Paparkan kata laluan baharu dalam modal berasingan (salinan mudah). */
function _paparKataLaluanBaharu(password, type) {
    let modal = document.getElementById('app-admin-pass-modal-overlay');
    if (!modal) {
        modal = document.createElement('div');
        modal.id = 'app-admin-pass-modal-overlay';
        modal.style.cssText = 'position:fixed; top:0; left:0; width:100%; height:100%; background:rgba(0,0,0,0.65); z-index:100000; display:flex; align-items:center; justify-content:center; padding:15px; box-sizing:border-box;';
        document.body.appendChild(modal);
    }
    modal.innerHTML = `
        <div class="neo-box" style="background-color:#fef9ec; background-image:radial-gradient(circle, rgba(16, 24, 47, 0.12) 1.8px, transparent 1.8px); background-size:16px 16px; max-width:400px; width:100%; box-sizing:border-box; padding:24px 20px 20px; border-radius:20px; border:3px solid var(--color-dark, #10182f); box-shadow:0 6px 0 var(--color-dark, #10182f); text-align:center;">
            <div class="neo-btn" style="background-color:#168f81; color:white; font-size:1rem; margin:0 auto 16px auto; display:inline-flex; align-items:center; gap:8px; pointer-events:none; padding:8px 22px; font-weight:bold; border-radius:12px;">
                <i class="fa-solid fa-key"></i> Kata Laluan Baharu
            </div>
            <p style="margin:0 0 14px 0; font-size:0.88rem; color:#475569; font-weight:bold;">
                Salin dan berikan kata laluan ini kepada pengguna. Ia hanya dipaparkan sekali.
            </p>
            <div style="background:#ffffff; border:2px dashed #168f81; border-radius:14px; padding:16px; margin-bottom:16px; box-shadow:0 3px 0 #0f172a;">
                <span id="admin-pass-baharu-teks" style="font-family:monospace; font-size:1.3rem; font-weight:900; color:#0f172a; letter-spacing:1px; word-break:break-all;">${password}</span>
            </div>
            <div style="display:flex; gap:10px;">
                <button type="button" class="neo-btn" style="flex:1; padding:11px; font-weight:bold; border-radius:10px; border:2px solid #0f172a; background:#ffffff; cursor:pointer; display:inline-flex; align-items:center; justify-content:center; gap:7px; box-shadow:0 3px 0 #0f172a;" onclick="window.salinKataLaluanBaharu(this)">
                    <i class="fa-solid fa-clipboard"></i> Salin
                </button>
                <button type="button" class="neo-btn" style="flex:1; padding:11px; font-weight:bold; border-radius:10px; border:2px solid #000000; background:#0f172a; color:#fff; cursor:pointer; display:inline-flex; align-items:center; justify-content:center; gap:7px; box-shadow:0 3px 0 #000000;" onclick="document.getElementById('app-admin-pass-modal-overlay').style.display='none'">
                    <i class="fa-solid fa-circle-check"></i> Selesai
                </button>
            </div>
        </div>
    `;
    modal.style.display = 'flex';
}
window._paparKataLaluanBaharu = _paparKataLaluanBaharu;

window.salinKataLaluanBaharu = async function (btn) {
    const el = document.getElementById('admin-pass-baharu-teks');
    if (!el) return;
    const teks = el.innerText.trim();
    try {
        await navigator.clipboard.writeText(teks);
    } catch (e) {
        const ta = document.createElement('textarea');
        ta.value = teks;
        document.body.appendChild(ta);
        ta.select();
        try { document.execCommand('copy'); } catch (err) { }
        document.body.removeChild(ta);
    }
    if (btn) {
        const asal = btn.innerHTML;
        btn.innerHTML = '<i class="fa-solid fa-check"></i> Disalin!';
        setTimeout(function () { btn.innerHTML = asal; }, 2000);
    }
};


/** Lanjutkan tempoh langganan pengguna (pakej atau bilangan hari tersuai). */
window.lanjutanTempohAdminPopup = async function (uid, type) {
    if (!uid) { window.showAppToast('Ralat', 'ID pengguna tidak dijumpai.'); return; }
    const api = await _tungguAdminApi();
    if (!api || typeof api.panjangkanTempohAdmin !== 'function') {
        window.showAppToast('Ralat', 'Sesi admin tidak aktif. Sila muat semula halaman dan masuk semula.');
        return;
    }

    _bukaModalLanjutanTempoh(uid, type, api);
};

/** Nama lama dikekalkan supaya pautan/bookmark lama tidak pecah. */
window.panjangTempohAdminPopup = window.lanjutanTempohAdminPopup;

/**
 * Modal "Lanjutan Tempoh" langganan.
 *
 * Dua cara untuk admin menambah masa:
 *   1. Pilih pakej (1 Bulan / 3 Bulan / 1 Tahun) — cara biasa.
 *   2. Taip bilangan hari sendiri (cth. 10) — keputusan budi bicara admin,
 *      walaupun cikgu hanya membayar untuk 1 bulan. Ini penting kerana admin
 *      mungkin mahu memberi ganjaran percuma / pampasan tanpa ganti pakej.
 *
 * Tempoh baharu SELALU ditambah pada tarikh tamat sedia ada (lihat
 * /api/admin/extend-expiry), jadi baki yang belum habis tidak dihanguskan.
 */
var _cachePakejKlien = null;
var _warnaPakej = [
    { warna: '#168f81', gelap: '#0b5c53' },
    { warna: '#ea580c', gelap: '#9a3412' },
    { warna: '#0284c7', gelap: '#075985' },
];
var _PAKEJ_LALAI_KLIEN = [
    { key: '1bulan', name: '1 Bulan', days: 30, harga: 'RM15' },
    { key: '3bulan', name: '3 Bulan', days: 90, harga: 'RM40' },
    { key: '1tahun', name: '1 Tahun', days: 365, harga: 'RM69' },
];

/**
 * Ambil senarai pakej daripada /api/plans (satu sumber harga).
 * Jika gagal, guna senarai lalai supaya modal tetap berfungsi.
 */
function _ambilPakejKlien() {
    if (_cachePakejKlien) return Promise.resolve(_cachePakejKlien);
    return fetch('/api/plans')
        .then(function (r) { return r.ok ? r.json() : null; })
        .then(function (d) {
            if (d && d.success && Array.isArray(d.plans) && d.plans.length) {
                _cachePakejKlien = d.plans;
            } else {
                _cachePakejKlien = _PAKEJ_LALAI_KLIEN;
            }
            return _cachePakejKlien;
        })
        .catch(function () {
            _cachePakejKlien = _PAKEJ_LALAI_KLIEN;
            return _cachePakejKlien;
        });
}

function _pakejUntukModal(senarai) {
    return senarai.map(function (p, i) {
        var w = _warnaPakej[i % _warnaPakej.length];
        return {
            key: p.key,
            label: p.name || p.key,
            hari: '+' + p.days + ' Hari',
            harga: p.harga || '',
            warna: w.warna,
            gelap: w.gelap,
        };
    });
}
function _bukaModalLanjutanTempoh(uid, type, api) {
    // Pakej + harga datang dari /api/plans (satu sumber harga). Modal hanya
    // dipaparkan selepas senarai diterima supaya harga tidak pernah hardcode.
    _ambilPakejKlien().then(function (senarai) {
        _paparModalLanjutanTempoh(uid, type, api, _pakejUntukModal(senarai));
    });
}

function _paparModalLanjutanTempoh(uid, type, api, pakej) {

    let modal = document.getElementById('app-admin-panjang-overlay');
    if (!modal) {
        modal = document.createElement('div');
        modal.id = 'app-admin-panjang-overlay';
        modal.style.cssText = 'position:fixed; top:0; left:0; width:100%; height:100%; background:rgba(0,0,0,0.65); z-index:100001; display:flex; align-items:center; justify-content:center; padding:15px; box-sizing:border-box;';
        document.body.appendChild(modal);
    }

    const butangPakej = pakej.map((p) => `
        <button type="button" class="neo-btn" data-pakej="${p.key}" style="width:100%; padding:12px 14px; border-radius:12px; border:2px solid ${p.gelap}; background:${p.warna}; color:#fff; cursor:pointer; font-weight:bold; display:flex; align-items:center; justify-content:space-between; gap:10px; box-shadow:0 3px 0 ${p.gelap}; text-align:left;">
            <span style="display:inline-flex; align-items:center; gap:9px;">
                <i class="fa-solid fa-calendar-plus"></i>
                <span>${p.label}</span>
            </span>
            <span style="display:inline-flex; align-items:center; gap:9px; font-size:0.82rem;">
                <span style="background:rgba(255,255,255,0.25); padding:2px 8px; border-radius:8px;">${p.hari}</span>
                <span>${p.harga}</span>
            </span>
        </button>
    `).join('');

    modal.innerHTML = `
        <div class="neo-box" style="background-color:#ffffff; background-image:radial-gradient(circle, rgba(16, 24, 47, 0.12) 1.8px, transparent 1.8px); background-size:16px 16px; max-width:420px; width:100%; box-sizing:border-box; padding:24px 20px 20px; border-radius:20px; border:3px solid var(--color-dark, #10182f); box-shadow:0 6px 0 var(--color-dark, #10182f); position:relative; text-align:left;">
            <button type="button" class="neo-btn bg-red" style="position:absolute; top:12px; right:12px; width:34px; height:34px; min-width:34px; min-height:34px; padding:0; border-radius:10px; border:2px solid var(--color-dark); display:flex; align-items:center; justify-content:center; cursor:pointer; color:#fff;" onclick="document.getElementById('app-admin-panjang-overlay').style.display='none'">
                <i class="fa-solid fa-xmark"></i>
            </button>
            <div style="text-align:center; margin-bottom:16px;">
                <div class="neo-btn" style="background-color:#ea580c; color:white; font-size:1rem; margin:0 auto; display:inline-flex; align-items:center; gap:8px; pointer-events:none; padding:8px 22px; font-weight:bold; border-radius:12px;">
                    <i class="fa-solid fa-calendar-plus"></i> Lanjutan Tempoh
                </div>
            </div>
            <p style="margin:0 0 14px 0; font-size:0.86rem; color:#475569; font-weight:bold; text-align:center;">
                Tambah masa langganan. Tempoh akan ditambah pada <strong>tarikh tamat semasa</strong> — baki yang belum habis tidak hilang.
            </p>
            <div id="admin-panjang-err" style="display:none; color:#b91c1c; font-size:0.8rem; font-weight:bold; margin-bottom:8px; text-align:center;"></div>

            <div style="font-size:0.78rem; font-weight:bold; color:#64748b; text-transform:uppercase; letter-spacing:0.5px; margin-bottom:6px;">Cara 1 — Pilih Pakej</div>
            <div style="display:flex; flex-direction:column; gap:10px;">
                ${butangPakej}
            </div>

            <div style="display:flex; align-items:center; gap:10px; margin:16px 0 12px;">
                <span style="flex:1; height:2px; background:#e2e8f0;"></span>
                <span style="font-size:0.75rem; font-weight:bold; color:#94a3b8;">ATAU</span>
                <span style="flex:1; height:2px; background:#e2e8f0;"></span>
            </div>

            <div style="font-size:0.78rem; font-weight:bold; color:#64748b; text-transform:uppercase; letter-spacing:0.5px; margin-bottom:6px;">Cara 2 — Bilangan Hari Sendiri</div>
            <div style="display:flex; gap:10px;">
                <input id="admin-panjang-hari" type="number" min="1" max="3650" step="1" inputmode="numeric" placeholder="cth. 10" style="flex:1; padding:10px 12px; border-radius:10px; border:2px solid #cbd5e1; font-size:0.95rem; font-weight:bold; outline:none; box-sizing:border-box; background:#ffffff;" />
                <button type="button" id="admin-panjang-hari-ok" class="neo-btn" style="padding:10px 16px; font-weight:bold; border-radius:10px; border:2px solid #075985; background:#0284c7; color:#fff; cursor:pointer; display:inline-flex; align-items:center; justify-content:center; gap:7px; box-shadow:0 3px 0 #075985; white-space:nowrap;">
                    <i class="fa-solid fa-plus"></i> Tambah
                </button>
            </div>
            <p style="margin:6px 0 0 0; font-size:0.72rem; color:#94a3b8; font-weight:bold;">Budi bicara admin — cth. tambah 10 hari sebagai ganjaran.</p>

            <button type="button" class="neo-btn bg-white" style="width:100%; margin-top:14px; padding:11px; font-weight:bold; border-radius:10px; border:2px solid var(--color-dark); cursor:pointer; font-size:0.9rem;" onclick="document.getElementById('app-admin-panjang-overlay').style.display='none'">Batal</button>
        </div>
    `;
    modal.style.display = 'flex';

    const err = document.getElementById('admin-panjang-err');
    const semuaBtn = () => modal.querySelectorAll('button[data-pakej], #admin-panjang-hari-ok');

    /** Kongsi logik hantar: kekalkan keadaan butang, tunjuk ralat/toast. */
    const hantar = async function (btn, muatan) {
        if (btn.disabled) return;
        semuaBtn().forEach((b) => { b.disabled = true; });
        const asal = btn.innerHTML;
        btn.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i> Menyimpan...';
        if (err) err.style.display = 'none';

        const hasil = await api.panjangkanTempohAdmin(uid, muatan.planKey, muatan.hari);

        if (!hasil || !hasil.berjaya) {
            semuaBtn().forEach((b) => { b.disabled = false; });
            btn.innerHTML = asal;
            if (err) { err.textContent = (hasil && hasil.mesej) || 'Operasi gagal. Sila cuba lagi.'; err.style.display = 'block'; }
            return;
        }

        modal.style.display = 'none';
        _tutupInfoAdmin();
        if (typeof window.fetchAdminDataFromFirebase === 'function') {
            try { await window.fetchAdminDataFromFirebase(); } catch (e) { }
        }
        if (typeof window.renderAdminTable === 'function') {
            window.renderAdminTable(type === 'ibubapa' ? 'ibubapa' : 'guru');
        }
        const tkh = hasil.tarikh_tamat
            ? new Date(hasil.tarikh_tamat).toLocaleDateString('ms-MY', { day: '2-digit', month: 'long', year: 'numeric' })
            : '';
        window.showAppToast(
            'Berjaya Dilanjutkan',
            tkh ? `Tempoh langganan berjaya dilanjutkan sehingga ${tkh}.` : 'Tempoh langganan berjaya dilanjutkan.'
        );
    };

    modal.querySelectorAll('button[data-pakej]').forEach((btn) => {
        btn.onclick = function () {
            hantar(btn, { planKey: btn.getAttribute('data-pakej') });
        };
    });

    const btnHari = document.getElementById('admin-panjang-hari-ok');
    const inputHari = document.getElementById('admin-panjang-hari');
    if (btnHari && inputHari) {
        const hantarHari = function () {
            const hari = parseInt(String(inputHari.value || '').trim(), 10);
            if (!Number.isFinite(hari) || hari < 1) {
                if (err) { err.textContent = 'Masukkan bilangan hari yang sah (sekurang-kurangnya 1).'; err.style.display = 'block'; }
                inputHari.focus();
                return;
            }
            if (hari > 3650) {
                if (err) { err.textContent = 'Maksimum 3650 hari (10 tahun) sekali gus.'; err.style.display = 'block'; }
                return;
            }
            hantar(btnHari, { hari: hari });
        };
        btnHari.onclick = hantarHari;
        inputHari.addEventListener('keydown', function (ev) {
            if (ev.key === 'Enter') { ev.preventDefault(); hantarHari(); }
        });
    }
}






window.padamGuruAdmin = async function (id) {
    const teachers = getAdminTeachersList();
    const t = teachers.find(item => item.id === id);
    const namaGuru = t ? t.nama : 'guru ini';

    window.showAppModalConfirm(
        'Padam Rekod Guru',
        `Adakah anda pasti mahu memadam <strong>${namaGuru}</strong> daripada rekod sistem?<br><span style="color:#ef4444; font-size:0.85rem; font-weight:normal; display:inline-block; margin-top:6px;">Tindakan ini akan memadam akaun, kelas dan rekod murid di bawah guru ini secara kekal.</span>`,
        async function () {
            if (typeof window.deleteProfileInFirebase === 'function') {
                await window.deleteProfileInFirebase(id);
            } else if (typeof window.deleteProfileInFirebase === 'function') {
                await window.deleteProfileInFirebase(id);
            }
            if (typeof window.cleanupOrphanedStudentsInFirebase === 'function') {
                try { await window.cleanupOrphanedStudentsInFirebase(); } catch (e) { }
            }
            // Padam juga murid dan kelas guru ini daripada storan setempat
            try {
                const kodKelasList = (t?.kod_kelas || '').split(',').map(s => s.trim().toUpperCase()).filter(Boolean);
                let localMurid = JSON.parse(localStorage.getItem('bunyiKataMurid') || '[]');
                if (Array.isArray(localMurid) && kodKelasList.length > 0) {
                    localMurid = localMurid.filter(m => !kodKelasList.includes((m.kelasId || m.kelas || '').toUpperCase()));
                    localStorage.setItem('bunyiKataMurid', JSON.stringify(localMurid));
                }
            } catch (e) { }

            let curTeachers = getAdminTeachersList().filter(item => item.id !== id);
            localStorage.setItem('bunyiKataAdminTeachers', JSON.stringify(curTeachers));
            if (typeof window.fetchAdminDataFromFirebase === 'function') {
                await window.fetchAdminDataFromFirebase();
            } else if (typeof window.fetchAdminDataFromFirebase === 'function') {
                await window.fetchAdminDataFromFirebase();
            }
            if (typeof window.renderAdminUrus === 'function') window.renderAdminUrus('guru');
            if (typeof window.renderAdminTable === 'function') window.renderAdminTable('guru');
            if (document.getElementById('admin-jumlah-guru')) {
                document.getElementById('admin-jumlah-guru').innerText = curTeachers.length;
            }
            window.showAppToast('Berjaya Dipadam', 'Rekod guru, kelas dan semua murid berkaitan telah berjaya dipadam daripada pangkalan data.');
        }
    );
};

window.lanjutTempohParent = async function (id) {
    window.showAppModalConfirm(
        'Tambah Tempoh Langganan',
        'Adakah anda ingin menambah tempoh langganan ibu bapa ini sebanyak <span style="color:#16a34a; font-weight:900;">+30 Hari</span>?',
        async function () {
            if (typeof window.updateProfileSubscription === 'function') {
                await window.updateProfileSubscription(id, 30);
            }
            // Fasa 1.2b: muat semula dari Firebase (bukan +30 buta).
            if (typeof window.fetchAdminDataFromFirebase === 'function') {
                await window.fetchAdminDataFromFirebase();
            }
            if (typeof window.renderAdminUrus === 'function') window.renderAdminUrus('ibubapa');
            if (typeof window.renderAdminTable === 'function') window.renderAdminTable('ibubapa');
            window.showAppToast('Berjaya Ditambah', 'Tempoh langganan ibu bapa berjaya ditambah 30 hari!');
        }
    );
};

window.padamParentAdmin = async function (id) {
    const parents = getAdminParentsList();
    const p = parents.find(item => item.id === id);
    const namaParent = p ? p.nama : 'ibu bapa ini';

    window.showAppModalConfirm(
        'Padam Rekod Ibu Bapa',
        `Adakah anda pasti mahu memadam <strong>${namaParent}</strong> daripada rekod sistem?<br><span style="color:#ef4444; font-size:0.85rem; font-weight:normal; display:inline-block; margin-top:6px;">Tindakan ini akan memadam akaun, rekod keluarga dan profil anak berkaitan secara kekal.</span>`,
        async function () {
            if (typeof window.deleteProfileInFirebase === 'function') {
                await window.deleteProfileInFirebase(id);
            } else if (typeof window.deleteProfileInFirebase === 'function') {
                await window.deleteProfileInFirebase(id);
            }
            if (typeof window.cleanupOrphanedStudentsInFirebase === 'function') {
                try { await window.cleanupOrphanedStudentsInFirebase(); } catch (e) { }
            }
            // Padam juga profil anak ibu bapa ini daripada storan setempat
            try {
                const kodFam = (p?.kod_keluarga || '').trim().toUpperCase();
                let localMurid = JSON.parse(localStorage.getItem('bunyiKataMurid') || '[]');
                if (Array.isArray(localMurid) && kodFam) {
                    localMurid = localMurid.filter(m => (m.keluargaId || m.kod_keluarga || '').toUpperCase() !== kodFam);
                    localStorage.setItem('bunyiKataMurid', JSON.stringify(localMurid));
                }
            } catch (e) { }

            let curParents = getAdminParentsList().filter(item => item.id !== id);
            localStorage.setItem('bunyiKataAdminParents', JSON.stringify(curParents));
            if (typeof window.fetchAdminDataFromFirebase === 'function') {
                await window.fetchAdminDataFromFirebase();
            } else if (typeof window.fetchAdminDataFromFirebase === 'function') {
                await window.fetchAdminDataFromFirebase();
            }
            if (typeof window.renderAdminUrus === 'function') window.renderAdminUrus('ibubapa');
            if (typeof window.renderAdminTable === 'function') window.renderAdminTable('ibubapa');
            if (document.getElementById('admin-jumlah-ibubapa')) {
                document.getElementById('admin-jumlah-ibubapa').innerText = curParents.length;
            }
            window.showAppToast('Berjaya Dipadam', 'Rekod ibu bapa dan profil anak berkaitan telah berjaya dipadam daripada pangkalan data.');
        }
    );
};

window.tukarLanggananPengguna = async function (id, role, newPlan) {
    if (!id || !newPlan) return;

    window.showAppModalConfirm(
        'Pengesahan Tukar Pelan',
        `Adakah anda pasti mahu menukar jenis langganan pengguna ini kepada <span style="color:#ea580c; font-weight:900;">"${newPlan}"</span>?`,
        async () => {
            if (typeof window.updateProfileSubscriptionPlan === 'function') {
                const ok = await window.updateProfileSubscriptionPlan(id, newPlan);
                if (ok) {
                    if (typeof window.fetchAdminDataFromFirebase === 'function') {
                        await window.fetchAdminDataFromFirebase();
                    } else if (typeof window.fetchAdminDataFromFirebase === 'function') {
                        await window.fetchAdminDataFromFirebase();
                    }
                    if (typeof window.renderAdminUrus === 'function') window.renderAdminUrus(role);
                    if (typeof window.renderAdminTable === 'function') window.renderAdminTable(role);
                    window.showAppToast('Berjaya Dikemaskini', `Jenis langganan telah berjaya dikemaskini kepada "${newPlan}".`);
                } else {
                    window.showAppToast('Ralat', 'Ralat mengemaskini jenis langganan di pelayan.', 'error');
                }
            } else {
                window.showAppToast('Ralat', 'Fungsi kemas kini langganan tidak ditemui.', 'error');
            }
        },
        () => {
            if (typeof window.renderAdminUrus === 'function') window.renderAdminUrus(role);
            if (typeof window.renderAdminTable === 'function') window.renderAdminTable(role);
        }
    );
};

// --- JADUAL SEJARAH LANGGANAN (Mod Guru / Ibu Bapa / Admin) ---
window.sejarahLanggananPerananFilter = window.sejarahLanggananPerananFilter || 'semua';
window.sejarahLanggananCarian = window.sejarahLanggananCarian || '';

/**
 * Fasa 1.5: Papar/ sembunyi banner amaran luput langganan.
 *
 * @param {{luput:boolean, sah:boolean, langganan?:string, tarikh_tamat?:string}} hasil
 *        Keputusan daripada /api/subscription/check.
 */
window.paparBannerLuput = function (hasil) {
    const el = document.getElementById("banner-luput-langganan");
    if (!el) return;
    const teksEl = document.getElementById("banner-luput-teks");
    const tutupBtn = document.getElementById("banner-luput-tutup");

    if (!hasil || !hasil.sah || !hasil.luput) {
        el.style.display = "none";
        return;
    }

    const tarikh = hasil.tarikh_tamat ? window.formatTarikhLangganan(hasil.tarikh_tamat) : "";
    if (teksEl) {
        teksEl.innerHTML = tarikh
            ? "Langganan Pro anda telah tamat (" + tarikh + "). Akaun kini dalam mod Percuma."
            : "Langganan Pro anda telah tamat. Akaun kini dalam mod Percuma.";
    }
    el.style.cssText = "display:flex; align-items:center; gap:10px; position:sticky; top:0; z-index:400; width:100%; box-sizing:border-box; padding:9px 14px; background:linear-gradient(135deg, #dc2626 0%, #991b1b 100%); color:#ffffff; font-family:'Baloo 2', 'Fredoka', sans-serif; font-weight:800; font-size:0.88rem; border-bottom:3px solid #7f1d1d;";
    if (tutupBtn) {
        tutupBtn.onclick = function () { el.style.display = "none"; };
    }
};

window.formatTarikhLangganan = function (iso) {
    if (!iso) return '-';
    const d = new Date(iso);
    if (isNaN(d.getTime())) return '-';
    const bulan = ['Jan', 'Feb', 'Mac', 'Apr', 'Mei', 'Jun', 'Jul', 'Ogo', 'Sep', 'Okt', 'Nov', 'Dis'];
    return `${String(d.getDate()).padStart(2, '0')} ${bulan[d.getMonth()]} ${d.getFullYear()}`;
};

window.getIdentitiLanggananSemasa = function (peranan) {
    const userId = (localStorage.getItem('bunyiKataUserId') || '').trim().toLowerCase();
    const emel = (peranan === 'ibubapa'
        ? (localStorage.getItem('bunyiKataIbubapaEmail') || localStorage.getItem('bunyiKataParentEmail') || '')
        : (localStorage.getItem('bunyiKataGuruEmail') || '')).trim().toLowerCase();
    const nama = (peranan === 'ibubapa'
        ? (localStorage.getItem('bunyiKataNamaKeluarga') || localStorage.getItem('bunyiKataNamaIbubapa') || '')
        : (localStorage.getItem('bunyiKataNamaGuru') || localStorage.getItem('pdf_guru') || '')).trim().toLowerCase();
    return { userId, emel, nama };
};

window.tukarSejarahLanggananFilter = function (peranan, nilai) {
    // Penapis peranan (Mod Admin sahaja): semua / guru / ibubapa
    if (peranan === 'admin') {
        window.sejarahLanggananPerananFilter = nilai || 'semua';
    }
    window.renderSejarahLangganan(peranan);
};

window.tukarCarianSejarahLangganan = function (peranan, nilai) {
    // Carian nama / emel (Mod Admin sahaja)
    window.sejarahLanggananCarian = nilai || '';
    window.renderSejarahLangganan(peranan);
};

window.renderSejarahLangganan = function (peranan) {
    const tbody = document.getElementById(`${peranan}-sejarah-langganan-body`);
    if (!tbody) return;

    const rekodSemua = Array.isArray(window.__sejarahLanggananCache) ? window.__sejarahLanggananCache : [];
    let senarai = rekodSemua;

    if (peranan === 'guru' || peranan === 'ibubapa') {
        // Mod Guru / Ibu Bapa: hanya sejarah langganan pengguna itu sahaja.
        const id = window.getIdentitiLanggananSemasa(peranan);
        senarai = rekodSemua.filter(r => {
            const emelRekod = String(r.email || '').trim().toLowerCase();
            const namaRekod = String(r.nama || '').trim().toLowerCase();
            if (id.emel && emelRekod && emelRekod === id.emel) return true;
            if (id.userId && emelRekod === id.userId) return true;
            if (id.nama && namaRekod && namaRekod === id.nama) return true;
            return false;
        });
    } else {
        // Mod Admin: tunjuk semua, dengan penapis peranan + carian nama/emel.
        const penapis = window.sejarahLanggananPerananFilter || 'semua';
        const carian = (window.sejarahLanggananCarian || '').trim().toLowerCase();
        senarai = rekodSemua.filter(r => {
            const perananRekod = String(r.peranan || '').trim().toLowerCase();
            if (penapis !== 'semua' && perananRekod !== penapis) return false;
            if (!carian) return true;
            return String(r.nama || '').toLowerCase().includes(carian)
                || String(r.email || '').toLowerCase().includes(carian);
        });
    }

    if (senarai.length === 0) {
        const mesej = (peranan === 'guru' || peranan === 'ibubapa')
            ? 'Belum ada sejarah langganan untuk akaun ini.'
            : 'Tiada rekod langganan yang sepadan dengan penapis ini.';
        tbody.innerHTML = `
            <tr>
                <td colspan="5" style="padding:30px 16px; text-align:center; color:#64748b; font-weight:bold; font-size:0.9rem;">
                    <i class="fa-solid fa-clock-rotate-left" style="font-size:1.8rem; color:#cbd5e1; display:block; margin-bottom:8px;"></i>
                    ${mesej}
                </td>
            </tr>
        `;
        return;
    }

    const isAdmin = peranan === 'admin';
    const warnaZebra = isAdmin ? '#fff7ed' : '#f8fafc';
    let html = '';

    senarai.forEach((r, idx) => {
        const rowBg = idx % 2 === 0 ? '#ffffff' : warnaZebra;
        const tamatSudah = r.tarikhTamat && new Date(r.tarikhTamat).getTime() < Date.now();
        const warnaTamat = tamatSudah ? '#dc2626' : '#0f766e';
        const cellClass = isAdmin ? 'admin-sejarah-td admin-td' : 'admin-sejarah-td teacher-sejarah-td';
        html += `
            <tr style="background:${rowBg}; border-bottom:1px solid #e2e8f0; transition:background 0.15s ease;">
                <td class="${cellClass}" style="padding:9px 8px; text-align:center; font-weight:600; color:#64748b; border-right:1px solid #e2e8f0; font-size:0.85rem;">${idx + 1}</td>
                <td class="${cellClass}" style="padding:9px 12px; font-weight:bold; color:#1e293b; border-right:1px solid #e2e8f0; font-size:0.85rem; white-space:nowrap;">${r.nama || '-'}</td>
                <td class="${cellClass}" style="padding:9px 12px; color:#475569; border-right:1px solid #e2e8f0; font-size:0.85rem; white-space:nowrap; text-align:center;">${window.formatTarikhLangganan(r.tarikhLangganan)}</td>
                <td class="${cellClass}" style="padding:9px 12px; color:${warnaTamat}; font-weight:bold; border-right:1px solid #e2e8f0; font-size:0.85rem; white-space:nowrap; text-align:center;">${window.formatTarikhLangganan(r.tarikhTamat)}</td>
                <td class="${cellClass}" style="padding:9px 12px; text-align:center; font-size:0.85rem; white-space:nowrap;">
                    <span style="display:inline-block; padding:3px 10px; border-radius:999px; font-weight:bold; font-size:0.78rem; border:1.5px solid ${r.jenisLangganan === 'Percuma' ? '#94a3b8' : '#0f766e'}; background:${r.jenisLangganan === 'Percuma' ? '#f1f5f9' : '#ccfbf1'}; color:${r.jenisLangganan === 'Percuma' ? '#475569' : '#0f766e'};">${r.jenisLangganan || '-'}</span>
                </td>
            </tr>
        `;
    });

    tbody.innerHTML = html;
};

window.muatSejarahLangganan = async function (peranan) {
    if (typeof window.getSubscriptionHistory === 'function') {
        try {
            await window.getSubscriptionHistory();
        } catch (e) {
            console.warn('Ralat memuatkan sejarah langganan:', e);
        }
    }
    window.renderSejarahLangganan(peranan);
};

