window.misi3DNext = function () {
    if (!window.currentMisiModules || window.currentMisiModules.length === 0) return;
    const total = window.currentMisiModules.length;
    window.currentMisiActiveIndex = (window.currentMisiActiveIndex + 1) % total;
    window.updateMisi3DSlots();
};

window.misi3DPrev = function () {
    if (!window.currentMisiModules || window.currentMisiModules.length === 0) return;
    const total = window.currentMisiModules.length;
    window.currentMisiActiveIndex = (window.currentMisiActiveIndex - 1 + total) % total;
    window.updateMisi3DSlots();
};

window.misi3DGoTo = function (idx) {
    if (!window.currentMisiModules) return;
    if (idx >= 0 && idx < window.currentMisiModules.length) {
        window.currentMisiActiveIndex = idx;
        window.updateMisi3DSlots();
    }
};

window.handleMisiCardClick = function (idx) {
    if (!window.currentMisiModules) return;
    const total = window.currentMisiModules.length;
    const activeIdx = window.currentMisiActiveIndex || 0;
    const offset = getMisiCircularOffset(idx, activeIdx, total);

    if (Math.abs(offset) < 0.5) {
        const modul = window.currentMisiModules[idx];
        if (modul.isLocked) {
            alert('Tahap Terkunci!');
        } else {
            window.klikModul(modul.id, modul.displayTitle);
        }
    } else {
        window.misi3DGoTo(idx);
    }
};

window.initMisi3DGestures = function () {
    const stage = document.getElementById('misi-3d-stage');
    if (!stage || stage.dataset.has3dGestures === 'true') return;
    stage.dataset.has3dGestures = 'true';

    let touchStartX = null;
    stage.addEventListener('touchstart', (e) => {
        touchStartX = e.touches[0].clientX;
    }, { passive: true });

    stage.addEventListener('touchend', (e) => {
        if (touchStartX === null) return;
        const diff = touchStartX - e.changedTouches[0].clientX;
        if (diff > 25) {
            window.misi3DNext();
        } else if (diff < -25) {
            window.misi3DPrev();
        }
        touchStartX = null;
    });

    let mouseStartX = null;
    let isMouseDown = false;
    stage.addEventListener('mousedown', (e) => {
        isMouseDown = true;
        mouseStartX = e.clientX;
    });
    window.addEventListener('mouseup', (e) => {
        if (!isMouseDown) return;
        isMouseDown = false;
        if (mouseStartX === null) return;
        const diff = mouseStartX - e.clientX;
        if (diff > 30) {
            window.misi3DNext();
        } else if (diff < -30) {
            window.misi3DPrev();
        }
        mouseStartX = null;
    });
};

if (!window.hasMisi3DResizeListener) {
    window.hasMisi3DResizeListener = true;
    window.addEventListener('resize', () => {
        if (document.getElementById('misi-3d-stage')) {
            window.updateMisi3DSlots();
        }
    });
}
