// --- CABARAN LAIN 3D SWIPER ENGINE ---
window.cabaranLainActiveIndex = 0;
window.cabaranLainModules = [];

window.updateCabaranLainSlots = function () {
    const viewport = document.getElementById('cabaran-lain-viewport');
    const stage = document.getElementById('cabaran-lain-stage');
    if (!viewport || !window.cabaranLainModules || window.cabaranLainModules.length === 0) return;
    const slots = viewport.querySelectorAll('.cabaran-lain-slot');
    const total = window.cabaranLainModules.length;
    const activeIdx = window.cabaranLainActiveIndex || 0;
    const stageWidth = (stage && stage.clientWidth > 0) ? stage.clientWidth : window.innerWidth;
    const isMobile = window.innerWidth <= 768 || stageWidth <= 640;
    const stepX = isMobile ? Math.min(92, Math.floor(stageWidth * 0.26)) : 205;

    slots.forEach((slot, i) => {
        let offset = (i - activeIdx) % total;
        while (offset < -total / 2) offset += total;
        while (offset > total / 2) offset -= total;

        const absOffset = Math.abs(offset);
        const xPos = offset * stepX;
        const rotateY = offset * (isMobile ? -14 : -12);
        const scale = isMobile
            ? Math.max(0.70, 1.05 - absOffset * 0.25)
            : Math.max(0.72, 1.04 - absOffset * 0.22);

        let opacity = 0;
        let isVisible = false;
        if (absOffset < 0.5) {
            opacity = 1;
            isVisible = true;
        } else if (absOffset <= 1.25) {
            opacity = isMobile ? 0.75 : 0.85;
            isVisible = true;
        } else if (absOffset <= 2.2 && !isMobile) {
            opacity = 0.35;
            isVisible = true;
        } else {
            opacity = 0;
            isVisible = false;
        }

        const zIdx = Math.round(30 - absOffset * 8);
        const isCenter = absOffset < 0.5;

        slot.style.transform = 'translate(-50%, -50%) translateX(' + xPos + 'px) rotateY(' + rotateY + 'deg) scale(' + scale + ')';
        slot.style.opacity = opacity;
        slot.style.visibility = isVisible ? 'visible' : 'hidden';
        slot.style.zIndex = zIdx;
        slot.style.pointerEvents = (isVisible && opacity > 0.1) ? 'auto' : 'none';
        slot.style.transition = 'all 0.35s cubic-bezier(0.25, 1, 0.5, 1)';
        slot.style.position = 'absolute';
        slot.style.top = '50%';
        slot.style.left = '50%';
        slot.style.marginTop = '0px';
        slot.style.marginLeft = '0px';

        const node = slot.querySelector('.island-node');
        if (node) {
            if (isCenter) {
                node.classList.add('active-level');
                slot.classList.add('is-center');
                slot.classList.remove('is-side');
            } else {
                node.classList.remove('active-level');
                slot.classList.remove('is-center');
                slot.classList.add('is-side');
            }
        }
    });

    // Update dots
    const dots = document.querySelectorAll('.cabaran-lain-dot');
    dots.forEach((d, i) => {
        const isActive = (i === activeIdx);
        d.classList.toggle('active', isActive);
        if (isActive) {
            d.style.backgroundColor = '#ea580c';
        } else {
            d.style.backgroundColor = '#ffffff';
        }
    });
};

window.cabaranLainNext = function () {
    if (!window.cabaranLainModules || window.cabaranLainModules.length === 0) return;
    const total = window.cabaranLainModules.length;
    window.cabaranLainActiveIndex = (window.cabaranLainActiveIndex + 1) % total;
    window.updateCabaranLainSlots();
};

window.cabaranLainPrev = function () {
    if (!window.cabaranLainModules || window.cabaranLainModules.length === 0) return;
    const total = window.cabaranLainModules.length;
    window.cabaranLainActiveIndex = (window.cabaranLainActiveIndex - 1 + total) % total;
    window.updateCabaranLainSlots();
};

window.cabaranLainGoTo = function (idx) {
    if (!window.cabaranLainModules) return;
    if (idx >= 0 && idx < window.cabaranLainModules.length) {
        window.cabaranLainActiveIndex = idx;
        window.updateCabaranLainSlots();
    }
};

window.initCabaranLainSwipe = function () {
    const stage = document.getElementById('cabaran-lain-stage');
    if (!stage || stage.dataset.hasClGestures === 'true') return;
    stage.dataset.hasClGestures = 'true';

    let touchStartX = null;
    stage.addEventListener('touchstart', (e) => { touchStartX = e.touches[0].clientX; }, { passive: true });
    stage.addEventListener('touchend', (e) => {
        if (touchStartX === null) return;
        const diff = e.changedTouches[0].clientX - touchStartX;
        touchStartX = null;
        if (Math.abs(diff) > 40) {
            if (diff < 0) window.cabaranLainNext();
            else window.cabaranLainPrev();
        }
    });

    let mouseStartX = null;
    stage.addEventListener('mousedown', (e) => {
        mouseStartX = e.clientX;
    });
    stage.addEventListener('mouseup', (e) => {
        if (mouseStartX === null) return;
        const diff = e.clientX - mouseStartX;
        mouseStartX = null;
        if (Math.abs(diff) > 45) {
            if (diff < 0) window.cabaranLainNext();
            else window.cabaranLainPrev();
        }
    });
};

if (!window.hasCabaranLainResizeListener) {
    window.hasCabaranLainResizeListener = true;
    window.addEventListener('resize', () => {
        if (document.getElementById('cabaran-lain-stage')) {
            window.updateCabaranLainSlots();
        }
    });
}

window.handleCabaranLainClick = function (idx) {
    const modules = window.cabaranLainModules;
    if (!modules || !modules[idx]) return;
    const activeIdx = window.cabaranLainActiveIndex || 0;
    if (Math.abs(idx - activeIdx) < 0.5) {
        window.openCabaranLainGame(modules[idx]);
    } else {
        window.cabaranLainGoTo(idx);
    }
};

