window.openCabaranLainGame = function (modul) {
    const modal = document.getElementById('modal-cabaran-lain-game');
    if (!modal) return;
    window.currentExtraChallenge = modul;
    window.clLives = 3;
    const petaId = window.currentPeta || 1;
    const words = EXTRA_WORD_BANKS[petaId] || EXTRA_WORD_BANKS[1];

    const titleEl = document.getElementById('cabaran-lain-game-title');
    if (titleEl) titleEl.innerHTML = `<i class="fa-solid ${modul.icon}"></i> ${modul.title}`;

    const gameArea = document.getElementById('cabaran-lain-game-area');
    if (!gameArea) return;

    // Generate game based on type
    if (modul.type === 'fruit_slash') {
        window.generateFruitSlashGame(gameArea);
    } else if (modul.type === 'basket_catch') {
        window.generateBasketCatchGame(gameArea);
    } else if (modul.type === 'word_search') {
        window.generateWordSearchGame(gameArea, words);
    } else if (modul.type === 'frog_jump' || modul.type === 'missing_pieces') {
        window.generateFrogJumpGame(gameArea);
    } else if (modul.type === 'space_shooter' || modul.type === 'word_builder') {
        window.generateSpaceShooterGame(gameArea);
    } else if (modul.type === 'memory_match') {
        window.generateMemoryMatchGame(gameArea, words);
    } else if (modul.type === 'bird_math') {
        window.generateBirdMathGame(gameArea);
    } else if (modul.type === 'bird_tolak') {
        window.generateBirdTolakGame(gameArea);
    } else if (modul.type === 'speed_quiz') {
        window.generateSpeedQuizGame(gameArea, words);
    } else if (modul.type === 'vowel_whack') {
        window.generateVowelWhackGame(gameArea, 'vowel');
    } else if (modul.type === 'consonant_whack') {
        window.generateVowelWhackGame(gameArea, 'consonant');
    } else if (modul.type === 'bina_ayat' || modul.type === 'ular_ayat' || modul.type === 'burung_ayat' || modul.type === 'burung_ayat') {
        window.generateUlarAyatGame(gameArea);
    } else if (modul.type === 'sambung_ayat' || modul.type === 'lastik_burung') {
        window.generateLastikBurungGame(gameArea);
    } else if (modul.type === 'teka_petikan' || modul.type === 'meriam_kata') {
        window.generateMeriamKataGame(gameArea);
    } else if (modul.type === 'detektif_petikan' || modul.type === 'katak_lompat') {
        window.generateKatakLompatGame(gameArea);
    } else if (modul.type === 'kembara_cerita' || modul.type === 'tangkap_cerita') {
        window.generateTangkapCeritaGame(gameArea);
    }

    const isBacaanBergred = (petaId === 4) || ['burung_ayat', 'ular_ayat', 'bina_ayat', 'lastik_burung', 'sambung_ayat', 'meriam_kata', 'teka_petikan', 'katak_lompat', 'detektif_petikan', 'tangkap_cerita', 'kembara_cerita'].includes(modul.type);
    if (isBacaanBergred) {
        modal.classList.add('is-bacaan-bergred');
    } else {
        modal.classList.remove('is-bacaan-bergred');
    }

    document.body.classList.add('hide-top-banner');
    const topBanner = document.getElementById('teacher-top-banner');
    if (topBanner) topBanner.style.display = 'none';

    modal.style.display = 'flex';
    modal.classList.add('modal-open');
};

