// ==========================================
// TETAK BUAH GENAP — FRUIT NINJA MATH GAME
// ==========================================
window.generateFruitSlashGame = function (area) {
    if (!area) area = document.getElementById('cabaran-lain-game-area');
    if (!area) return;

    if (window.fsAnimId) { cancelAnimationFrame(window.fsAnimId); window.fsAnimId = null; }
    if (window.fsSpawnTimeout) { clearTimeout(window.fsSpawnTimeout); window.fsSpawnTimeout = null; }

    window.fsScore = 0;
    window.fsTarget = 10;
    window.clLives = 3;

    let html = '';
    // Header with hearts and score (Buah Genap: 0/10)
    html += window.renderCabaranLainHeader(window.fsScore, window.fsTarget, `Buah Genap: ${window.fsScore}/${window.fsTarget}`);

    // Top instruction text
    html += '<div class="cl-instruction-wrap">';
    html += '<div class="cl-instruction-box">';
    html += 'Tetak nombor <span style="color:#ea580c;font-size:1.15rem;font-weight:900;margin:0 4px;">genap</span> sahaja!';
    html += '</div>';
    html += '</div>';

    // Canvas element
    html += '<div class="cl-canvas-wrap" style="position:relative;width:100%;max-width:340px;margin:0 auto 10px auto;">';
    html += '<canvas id="fs-canvas" width="360" height="340" style="width:100%;max-width:340px;aspect-ratio:360/340;border-radius:18px;border:3.5px solid #ea580c;box-shadow:0 5px 0 #c2410c;background:#fef3c7;display:block;margin:0 auto;cursor:crosshair;user-select:none;-webkit-user-select:none;touch-action:none;"></canvas>';
    html += '</div>';

    area.innerHTML = html;

    setTimeout(() => {
        window.initFruitSlashCanvas();
    }, 50);
};

window.initFruitSlashCanvas = function () {
    const canvas = document.getElementById('fs-canvas');
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const C_WIDTH = 360;
    const C_HEIGHT = 340;

    let gameState = 'ready'; // 'ready' | 'playing' | 'done'
    let fruits = [];
    let slicedHalves = [];
    let particles = [];
    let floatingTexts = [];
    let bladeTrail = [];
    let isPointerDown = false;
    let lastSlashSoundTime = 0;
    let flashRedTimer = 0;
    let pulseTimer = 0;

    const FRUIT_TYPES = [
        { type: 'orange', name: 'Oren', color1: '#fb923c', color2: '#ea580c', pulp: '#fed7aa', juice: '#f97316', rind: '#c2410c' },
        { type: 'watermelon', name: 'Tembikai', color1: '#22c55e', color2: '#15803d', pulp: '#ef4444', juice: '#ef4444', rind: '#14532d' },
        { type: 'apple', name: 'Epal', color1: '#f87171', color2: '#dc2626', pulp: '#fef08a', juice: '#dc2626', rind: '#991b1b' },
        { type: 'lemon', name: 'Lemon', color1: '#fde047', color2: '#eab308', pulp: '#fef08a', juice: '#eab308', rind: '#ca8a04' }
    ];

    function spawnFruit() {
        if (gameState !== 'playing') return;

        // Choose 1 or 2 fruits
        const count = (fruits.length < 2 && Math.random() < 0.35) ? 2 : 1;
        for (let k = 0; k < count; k++) {
            const fType = FRUIT_TYPES[Math.floor(Math.random() * FRUIT_TYPES.length)];

            // 60% Even, 40% Odd
            const isEven = Math.random() < 0.60;
            const evens = [2, 4, 6, 8, 10];
            const odds = [1, 3, 5, 7, 9];
            const num = isEven
                ? evens[Math.floor(Math.random() * evens.length)]
                : odds[Math.floor(Math.random() * odds.length)];

            const startX = 60 + Math.random() * (C_WIDTH - 120);
            const startY = C_HEIGHT + 35;
            // Arc towards middle
            const targetX = C_WIDTH / 2 + (Math.random() - 0.5) * 120;
            const vx = (targetX - startX) * 0.016 + (Math.random() - 0.5) * 1.2;
            const vy = - (7.2 + Math.random() * 1.8);

            fruits.push({
                x: startX,
                y: startY,
                vx: vx,
                vy: vy,
                r: 27,
                rot: Math.random() * Math.PI,
                vRot: (Math.random() - 0.5) * 0.06,
                type: fType,
                num: num,
                isEven: isEven,
                sliced: false
            });
        }

        // Schedule next spawn
        const nextDelay = 1300 + Math.random() * 600;
        window.fsSpawnTimeout = setTimeout(spawnFruit, nextDelay);
    }

    function addBladePoint(x, y) {
        const now = performance.now();
        bladeTrail.push({ x: x, y: y, t: now });

        if (bladeTrail.length > 2) {
            const p1 = bladeTrail[bladeTrail.length - 2];
            const dist = Math.hypot(x - p1.x, y - p1.y);
            if (dist > 16 && now - lastSlashSoundTime > 140) {
                if (window.playSlashSound) window.playSlashSound();
                lastSlashSoundTime = now;
            }
        }
    }

    function getCanvasCoords(e) {
        const rect = canvas.getBoundingClientRect();
        const scaleX = canvas.width / rect.width;
        const scaleY = canvas.height / rect.height;
        return {
            x: (e.clientX - rect.left) * scaleX,
            y: (e.clientY - rect.top) * scaleY
        };
    }

    canvas.onpointerdown = function (e) {
        e.preventDefault();
        isPointerDown = true;
        const pt = getCanvasCoords(e);
        bladeTrail = [];
        addBladePoint(pt.x, pt.y);

        if (gameState === 'ready') {
            gameState = 'playing';
            if (window.playBubble) window.playBubble();
            spawnFruit();
        }
    };

    canvas.onpointermove = function (e) {
        if (!isPointerDown) return;
        e.preventDefault();
        const pt = getCanvasCoords(e);
        addBladePoint(pt.x, pt.y);

        if (gameState === 'playing') {
            checkBladeIntersection();
        }
    };

    canvas.onpointerup = function (e) {
        e.preventDefault();
        isPointerDown = false;
    };

    canvas.onpointercancel = function (e) {
        isPointerDown = false;
    };

    function distToSegment(px, py, x1, y1, x2, y2) {
        const l2 = (x2 - x1) * (x2 - x1) + (y2 - y1) * (y2 - y1);
        if (l2 === 0) return Math.hypot(px - x1, py - y1);
        let t = ((px - x1) * (x2 - x1) + (py - y1) * (y2 - y1)) / l2;
        t = Math.max(0, Math.min(1, t));
        return Math.hypot(px - (x1 + t * (x2 - x1)), py - (y1 + t * (y2 - y1)));
    }

    function checkBladeIntersection() {
        if (bladeTrail.length < 2) return;
        const p2 = bladeTrail[bladeTrail.length - 1];
        const p1 = bladeTrail[bladeTrail.length - 2];

        fruits.forEach(f => {
            if (f.sliced) return;
            const d = distToSegment(f.x, f.y, p1.x, p1.y, p2.x, p2.y);
            if (d <= f.r + 4) {
                sliceFruit(f, p1, p2);
            }
        });
    }

    function sliceFruit(f, p1, p2) {
        f.sliced = true;
        const slashAngle = Math.atan2(p2.y - p1.y, p2.x - p1.x);

        // Spawn Sliced Halves
        const normalAngle = slashAngle + Math.PI / 2;
        const spreadSpeed = 2.4 + Math.random() * 1.2;

        slicedHalves.push({
            x: f.x,
            y: f.y,
            vx: f.vx - Math.cos(normalAngle) * spreadSpeed,
            vy: f.vy - 1.2 - Math.sin(normalAngle) * spreadSpeed,
            r: f.r,
            rot: f.rot,
            vRot: -0.09,
            type: f.type,
            side: 'left',
            cutAngle: slashAngle
        });

        slicedHalves.push({
            x: f.x,
            y: f.y,
            vx: f.vx + Math.cos(normalAngle) * spreadSpeed,
            vy: f.vy - 1.2 + Math.sin(normalAngle) * spreadSpeed,
            r: f.r,
            rot: f.rot,
            vRot: 0.09,
            type: f.type,
            side: 'right',
            cutAngle: slashAngle
        });

        // Juice droplet particles
        for (let i = 0; i < 18; i++) {
            const pAngle = slashAngle + (Math.random() - 0.5) * Math.PI;
            const pSpeed = 2.0 + Math.random() * 4.5;
            particles.push({
                x: f.x,
                y: f.y,
                vx: Math.cos(pAngle) * pSpeed,
                vy: Math.sin(pAngle) * pSpeed - 1.0,
                r: 2.5 + Math.random() * 3.5,
                color: f.type.juice,
                life: 24,
                maxLife: 24
            });
        }

        if (f.isEven) {
            // Correct slice!
            window.fsScore++;
            if (window.playBetulSound) window.playBetulSound();
            if (window.triggerConfettiEffect) window.triggerConfettiEffect();

            floatingTexts.push({
                x: f.x,
                y: f.y - 15,
                vy: -1.4,
                text: `${f.num} GENAP!`,
                color: '#10b981',
                alpha: 1,
                scale: 1.1
            });

            // Update Header Score Text
            const scoreBox = document.getElementById('cl-score-box');
            if (scoreBox) {
                scoreBox.textContent = `Buah Genap: ${window.fsScore}/${window.fsTarget}`;
            }

            if (window.fsScore >= window.fsTarget) {
                // WON!
                gameState = 'done';
                if (window.fsAnimId) cancelAnimationFrame(window.fsAnimId);
                if (window.fsSpawnTimeout) clearTimeout(window.fsSpawnTimeout);

                const stars = window.clLives >= 3 ? 3 : window.clLives >= 2 ? 2 : 1;
                const score = Math.round((stars / 3) * 100);
                window.saveCabaranLainScore(window.currentExtraChallenge.id, score, stars);
                setTimeout(() => {
                    window.showCabaranLainStarPopup(score, stars);
                }, 500);
            }
        } else {
            // Odd number mistake!
            window.clLives--;
            window.updateCabaranLainHearts();
            if (window.playSalahSound) window.playSalahSound();
            flashRedTimer = 16;

            floatingTexts.push({
                x: f.x,
                y: f.y - 15,
                vy: -1.4,
                text: `${f.num} GANJIL!`,
                color: '#ef4444',
                alpha: 1,
                scale: 1.1
            });

            if (window.clLives <= 0) {
                gameState = 'done';
                if (window.fsAnimId) cancelAnimationFrame(window.fsAnimId);
                if (window.fsSpawnTimeout) clearTimeout(window.fsSpawnTimeout);
                setTimeout(() => {
                    window.showCabaranLainStarPopup(0, 0);
                }, 500);
            }
        }
    }

    function drawFruit(f) {
        ctx.save();
        ctx.translate(f.x, f.y);
        ctx.rotate(f.rot);

        // Fruit Body
        const grad = ctx.createRadialGradient(-f.r * 0.3, -f.r * 0.3, f.r * 0.1, 0, 0, f.r);
        grad.addColorStop(0, f.type.color1);
        grad.addColorStop(0.85, f.type.color2);
        grad.addColorStop(1, f.type.rind);

        ctx.fillStyle = grad;
        ctx.strokeStyle = f.type.rind;
        ctx.lineWidth = 2.5;
        ctx.beginPath();
        ctx.arc(0, 0, f.r, 0, Math.PI * 2);
        ctx.fill();
        ctx.stroke();

        // Watermelon Stripes
        if (f.type.type === 'watermelon') {
            ctx.strokeStyle = '#14532d';
            ctx.lineWidth = 3;
            ctx.beginPath();
            ctx.arc(0, 0, f.r * 0.82, -Math.PI * 0.6, -Math.PI * 0.1);
            ctx.stroke();
            ctx.beginPath();
            ctx.arc(0, 0, f.r * 0.82, Math.PI * 0.3, Math.PI * 0.8);
            ctx.stroke();
        }

        // Stem and Cute Green Leaf
        ctx.fillStyle = '#15803d';
        ctx.beginPath();
        ctx.ellipse(f.r * 0.5, -f.r * 0.85, 7, 4, 0.4, 0, Math.PI * 2);
        ctx.fill();
        ctx.fillStyle = '#78350f';
        ctx.fillRect(-2, -f.r - 4, 4, 6);

        // Glossy Shine Highlight
        ctx.fillStyle = 'rgba(255, 255, 255, 0.55)';
        ctx.beginPath();
        ctx.ellipse(-f.r * 0.38, -f.r * 0.38, f.r * 0.32, f.r * 0.18, -Math.PI / 4, 0, Math.PI * 2);
        ctx.fill();

        // Bold Crisp Number Badge
        ctx.restore();
        ctx.save();
        ctx.translate(f.x, f.y);

        ctx.font = '900 24px "AtlantaRounded", sans-serif';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.strokeStyle = '#1e1b4b';
        ctx.lineWidth = 4.5;
        ctx.strokeText(f.num, 0, 1);
        ctx.fillStyle = '#ffffff';
        ctx.fillText(f.num, 0, 1);

        ctx.restore();
    }

    function drawSlicedHalf(h) {
        ctx.save();
        ctx.translate(h.x, h.y);
        ctx.rotate(h.rot);

        ctx.beginPath();
        if (h.side === 'left') {
            ctx.arc(0, 0, h.r, Math.PI / 2, Math.PI * 1.5);
        } else {
            ctx.arc(0, 0, h.r, -Math.PI / 2, Math.PI / 2);
        }
        ctx.closePath();

        // Rind & Pulp Fill
        ctx.fillStyle = h.type.pulp;
        ctx.fill();
        ctx.strokeStyle = h.type.rind;
        ctx.lineWidth = 3;
        ctx.stroke();

        // Inner seeds / segments
        ctx.fillStyle = h.type.type === 'watermelon' ? '#0f172a' : h.type.color2;
        const seedOffset = h.side === 'left' ? -h.r * 0.4 : h.r * 0.4;
        ctx.beginPath();
        ctx.arc(seedOffset, 0, 3, 0, Math.PI * 2);
        ctx.arc(seedOffset * 0.7, -8, 2.5, 0, Math.PI * 2);
        ctx.arc(seedOffset * 0.7, 8, 2.5, 0, Math.PI * 2);
        ctx.fill();

        ctx.restore();
    }

    function drawRoundedRect(c, x, y, width, height, radius, fill, stroke, strokeWidth) {
        c.beginPath();
        c.moveTo(x + radius, y);
        c.lineTo(x + width - radius, y);
        c.quadraticCurveTo(x + width, y, x + width, y + radius);
        c.lineTo(x + width, y + height - radius);
        c.quadraticCurveTo(x + width, y + height, x + width - radius, y + height);
        c.lineTo(x + radius, y + height);
        c.quadraticCurveTo(x, y + height, x, y + height - radius);
        c.lineTo(x, y + radius);
        c.quadraticCurveTo(x, y, x + radius, y);
        c.closePath();
        if (fill) { c.fillStyle = fill; c.fill(); }
        if (stroke) { c.strokeStyle = stroke; c.lineWidth = strokeWidth || 2; c.stroke(); }
    }

    function gameLoop() {
        // Clear screen with warm sunrise sky
        const skyGrad = ctx.createLinearGradient(0, 0, 0, C_HEIGHT);
        skyGrad.addColorStop(0, '#fed7aa');
        skyGrad.addColorStop(0.6, '#fef3c7');
        skyGrad.addColorStop(1, '#fffbeb');
        ctx.fillStyle = skyGrad;
        ctx.fillRect(0, 0, C_WIDTH, C_HEIGHT);

        // Soft background clouds
        ctx.fillStyle = 'rgba(255, 255, 255, 0.7)';
        ctx.beginPath();
        ctx.arc(60, 60, 24, 0, Math.PI * 2);
        ctx.arc(80, 52, 28, 0, Math.PI * 2);
        ctx.arc(102, 60, 20, 0, Math.PI * 2);
        ctx.fill();

        ctx.beginPath();
        ctx.arc(280, 85, 20, 0, Math.PI * 2);
        ctx.arc(300, 78, 24, 0, Math.PI * 2);
        ctx.arc(320, 85, 18, 0, Math.PI * 2);
        ctx.fill();

        // Flash Red on Mistake
        if (flashRedTimer > 0) {
            flashRedTimer--;
            ctx.fillStyle = `rgba(239, 68, 68, ${flashRedTimer * 0.025})`;
            ctx.fillRect(0, 0, C_WIDTH, C_HEIGHT);
        }

        // Update & Draw Active Fruits
        if (gameState === 'playing') {
            for (let i = fruits.length - 1; i >= 0; i--) {
                const f = fruits[i];
                f.x += f.vx;
                f.vy += 0.14; // Gravity
                f.y += f.vy;
                f.rot += f.vRot;

                if (!f.sliced) {
                    drawFruit(f);
                }

                // Despawn if fallen below screen
                if (f.y > C_HEIGHT + 60) {
                    fruits.splice(i, 1);
                }
            }
        }

        // Update & Draw Sliced Halves
        for (let i = slicedHalves.length - 1; i >= 0; i--) {
            const h = slicedHalves[i];
            h.x += h.vx;
            h.vy += 0.16; // Gravity
            h.y += h.vy;
            h.rot += h.vRot;
            drawSlicedHalf(h);

            if (h.y > C_HEIGHT + 60) {
                slicedHalves.splice(i, 1);
            }
        }

        // Update & Draw Juice Particles
        for (let i = particles.length - 1; i >= 0; i--) {
            const p = particles[i];
            p.x += p.vx;
            p.y += p.vy;
            p.vy += 0.12;
            p.life--;

            if (p.life <= 0) {
                particles.splice(i, 1);
            } else {
                ctx.save();
                ctx.globalAlpha = p.life / p.maxLife;
                ctx.fillStyle = p.color;
                ctx.beginPath();
                ctx.arc(p.x, p.y, p.r, 0, Math.PI * 2);
                ctx.fill();
                ctx.restore();
            }
        }

        // Update & Draw Floating Feedback Text
        for (let i = floatingTexts.length - 1; i >= 0; i--) {
            const ft = floatingTexts[i];
            ft.y += ft.vy;
            ft.alpha -= 0.035;

            if (ft.alpha <= 0) {
                floatingTexts.splice(i, 1);
            } else {
                ctx.save();
                ctx.globalAlpha = ft.alpha;
                ctx.font = '900 18px "AtlantaRounded", sans-serif';
                ctx.textAlign = 'center';
                ctx.fillStyle = ft.color;
                ctx.strokeStyle = '#ffffff';
                ctx.lineWidth = 3;
                ctx.strokeText(ft.text, ft.x, ft.y);
                ctx.fillText(ft.text, ft.x, ft.y);
                ctx.restore();
            }
        }

        // Draw Glowing Blade Trail
        const now = performance.now();
        bladeTrail = bladeTrail.filter(pt => now - pt.t < 150);

        if (bladeTrail.length > 1) {
            ctx.save();
            ctx.lineCap = 'round';
            ctx.lineJoin = 'round';

            // Outer cyan glow
            ctx.shadowColor = '#38bdf8';
            ctx.shadowBlur = 12;
            ctx.strokeStyle = 'rgba(56, 189, 248, 0.7)';
            ctx.lineWidth = 7;
            ctx.beginPath();
            ctx.moveTo(bladeTrail[0].x, bladeTrail[0].y);
            for (let i = 1; i < bladeTrail.length; i++) {
                ctx.lineTo(bladeTrail[i].x, bladeTrail[i].y);
            }
            ctx.stroke();

            // Inner bright white laser
            ctx.shadowBlur = 0;
            ctx.strokeStyle = '#ffffff';
            ctx.lineWidth = 3.5;
            ctx.beginPath();
            ctx.moveTo(bladeTrail[0].x, bladeTrail[0].y);
            for (let i = 1; i < bladeTrail.length; i++) {
                ctx.lineTo(bladeTrail[i].x, bladeTrail[i].y);
            }
            ctx.stroke();

            ctx.restore();
        }

        // Ready Banner Overlay with Modern Vector Touch/Swipe Icon
        if (gameState === 'ready') {
            pulseTimer += 0.05;
            const pulseScale = 1 + Math.sin(pulseTimer) * 0.03;

            ctx.save();
            ctx.translate(C_WIDTH / 2, 160);
            ctx.scale(pulseScale, pulseScale);

            // Translucent rounded badge card
            drawRoundedRect(ctx, -140, -38, 280, 76, 18, 'rgba(255,255,255,0.96)', '#ea580c', 3.5);

            // Modern Vector Pointer Hand Icon
            ctx.save();
            ctx.translate(-96, 0);

            // Soft circular background for icon
            ctx.fillStyle = '#ffedd5';
            ctx.beginPath();
            ctx.arc(0, 0, 19, 0, Math.PI * 2);
            ctx.fill();
            ctx.strokeStyle = '#ea580c';
            ctx.lineWidth = 2;
            ctx.stroke();

            // Animated Tap Ripples at fingertip
            const rippleR = 4 + (Math.sin(pulseTimer * 3) + 1) * 2.2;
            ctx.strokeStyle = 'rgba(234, 88, 12, 0.7)';
            ctx.lineWidth = 1.8;
            ctx.beginPath();
            ctx.arc(0, -9, rippleR, 0, Math.PI * 2);
            ctx.stroke();

            // Fingertip tap center dot
            ctx.fillStyle = '#ea580c';
            ctx.beginPath();
            ctx.arc(0, -9, 2.5, 0, Math.PI * 2);
            ctx.fill();

            // Clean Vector Hand Pointer Shape
            ctx.save();
            ctx.translate(0, 1);
            ctx.fillStyle = '#ea580c';
            ctx.strokeStyle = '#ffffff';
            ctx.lineWidth = 1.5;

            ctx.beginPath();
            // Index finger pointing up
            ctx.moveTo(-2.5, -9);
            ctx.arcTo(-2.5, -11.5, 0, -11.5, 2.5);
            ctx.arcTo(2.5, -11.5, 2.5, -9, 2.5);
            ctx.lineTo(2.5, -2);
            // Middle, ring, pinky knuckles
            ctx.lineTo(5.5, -2);
            ctx.arcTo(7.5, -2, 7.5, 0, 2);
            ctx.lineTo(7.5, 4.5);
            ctx.arcTo(7.5, 7.5, 4.5, 7.5, 2);
            // Palm base
            ctx.lineTo(-2, 7.5);
            ctx.arcTo(-5, 7.5, -5, 4.5, 2);
            // Thumb
            ctx.lineTo(-5, 2);
            ctx.lineTo(-7, 0.5);
            ctx.arcTo(-8, -1.5, -6, -2.5, 2);
            ctx.lineTo(-2.5, -2);
            ctx.closePath();
            ctx.fill();
            ctx.stroke();

            // Finger separation lines
            ctx.strokeStyle = '#ffffff';
            ctx.lineWidth = 1.2;
            ctx.beginPath();
            ctx.moveTo(2.5, 0);
            ctx.lineTo(6.5, 0);
            ctx.moveTo(2.5, 3);
            ctx.lineTo(6.5, 3);
            ctx.stroke();

            ctx.restore();
            ctx.restore();

            // Clean typography
            ctx.fillStyle = '#c2410c';
            ctx.font = '900 16px "AtlantaRounded", sans-serif';
            ctx.textAlign = 'left';
            ctx.textBaseline = 'middle';
            ctx.fillText('Ketik untuk mula!', -68, -8);

            ctx.fillStyle = '#475569';
            ctx.font = '700 12px "AtlantaRounded", sans-serif';
            ctx.fillText('Leret jari untuk tetak buah genap', -68, 14);

            ctx.restore();
        }

        if (gameState !== 'done') {
            window.fsAnimId = requestAnimationFrame(gameLoop);
        }
    }

    // Start loop
    window.fsAnimId = requestAnimationFrame(gameLoop);
};

// === GAME 1: WORD SEARCH ===
window.generateWordSearchGame = function (area, words) {
    if (!area) area = document.getElementById('cabaran-lain-game-area');
    if (!area) return;

    const size = 6;
    const petaId = window.currentPeta || 2;

    // Choose pool based on current map
    let wordSource = [];
    if (petaId === 2) {
        wordSource = (EXTRA_WORD_BANKS && EXTRA_WORD_BANKS[2]) ? EXTRA_WORD_BANKS[2] : (words || []);
    } else if (petaId === 3) {
        wordSource = (EXTRA_WORD_BANKS && EXTRA_WORD_BANKS[3]) ? EXTRA_WORD_BANKS[3] : (words || []);
    } else if (petaId === 4) {
        wordSource = (EXTRA_WORD_BANKS && EXTRA_WORD_BANKS[4]) ? EXTRA_WORD_BANKS[4] : (words || []);
    } else {
        wordSource = (EXTRA_WORD_BANKS && EXTRA_WORD_BANKS[1]) ? EXTRA_WORD_BANKS[1] : (words || []);
    }

    // Filter words that fit inside 6x6 grid and randomly pick 4
    const validWords = wordSource
        .map(w => w.toLowerCase().trim())
        .filter(w => w.length >= 3 && w.length <= size);

    const shuffledWords = Array.from(new Set(validWords)).sort(() => Math.random() - 0.5);
    const selectedWords = shuffledWords.slice(0, 4);

    const grid = Array.from({ length: size }, () => Array.from({ length: size }, () => ''));
    const alpha = 'abcdefghijklmnopqrstuvwxyz';

    // Place words horizontally, vertically, or diagonally
    selectedWords.forEach(word => {
        let placed = false;
        const directions = ['h', 'v', 'd'];
        for (let attempt = 0; attempt < 80 && !placed; attempt++) {
            const dir = directions[Math.floor(Math.random() * (attempt < 50 ? 2 : 3))]; // h, v, or d
            let maxR = size, maxC = size;
            if (dir === 'h') { maxR = size; maxC = size - word.length; }
            else if (dir === 'v') { maxR = size - word.length; maxC = size; }
            else if (dir === 'd') { maxR = size - word.length; maxC = size - word.length; }

            if (maxR <= 0 || maxC <= 0) continue;
            const r = Math.floor(Math.random() * maxR);
            const c = Math.floor(Math.random() * maxC);

            let canPlace = true;
            for (let k = 0; k < word.length; k++) {
                const cr = (dir === 'v' || dir === 'd') ? r + k : r;
                const cc = (dir === 'h' || dir === 'd') ? c + k : c;
                if (grid[cr][cc] !== '' && grid[cr][cc] !== word[k]) {
                    canPlace = false;
                    break;
                }
            }

            if (canPlace) {
                for (let k = 0; k < word.length; k++) {
                    const cr = (dir === 'v' || dir === 'd') ? r + k : r;
                    const cc = (dir === 'h' || dir === 'd') ? c + k : c;
                    grid[cr][cc] = word[k];
                }
                placed = true;
            }
        }
    });

    // Fill empty cells with random alphabet
    for (let r = 0; r < size; r++) {
        for (let c = 0; c < size; c++) {
            if (grid[r][c] === '') grid[r][c] = alpha[Math.floor(Math.random() * 26)];
        }
    }

    const WORD_COLORS = [
        { bg: '#e0e7ff', border: '#6366f1', text: '#3730a3', activeBg: '#6366f1' }, // Indigo
        { bg: '#fce7f3', border: '#ec4899', text: '#831843', activeBg: '#ec4899' }, // Pink
        { bg: '#fef3c7', border: '#f59e0b', text: '#78350f', activeBg: '#f59e0b' }, // Amber
        { bg: '#ccfbf1', border: '#0d9488', text: '#134e4a', activeBg: '#0d9488' }  // Teal
    ];

    window.wsFoundWords = [];
    window.wsTargetWords = selectedWords;
    window.wsWordColors = {};
    selectedWords.forEach((w, i) => {
        window.wsWordColors[w] = WORD_COLORS[i % WORD_COLORS.length];
    });

    let html = '';

    // Instruction subtitle
    html += '<div class="cl-instruction-wrap">';
    html += '<div class="cl-instruction-box">';
    html += 'Tarik huruf untuk cari perkataan di bawah!';
    html += '</div>';
    html += '</div>';

    // Colorful word badges at top
    html += `<div id="ws-word-list" style="margin-bottom:14px;display:flex;flex-wrap:wrap;gap:8px;justify-content:center;max-width:340px;margin-left:auto;margin-right:auto;">`;
    selectedWords.forEach((w, i) => {
        const col = window.wsWordColors[w];
        html += `<span id="ws-word-${w}" style="padding:6px 14px;border-radius:14px;background:${col.bg};font-weight:900;font-size:0.92rem;color:${col.text};border:2.5px solid ${col.border};box-shadow:0 3px 0 ${col.border};transition:all 0.3s;font-family:'AtlantaRounded',sans-serif;user-select:none;">${w}</span>`;
    });
    html += `</div>`;

    // 6x6 Letter Grid
    html += `<div id="ws-grid" style="display:grid;grid-template-columns:repeat(${size},1fr);gap:5px;max-width:320px;margin:0 auto;touch-action:none;user-select:none;-webkit-user-select:none;">`;
    for (let r = 0; r < size; r++) {
        for (let c = 0; c < size; c++) {
            html += `<div class="ws-cell" data-r="${r}" data-c="${c}" data-letter="${grid[r][c]}" style="width:100%;aspect-ratio:1;display:flex;align-items:center;justify-content:center;font-weight:900;font-size:1.2rem;background:#ffffff;color:#1e1b4b;border:2.5px solid #cbd5e1;box-shadow:0 3px 0 #cbd5e1;border-radius:12px;cursor:pointer;user-select:none;-webkit-user-select:none;transition:transform 0.15s, background 0.15s, border-color 0.15s;font-family:'AtlantaRounded',sans-serif;">${grid[r][c]}</div>`;
        }
    }
    html += `</div>`;
    html += `<div id="ws-result" style="margin-top:10px;text-align:center;font-weight:900;font-size:1rem;min-height:24px;font-family:'AtlantaRounded',sans-serif;"></div>`;

    area.innerHTML = html;

    // Attach Drag / Swipe Gesture Engine
    setTimeout(() => {
        window.initWordSearchGestures();
    }, 50);
};

window.initWordSearchGestures = function () {
    const gridEl = document.getElementById('ws-grid');
    if (!gridEl) return;

    let isDragging = false;
    let startR = null;
    let startC = null;
    let currentLineCells = [];

    function getCellFromPoint(clientX, clientY) {
        const el = document.elementFromPoint(clientX, clientY);
        if (!el) return null;
        const cell = el.closest('.ws-cell');
        if (!cell || !gridEl.contains(cell)) return null;
        return {
            el: cell,
            r: parseInt(cell.dataset.r, 10),
            c: parseInt(cell.dataset.c, 10),
            letter: cell.dataset.letter
        };
    }

    function calculateLine(r1, c1, r2, c2) {
        const dr = r2 - r1;
        const dc = c2 - c1;
        const len = Math.max(Math.abs(dr), Math.abs(dc));
        if (len === 0) return [{ r: r1, c: c1 }];

        // Check if along horizontal, vertical, or 45-degree diagonal
        const isHorizontal = dr === 0;
        const isVertical = dc === 0;
        const isDiagonal = Math.abs(dr) === Math.abs(dc);

        if (!isHorizontal && !isVertical && !isDiagonal) {
            // Snap to dominant direction
            if (Math.abs(dr) > Math.abs(dc) * 1.8) {
                c2 = c1;
            } else if (Math.abs(dc) > Math.abs(dr) * 1.8) {
                r2 = r1;
            } else {
                const diagLen = Math.min(Math.abs(dr), Math.abs(dc));
                r2 = r1 + Math.sign(dr) * diagLen;
                c2 = c1 + Math.sign(dc) * diagLen;
            }
        }

        const stepR = Math.sign(r2 - r1);
        const stepC = Math.sign(c2 - c1);
        const steps = Math.max(Math.abs(r2 - r1), Math.abs(c2 - c1));

        const cells = [];
        for (let i = 0; i <= steps; i++) {
            cells.push({ r: r1 + i * stepR, c: c1 + i * stepC });
        }
        return cells;
    }

    function highlightSelectedLine(lineCoords) {
        // Clear previous un-found selection
        const allCells = gridEl.querySelectorAll('.ws-cell');
        allCells.forEach(cell => {
            if (cell.dataset.found !== 'true') {
                cell.classList.remove('ws-cell-selected');
                cell.style.removeProperty('background');
                cell.style.removeProperty('color');
                cell.style.removeProperty('border-color');
                cell.style.removeProperty('box-shadow');
                cell.style.removeProperty('transform');
                cell.style.background = '#ffffff';
                cell.style.color = '#1e1b4b';
                cell.style.borderColor = '#cbd5e1';
                cell.style.boxShadow = '0 2px 0 #cbd5e1';
                cell.style.transform = 'scale(1)';
            } else {
                const bg = cell.dataset.color || '#10b981';
                const border = cell.dataset.border || '#059669';
                cell.style.setProperty('background', bg, 'important');
                cell.style.setProperty('color', '#ffffff', 'important');
                cell.style.setProperty('border-color', border, 'important');
                cell.style.setProperty('box-shadow', `0 3px 0 ${border}`, 'important');
                cell.style.setProperty('transform', 'scale(1)', 'important');
            }
        });

        currentLineCells = [];
        lineCoords.forEach(pt => {
            const cell = gridEl.querySelector(`.ws-cell[data-r="${pt.r}"][data-c="${pt.c}"]`);
            if (cell) {
                currentLineCells.push(cell);
                if (cell.dataset.found !== 'true') {
                    cell.classList.add('ws-cell-selected');
                    cell.style.setProperty('background', '#8b5cf6', 'important');
                    cell.style.setProperty('color', '#ffffff', 'important');
                    cell.style.setProperty('border-color', '#6d28d9', 'important');
                    cell.style.setProperty('box-shadow', '0 3px 0 #6d28d9', 'important');
                    cell.style.setProperty('transform', 'scale(1.08)', 'important');
                }
            }
        });
    }

    function onPointerStart(e) {
        e.preventDefault();
        const pt = getCellFromPoint(e.clientX, e.clientY);
        if (!pt) return;

        isDragging = true;
        startR = pt.r;
        startC = pt.c;
        if (window.playBubble) window.playBubble();
        highlightSelectedLine([{ r: startR, c: startC }]);
    }

    function onPointerMove(e) {
        if (!isDragging) return;
        e.preventDefault();
        const pt = getCellFromPoint(e.clientX, e.clientY);
        if (!pt) return;

        const line = calculateLine(startR, startC, pt.r, pt.c);
        highlightSelectedLine(line);
    }

    function onPointerEnd(e) {
        if (!isDragging) return;
        isDragging = false;

        // Form string from current line
        let wordForward = '';
        currentLineCells.forEach(c => { wordForward += (c.dataset.letter || ''); });
        const wordBackward = wordForward.split('').reverse().join('');

        let matchedWord = null;
        if (window.wsTargetWords.includes(wordForward) && !window.wsFoundWords.includes(wordForward)) {
            matchedWord = wordForward;
        } else if (window.wsTargetWords.includes(wordBackward) && !window.wsFoundWords.includes(wordBackward)) {
            matchedWord = wordBackward;
        }

        if (matchedWord) {
            // MATCH FOUND! (Auto-detect Betul!)
            window.wsFoundWords.push(matchedWord);
            const col = window.wsWordColors[matchedWord] || { activeBg: '#10b981', border: '#059669' };

            // Lock grid cells with color
            currentLineCells.forEach(c => {
                c.dataset.found = 'true';
                c.dataset.color = col.activeBg;
                c.dataset.border = col.border;
                c.classList.add('ws-cell-found');
                c.classList.remove('ws-cell-selected');
                c.style.setProperty('background', col.activeBg, 'important');
                c.style.setProperty('color', '#ffffff', 'important');
                c.style.setProperty('border-color', col.border, 'important');
                c.style.setProperty('box-shadow', `0 3px 0 ${col.border}`, 'important');
                c.style.setProperty('transform', 'scale(1)', 'important');
            });

            // Update top pill tag
            const tag = document.getElementById('ws-word-' + matchedWord);
            if (tag) {
                tag.style.background = col.activeBg;
                tag.style.color = '#ffffff';
                tag.style.borderColor = col.border;
                tag.style.boxShadow = `0 3px 0 ${col.border}`;
                tag.innerHTML = `<i class="fa-solid fa-check" style="margin-right:4px;"></i> ${matchedWord}`;
                tag.style.transform = 'scale(1.08)';
                setTimeout(() => { if (tag) tag.style.transform = 'scale(1)'; }, 200);
            }

            if (window.playBetulSound) window.playBetulSound();
            if (window.triggerConfettiEffect) window.triggerConfettiEffect();

            // Check if all found
            if (window.wsFoundWords.length === window.wsTargetWords.length) {
                const stars = 3;
                const score = 100;
                window.saveCabaranLainScore(window.currentExtraChallenge.id, score, stars);
                setTimeout(() => {
                    window.showCabaranLainStarPopup(score, stars);
                }, 500);
            }
        } else {
            // Not match -> reset selection smoothly
            currentLineCells.forEach(c => {
                if (c.dataset.found !== 'true') {
                    c.style.setProperty('background', '#fee2e2', 'important');
                    c.style.setProperty('border-color', '#fca5a5', 'important');
                    c.style.setProperty('box-shadow', '0 3px 0 #fca5a5', 'important');
                    setTimeout(() => {
                        if (c.dataset.found !== 'true') {
                            c.classList.remove('ws-cell-selected');
                            c.style.removeProperty('background');
                            c.style.removeProperty('color');
                            c.style.removeProperty('border-color');
                            c.style.removeProperty('box-shadow');
                            c.style.removeProperty('transform');
                            c.style.background = '#ffffff';
                            c.style.color = '#1e1b4b';
                            c.style.borderColor = '#cbd5e1';
                            c.style.boxShadow = '0 2px 0 #cbd5e1';
                            c.style.transform = 'scale(1)';
                        }
                    }, 250);
                }
            });
        }
    }

    gridEl.onpointerdown = onPointerStart;
    gridEl.onpointermove = onPointerMove;
    window.addEventListener('pointerup', onPointerEnd);
    window.addEventListener('pointercancel', onPointerEnd);
};

