function sebutTeksPermainan(teks, audioPath, onEnd) {
    window.unlockMobileAudioSubsystem();
    if (audioPath) {
        if (typeof window.sebutAudio === 'function') {
            window.sebutAudio(audioPath, onEnd);
            return;
        }
    }
    if (!teks) return;
    if (typeof window.sebutAudio === 'function') {
        window.sebutAudio(teks, onEnd);
        return;
    }
    if (!('speechSynthesis' in window)) {
        if (typeof onEnd === 'function') onEnd();
        return;
    }
    try {
        window.speechSynthesis.cancel();
        const u = new SpeechSynthesisUtterance(teks);
        u.lang = 'ms-MY';
        u.rate = 0.88;
        u.pitch = 1.05;
        if (typeof onEnd === 'function') {
            u.onend = onEnd;
            u.onerror = onEnd;
        }
        window.speechSynthesis.speak(u);
    } catch (e) {
        if (typeof onEnd === 'function') onEnd();
    }
}

