// ============================================================================
// 1. GAME 1: BURUNG PATUK AYAT (BIRD PECKING WORDS TO COMPLETE SENTENCES)
// ============================================================================
window.generateBurungPatukAyatGame = function (area) {
    if (!area) area = document.getElementById('cabaran-lain-game-area');
    if (!area) return;

    if (window.bpaAnimId) { cancelAnimationFrame(window.bpaAnimId); window.bpaAnimId = null; }
    if (window.bpaTimer) { clearInterval(window.bpaTimer); window.bpaTimer = null; }
    if (window.bpaKeyHandler) { window.removeEventListener('keydown', window.bpaKeyHandler); window.bpaKeyHandler = null; }

    window.bpaQuestions = [...ARKED_DATA_AYAT_PENDEK].sort(() => Math.random() - 0.5).slice(0, 5);
    window.bpaCurrent = 0;
    window.bpaTotal = 5;
    window.clLives = 3;

    window.renderBurungPatukAyatQuestion(area);
};

// Backwards compatibility alias
window.generateUlarAyatGame = window.generateBurungPatukAyatGame;

window.renderBurungPatukAyatQuestion = function (area) {
    if (!area) area = document.getElementById('cabaran-lain-game-area');
    if (!area) return;

    if (window.bpaAnimId) { cancelAnimationFrame(window.bpaAnimId); window.bpaAnimId = null; }
    if (window.bpaTimer) { clearInterval(window.bpaTimer); window.bpaTimer = null; }
    if (window.bpaKeyHandler) { window.removeEventListener('keydown', window.bpaKeyHandler); window.bpaKeyHandler = null; }

    if (window.clLives <= 0) {
        window.showCabaranLainStarPopup(0, 0);
        return;
    }
    if (window.bpaCurrent >= window.bpaTotal) {
        const stars = window.clLives >= 3 ? 3 : (window.clLives >= 2 ? 2 : 1);
        const score = Math.round((stars / 3) * 100);
        if (window.currentExtraChallenge && window.currentExtraChallenge.id) {
            window.saveCabaranLainScore(window.currentExtraChallenge.id, score, stars);
        }
        setTimeout(() => { window.showCabaranLainStarPopup(score, stars); }, 350);
        return;
    }

    const q = window.bpaQuestions[window.bpaCurrent];
    const cleanWords = q.text.replace(/\./g, '').trim().split(/\s+/);
    window.bpaTargetWords = cleanWords;
    window.bpaTargetIndex = 0;

    let html = window.renderCabaranLainHeader(window.bpaCurrent + 1, window.bpaTotal);

    // Sentence progress indicators
    const progressPills = cleanWords.map((w, idx) => {
        if (idx === 0) {
            return `<span id="bpa-pill-${idx}" style="background:#fef08a; color:#854d0e; border:1.5px solid #eab308; border-radius:6px; padding:2px 8px; font-size:0.82rem; font-weight:900; font-family:'AtlantaRoundedBlack', 'AtlantaRounded', sans-serif;">${w}</span>`;
        }
        return `<span id="bpa-pill-${idx}" style="background:#f1f5f9; color:#64748b; border:1.5px dashed #cbd5e1; border-radius:6px; padding:2px 8px; font-size:0.82rem; font-weight:800; font-family:'AtlantaRoundedBlack', 'AtlantaRounded', sans-serif;">...</span>`;
    }).join(' ');

    // Correct Malay quotation marks: \u201c (opening quote “) and \u201d (closing quote ”)
    const openQuote = '\u201c';
    const closeQuote = '\u201d';

    html += `
    <div class="cl-bacaan-bergred-wrap">
        <!-- Left Side: Card / Progress Banner -->
        <div class="cl-bacaan-question-card" style="position:relative; padding:18px 68px 18px 18px;">
            <div style="display:flex; align-items:center; gap:14px;">
                <img src="${q.image}" style="width:58px; height:58px; border-radius:12px; object-fit:cover; border:2.5px solid #1e293b; flex-shrink:0;" onerror="this.src='/images/menu/ayat pendek.png';" />
                <div style="text-align:left;">
                    <div style="font-size:0.82rem; font-weight:800; color:#64748b; margin-bottom:2px; font-family:'AtlantaRoundedBlack', 'AtlantaRounded', sans-serif;">Patuk perkataan seterusnya:</div>
                    <div id="bpa-target-badge" style="font-size:1.4rem; font-weight:900; color:#059669; font-family:'AtlantaRoundedBlack', 'AtlantaRounded', sans-serif; display:flex; align-items:center;">
                        <span style="color:#0284c7; font-family:Arial, sans-serif; font-weight:900; margin-right:1px;">${openQuote}</span><span>${cleanWords[0]}</span><span style="color:#0284c7; font-family:Arial, sans-serif; font-weight:900; margin-left:1px;">${closeQuote}</span>
                    </div>
                </div>
            </div>
            <!-- Live Completed Sentence Assembly Track -->
            <div id="bpa-sentence-assembly" style="display:flex; flex-wrap:wrap; gap:6px; align-items:center; justify-content:flex-start; margin-top:14px; padding-top:10px; border-top:2px dashed #e2e8f0;">
                ${progressPills}
            </div>
            <button type="button" onclick="sebutTeksPermainan('${q.audio || q.text}')" style="position:absolute; top:22px; right:16px; width:44px !important; height:44px !important; min-width:44px !important; min-height:44px !important; max-width:44px !important; max-height:44px !important; padding:0 !important; border-radius:50% !important; aspect-ratio:1/1 !important; display:flex !important; align-items:center !important; justify-content:center !important; flex-shrink:0 !important; box-sizing:border-box !important; background:#10b981; color:#ffffff; border:2.5px solid #1e293b; box-shadow:0 3px 0 #1e293b; cursor:pointer;" title="Dengar Ayat">
                <i class="fa-solid fa-volume-high" style="font-size:1.15rem; margin:0; padding:0;"></i>
            </button>
        </div>

        <!-- Right Side: Canvas Game Area (Enlarged) -->
        <div class="cl-bacaan-canvas-wrap" style="position:relative;">
            <canvas id="bpa-canvas" width="340" height="260" style="background:#7dd3fc; display:block; margin:0 auto; user-select:none; touch-action:none; cursor:pointer;"></canvas>
            <div id="bpa-hint-tap" style="position:absolute; bottom:28px; left:50%; transform:translateX(-50%); pointer-events:none; background:rgba(0,0,0,0.6); color:#ffffff; font-size:0.8rem; font-weight:900; padding:4px 14px; border-radius:14px; font-family:'AtlantaRoundedBlack', 'AtlantaRounded', sans-serif; letter-spacing:0.5px; transition:opacity 0.3s; opacity:0.9; white-space:nowrap;">
                👆 Ketuk skrin untuk terbang!
            </div>
        </div>
    </div>
    `;

    area.innerHTML = html;

    setTimeout(() => {
        window.initBurungPatukAyatCanvas();
    }, 40);
};

window.initBurungPatukAyatCanvas = function () {
    const canvas = document.getElementById('bpa-canvas');
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    if (window.bpaAnimId) cancelAnimationFrame(window.bpaAnimId);
    if (window.bpaKeyHandler) window.removeEventListener('keydown', window.bpaKeyHandler);

    const C_WIDTH = 340;
    const C_HEIGHT = 260;
    const GROUND_Y = 236;

    let bird = {
        x: 65,
        y: 125,
        vy: 0,
        r: 15,
        wingAngle: 0,
        peckTimer: 0,
        flashRedTimer: 0
    };

    let clouds = [
        { x: 30, y: 28, w: 55, s: 0.35 },
        { x: 170, y: 55, w: 45, s: 0.25 },
        { x: 280, y: 22, w: 65, s: 0.4 }
    ];

    let sparkles = [];
    let isAdvancing = false;

    // Distractor word generator
    const allSentenceWords = [];
    ARKED_DATA_AYAT_PENDEK.forEach(item => {
        item.text.replace(/\./g, '').trim().split(/\s+/).forEach(w => {
            if (w && !allSentenceWords.includes(w)) allSentenceWords.push(w);
        });
    });

    const targetWords = window.bpaTargetWords || [];
    let currentWordBadges = [];

    function spawnWordBadgesForTarget(tIdx) {
        if (tIdx >= targetWords.length) return;
        const currentTargetWord = targetWords[tIdx];

        // Pick 2 decoys that are different from target
        const decoys = allSentenceWords.filter(w => w.toLowerCase() !== currentTargetWord.toLowerCase())
            .sort(() => Math.random() - 0.5)
            .slice(0, 2);

        const lanes = [55, 115, 175];
        lanes.sort(() => Math.random() - 0.5);

        const wordsToSpawn = [
            { word: currentTargetWord, isTarget: true, laneY: lanes[0] },
            { word: decoys[0], isTarget: false, laneY: lanes[1] },
            { word: decoys[1], isTarget: false, laneY: lanes[2] }
        ];

        currentWordBadges = wordsToSpawn.map((item, idx) => ({
            word: item.word,
            isTarget: item.isTarget,
            x: C_WIDTH + 30 + (idx * 10),
            y: item.laneY,
            baseY: item.laneY,
            floatOffset: Math.random() * Math.PI * 2,
            speed: 1.15,
            collected: false,
            popScale: 1,
            popOpacity: 1
        }));
    }

    spawnWordBadgesForTarget(0);

    function flapBird() {
        if (isAdvancing) return;
        bird.vy = -3.8;
        bird.wingAngle = Math.PI / 4;
        const hint = document.getElementById('bpa-hint-tap');
        if (hint) hint.style.opacity = '0';
        if (window.playBubble) window.playBubble();
    }

    function diveBird() {
        if (isAdvancing) return;
        bird.vy = 3.2;
        const hint = document.getElementById('bpa-hint-tap');
        if (hint) hint.style.opacity = '0';
    }

    canvas.onpointerdown = function (e) {
        e.preventDefault();
        flapBird();
    };



    window.bpaKeyHandler = function (e) {
        if (e.target && (e.target.tagName === 'INPUT' || e.target.tagName === 'TEXTAREA' || e.target.isContentEditable)) return;
        if (e.code === 'Space' || e.code === 'ArrowUp' || e.key === 'w' || e.key === 'W') {
            e.preventDefault();
            flapBird();
        } else if (e.code === 'ArrowDown' || e.key === 's' || e.key === 'S') {
            e.preventDefault();
            diveBird();
        }
    };
    window.addEventListener('keydown', window.bpaKeyHandler);

    function spawnPeckSparkles(x, y) {
        const colors = ['#f59e0b', '#fbbf24', '#10b981', '#38bdf8', '#ffffff'];
        for (let i = 0; i < 12; i++) {
            const angle = Math.random() * Math.PI * 2;
            const speed = 1.8 + Math.random() * 3.5;
            sparkles.push({
                x: x,
                y: y,
                vx: Math.cos(angle) * speed,
                vy: Math.sin(angle) * speed,
                r: 2.5 + Math.random() * 3.5,
                color: colors[Math.floor(Math.random() * colors.length)],
                life: 20
            });
        }
    }

    let frameCount = 0;

    function gameLoop() {
        frameCount++;

        // Clear sky
        const skyGrad = ctx.createLinearGradient(0, 0, 0, GROUND_Y);
        skyGrad.addColorStop(0, '#38bdf8');
        skyGrad.addColorStop(0.5, '#7dd3fc');
        skyGrad.addColorStop(1, '#e0f2fe');
        ctx.fillStyle = skyGrad;
        ctx.fillRect(0, 0, C_WIDTH, C_HEIGHT);

        // Animate clouds
        clouds.forEach(c => {
            c.x -= c.s;
            if (c.x + c.w < -30) c.x = C_WIDTH + 30;
            ctx.fillStyle = 'rgba(255, 255, 255, 0.85)';
            ctx.beginPath();
            ctx.arc(c.x, c.y, c.w * 0.28, 0, Math.PI * 2);
            ctx.arc(c.x + c.w * 0.22, c.y - c.w * 0.1, c.w * 0.32, 0, Math.PI * 2);
            ctx.arc(c.x + c.w * 0.45, c.y, c.w * 0.25, 0, Math.PI * 2);
            ctx.fill();
        });

        // Rolling grassy ground
        ctx.fillStyle = '#22c55e';
        ctx.fillRect(0, GROUND_Y, C_WIDTH, C_HEIGHT - GROUND_Y);
        ctx.fillStyle = '#16a34a';
        ctx.fillRect(0, GROUND_Y, C_WIDTH, 4);

        // Ground decorative flowers
        for (let fx = 15; fx < C_WIDTH; fx += 40) {
            ctx.fillStyle = '#fef08a';
            ctx.beginPath();
            ctx.arc(fx, GROUND_Y + 12, 3.5, 0, Math.PI * 2);
            ctx.fill();
            ctx.fillStyle = '#ea580c';
            ctx.beginPath();
            ctx.arc(fx, GROUND_Y + 12, 1.8, 0, Math.PI * 2);
            ctx.fill();
        }

        // Update Bird Physics
        if (!isAdvancing) {
            bird.vy += 0.22; // Gravity
            bird.y += bird.vy;
            bird.wingAngle += 0.18;

            if (bird.y < bird.r + 5) {
                bird.y = bird.r + 5;
                bird.vy = 0;
            }
            if (bird.y > GROUND_Y - bird.r) {
                bird.y = GROUND_Y - bird.r;
                bird.vy = 0;
            }
        }

        if (bird.peckTimer > 0) bird.peckTimer--;
        if (bird.flashRedTimer > 0) bird.flashRedTimer--;

        // Update Word Badges
        let needRespawn = false;
        currentWordBadges.forEach(badge => {
            if (badge.collected) {
                badge.popScale += 0.05;
                badge.popOpacity -= 0.06;
                return;
            }

            badge.x -= badge.speed;
            badge.y = badge.baseY + Math.sin(frameCount * 0.04 + badge.floatOffset) * 8;

            if (badge.x < -80) {
                needRespawn = true;
            }

            // Collision detection with Bird beak
            const beakX = bird.x + (bird.peckTimer > 0 ? 20 : 13);
            const beakY = bird.y + (bird.peckTimer > 0 ? 3 : 0);
            const dist = Math.hypot(beakX - badge.x, beakY - badge.y);

            if (!badge.collected && !isAdvancing && dist < 32) {
                if (badge.isTarget) {
                    // SUCCESSFUL PECK!
                    badge.collected = true;
                    bird.peckTimer = 16;
                    spawnPeckSparkles(badge.x, badge.y);
                    if (window.playBetulSound) window.playBetulSound();

                    // Update UI Assembly
                    const tIdx = window.bpaTargetIndex;
                    const curPill = document.getElementById(`bpa-pill-${tIdx}`);
                    if (curPill) {
                        curPill.style.background = '#dcfce7';
                        curPill.style.color = '#15803d';
                        curPill.style.border = '1.5px solid #16a34a';
                        curPill.innerText = targetWords[tIdx];
                    }

                    window.bpaTargetIndex++;

                    if (window.bpaTargetIndex < targetWords.length) {
                        const nextIdx = window.bpaTargetIndex;
                        const nextPill = document.getElementById(`bpa-pill-${nextIdx}`);
                        if (nextPill) {
                            nextPill.style.background = '#fef08a';
                            nextPill.style.color = '#854d0e';
                            nextPill.style.border = '1.5px solid #eab308';
                            nextPill.innerText = targetWords[nextIdx];
                        }

                        // Update Target Badge
                        const badgeEl = document.getElementById('bpa-target-badge');
                        if (badgeEl) {
                            badgeEl.innerHTML = `<span style="color:#0284c7; font-family:Arial, sans-serif; font-weight:900; margin-right:1px;">\u201c</span><span>${targetWords[nextIdx]}</span><span style="color:#0284c7; font-family:Arial, sans-serif; font-weight:900; margin-left:1px;">\u201d</span>`;
                        }

                        setTimeout(() => {
                            spawnWordBadgesForTarget(window.bpaTargetIndex);
                        }, 250);
                    } else {
                        // ALL WORDS PECKED!
                        isAdvancing = true;
                        const badgeEl = document.getElementById('bpa-target-badge');
                        if (badgeEl) {
                            const fullTxt = (targetWords || []).join(' ');
                            badgeEl.innerHTML = `<span style="color:#059669;">${fullTxt}</span>`;
                        }

                        if (window.triggerConfettiEffect) window.triggerConfettiEffect();
                        const q = window.bpaQuestions[window.bpaCurrent];
                        if (q) sebutTeksPermainan(q.audio || q.text);

                        setTimeout(() => {
                            window.bpaCurrent++;
                            window.renderBurungPatukAyatQuestion();
                        }, 1400);
                    }
                } else {
                    // WRONG WORD PECKED!
                    if (window.playSalahSound) window.playSalahSound();
                    bird.flashRedTimer = 18;
                    badge.x += 35; // Push away
                    window.clLives--;
                    window.updateCabaranLainHearts();

                    if (window.clLives <= 0) {
                        isAdvancing = true;
                        setTimeout(() => {
                            window.showCabaranLainStarPopup(0, 0);
                        }, 400);
                    }
                }
            }
        });

        if (needRespawn && !isAdvancing) {
            spawnWordBadgesForTarget(window.bpaTargetIndex);
        }

        // Draw Word Badges
        currentWordBadges.forEach(badge => {
            if (badge.collected && badge.popOpacity <= 0) return;

            ctx.save();
            ctx.translate(badge.x, badge.y);

            if (badge.collected) {
                ctx.scale(badge.popScale, badge.popScale);
                ctx.globalAlpha = Math.max(0, badge.popOpacity);
                ctx.shadowColor = '#10b981';
                ctx.shadowBlur = 14;
            } else {
                ctx.globalAlpha = 1;
            }

            ctx.font = '900 13px "AtlantaRoundedBlack", "AtlantaRounded", sans-serif';
            const textMetrics = ctx.measureText(badge.word);
            const padX = 14;
            const bWidth = Math.max(54, textMetrics.width + padX * 2);
            const bHeight = 28;

            // Badge container
            ctx.beginPath();
            ctx.roundRect(-bWidth / 2, -bHeight / 2, bWidth, bHeight, 14);
            ctx.fillStyle = badge.collected ? '#dcfce7' : '#ffffff';
            ctx.fill();
            ctx.strokeStyle = badge.collected ? '#10b981' : '#1e293b';
            ctx.lineWidth = 2.5;
            ctx.stroke();

            // Word text
            ctx.fillStyle = badge.collected ? '#047857' : (badge.isTarget ? '#0f172a' : '#334155');
            ctx.textAlign = 'center';
            ctx.textBaseline = 'middle';
            ctx.fillText(badge.word, 0, 1);

            ctx.restore();
        });

        // Draw Peck Sparkles
        sparkles = sparkles.filter(s => s.life > 0);
        sparkles.forEach(s => {
            s.x += s.vx;
            s.y += s.vy;
            s.vy += 0.12;
            s.life--;
            ctx.save();
            ctx.globalAlpha = s.life / 20;
            ctx.fillStyle = s.color;
            ctx.beginPath();
            ctx.arc(s.x, s.y, s.r, 0, Math.PI * 2);
            ctx.fill();
            ctx.restore();
        });

        // Draw Cute Bird
        ctx.save();
        ctx.translate(bird.x, bird.y);

        // Peck thrust animation
        if (bird.peckTimer > 0) {
            ctx.translate(5, 2);
            ctx.rotate(0.12);
        } else {
            ctx.rotate(Math.max(-0.4, Math.min(0.5, bird.vy * 0.08)));
        }

        // Tail feathers
        ctx.fillStyle = '#0284c7';
        ctx.beginPath();
        ctx.moveTo(-bird.r, 0);
        ctx.lineTo(-bird.r - 10, -6);
        ctx.lineTo(-bird.r - 8, 2);
        ctx.lineTo(-bird.r - 11, 8);
        ctx.closePath();
        ctx.fill();

        // Bird Body
        ctx.fillStyle = bird.flashRedTimer > 0 ? '#ef4444' : '#38bdf8';
        ctx.beginPath();
        ctx.arc(0, 0, bird.r, 0, Math.PI * 2);
        ctx.fill();
        ctx.strokeStyle = '#1e293b';
        ctx.lineWidth = 2.5;
        ctx.stroke();

        // White belly
        ctx.fillStyle = '#ffffff';
        ctx.beginPath();
        ctx.arc(2, 4, bird.r * 0.62, 0, Math.PI * 2);
        ctx.fill();

        // Animated Wing
        const flap = Math.sin(bird.wingAngle) * 6;
        ctx.fillStyle = bird.flashRedTimer > 0 ? '#b91c1c' : '#0284c7';
        ctx.beginPath();
        ctx.ellipse(-3, -2 + flap * 0.3, bird.r * 0.65, bird.r * 0.42, 0.2 + flap * 0.05, 0, Math.PI * 2);
        ctx.fill();
        ctx.strokeStyle = '#1e293b';
        ctx.lineWidth = 1.8;
        ctx.stroke();

        // Cute Big Eye
        ctx.fillStyle = '#ffffff';
        ctx.beginPath();
        ctx.arc(6, -4, 5.5, 0, Math.PI * 2);
        ctx.fill();
        ctx.strokeStyle = '#1e293b';
        ctx.lineWidth = 1.8;
        ctx.stroke();

        // Pupil
        ctx.fillStyle = '#0f172a';
        ctx.beginPath();
        ctx.arc(7.5, -4, 2.8, 0, Math.PI * 2);
        ctx.fill();

        // Eye glint
        ctx.fillStyle = '#ffffff';
        ctx.beginPath();
        ctx.arc(8.5, -5.2, 1.2, 0, Math.PI * 2);
        ctx.fill();

        // Cute Orange Beak with Pecking action
        ctx.fillStyle = '#f97316';
        ctx.beginPath();
        if (bird.peckTimer > 0) {
            // Extended open beak during peck!
            ctx.moveTo(bird.r - 1, -5);
            ctx.lineTo(bird.r + 14, -1);
            ctx.lineTo(bird.r - 1, 3);
            ctx.closePath();
            ctx.fill();
            ctx.strokeStyle = '#c2410c';
            ctx.lineWidth = 1.5;
            ctx.stroke();
        } else {
            ctx.moveTo(bird.r - 1, -4);
            ctx.lineTo(bird.r + 9, -1);
            ctx.lineTo(bird.r - 1, 2);
            ctx.closePath();
            ctx.fill();
            ctx.strokeStyle = '#c2410c';
            ctx.lineWidth = 1.5;
            ctx.stroke();
        }

        ctx.restore();

        window.bpaAnimId = requestAnimationFrame(gameLoop);
    }

    window.bpaAnimId = requestAnimationFrame(gameLoop);
};

// ============================================================================
// 2. GAME 2: LASTIK BURUNG (ANGRY BIRDS SLINGSHOT)
// ============================================================================
window.generateLastikBurungGame = function (area) {
    if (!area) area = document.getElementById('cabaran-lain-game-area');
    if (!area) return;

    if (window.lbAnimId) { cancelAnimationFrame(window.lbAnimId); window.lbAnimId = null; }

    window.lbQuestions = [...ARKED_DATA_AYAT_PANJANG].sort(() => Math.random() - 0.5).slice(0, 5);
    window.lbCurrent = 0;
    window.lbTotal = 5;
    window.clLives = 3;

    window.renderLastikBurungQuestion(area);
};

window.renderLastikBurungQuestion = function (area) {
    if (!area) area = document.getElementById('cabaran-lain-game-area');
    if (!area) return;

    if (window.clLives <= 0) {
        window.showCabaranLainStarPopup(0, 0);
        return;
    }
    if (window.lbCurrent >= window.lbTotal) {
        const stars = window.clLives >= 3 ? 3 : (window.clLives >= 2 ? 2 : 1);
        const score = Math.round((stars / 3) * 100);
        window.saveCabaranLainScore(window.currentExtraChallenge.id, score, stars);
        setTimeout(() => { window.showCabaranLainStarPopup(score, stars); }, 350);
        return;
    }

    const q = window.lbQuestions[window.lbCurrent];

    let html = window.renderCabaranLainHeader(window.lbCurrent + 1, window.lbTotal);

    html += `
    <div class="cl-bacaan-bergred-wrap">
        <!-- Left Side: Sentence Card with Blank & Audio -->
        <div class="cl-bacaan-question-card" style="position:relative; padding:18px 68px 18px 18px; text-align:left;">
            <div style="font-size:0.82rem; font-weight:800; color:#64748b; margin-bottom:6px; font-family:'AtlantaRoundedBlack', 'AtlantaRounded', sans-serif;">Lengkapkan ayat:</div>
            <p style="margin:0; font-size:1.15rem; font-weight:800; line-height:1.45; color:#1e293b; font-family:'AtlantaRounded',sans-serif;">
                ${q.text.replace('______', `<span id="lb-blank" style="display:inline-block; min-width:75px; border-bottom:3px solid #1e293b; color:#1e293b; font-weight:900; padding:0 4px; text-align:center;">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span>`)}
            </p>
            <button type="button" onclick="sebutTeksPermainan('${q.audio || q.fullText}')" style="position:absolute; top:50%; transform:translateY(-50%); right:16px; width:44px !important; height:44px !important; min-width:44px !important; min-height:44px !important; max-width:44px !important; max-height:44px !important; padding:0 !important; border-radius:50% !important; aspect-ratio:1/1 !important; display:flex !important; align-items:center !important; justify-content:center !important; flex-shrink:0 !important; box-sizing:border-box !important; background:#f59e0b; color:#ffffff; border:2.5px solid #1e293b; box-shadow:0 3px 0 #1e293b; cursor:pointer;" title="Dengar">
                <i class="fa-solid fa-volume-high" style="font-size:1.15rem; margin:0; padding:0;"></i>
            </button>
        </div>

        <!-- Right Side: Canvas Game Wrap (Enlarged) with Animated Hand Cursor Demo -->
        <div class="cl-bacaan-canvas-wrap" style="position:relative;">
            <style>
                @keyframes lbSlingshotPull {
                    0% { transform: translate(-50%, -50%) translate(0px, 0px) scale(1); opacity: 0; }
                    15% { transform: translate(-50%, -50%) translate(0px, 0px) scale(0.92); opacity: 1; }
                    55% { transform: translate(-50%, -50%) translate(-38px, 20px) scale(0.92); opacity: 1; }
                    75% { transform: translate(-50%, -50%) translate(-38px, 20px) scale(1); opacity: 0; }
                    100% { transform: translate(-50%, -50%) translate(0px, 0px) scale(1); opacity: 0; }
                }
            </style>
            <canvas id="lb-canvas" width="340" height="260" style="background:#38bdf8; display:block; margin:0 auto; user-select:none; touch-action:none;"></canvas>
            <div id="lb-cursor-demo" style="position:absolute; inset:0; pointer-events:none; z-index:20;">
                <div style="position:absolute; left:65px; top:175px; animation:lbSlingshotPull 2.2s infinite ease-in-out;">
                    <svg width="40" height="40" viewBox="0 0 24 24" fill="none" style="display:block; filter:drop-shadow(0 3px 5px rgba(16,24,47,0.35));">
                        <circle cx="8" cy="5" r="3.5" stroke="#ff7a00" stroke-width="2" opacity="0.85" />
                        <circle cx="8" cy="5" r="5.5" stroke="#ffe24a" stroke-width="1.5" opacity="0.55" />
                        <path d="M9 11V4.5C9 3.67 8.33 3 7.5 3C6.67 3 6 3.67 6 4.5V12.5L4.85 11.27C4.33 10.74 3.49 10.74 2.97 11.27C2.45 11.8 2.45 12.64 2.97 13.17L7.6 17.8C8.5 18.7 9.7 19.2 11 19.2H14.5C16.99 19.2 19 17.19 19 14.7V10.5C19 9.67 18.33 9 17.5 9C17.3 9 17.1 9.04 16.92 9.12C16.66 8.46 16.03 8 15.28 8C15.05 8 14.83 8.05 14.63 8.15C14.33 7.46 13.65 7 12.85 7C12.65 7 12.45 7.04 12.27 7.12C12.01 6.46 11.38 6 10.63 6C9.73 6 9 6.73 9 7.63V11Z" fill="#ffffff" stroke="#10182f" stroke-width="1.8" stroke-linejoin="round" />
                    </svg>
                </div>
            </div>
        </div>
    </div>
    `;

    area.innerHTML = html;

    setTimeout(() => {
        window.initLastikBurungCanvas();
    }, 40);
};

window.initLastikBurungCanvas = function () {
    const canvas = document.getElementById('lb-canvas');
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    if (window.lbAnimId) cancelAnimationFrame(window.lbAnimId);

    const q = window.lbQuestions[window.lbCurrent];
    const choices = [...q.choices].sort(() => Math.random() - 0.5);

    const SLING_X = 65;
    const SLING_Y = 175;

    let bird = {
        x: SLING_X,
        y: SLING_Y,
        vx: 0,
        vy: 0,
        r: 16,
        isDragging: false,
        isFlying: false
    };

    // Target crates on right
    let targets = [
        { text: choices[0], x: 260, y: 65, w: 72, h: 36, hit: false, popScale: 1.0, popGlow: 0, isPopping: false },
        { text: choices[1], x: 260, y: 125, w: 72, h: 36, hit: false, popScale: 1.0, popGlow: 0, isPopping: false },
        { text: choices[2], x: 260, y: 185, w: 72, h: 36, hit: false, popScale: 1.0, popGlow: 0, isPopping: false }
    ];
    let lbParticles = [];

    function spawnLbPopParticles(px, py, isCorrect) {
        const colors = isCorrect ? ['#10b981', '#34d399', '#fbbf24', '#ffffff'] : ['#f87171', '#ef4444', '#f59e0b'];
        for (let i = 0; i < 14; i++) {
            const angle = Math.random() * Math.PI * 2;
            const spd = 2.0 + Math.random() * 4.0;
            lbParticles.push({
                x: px,
                y: py,
                vx: Math.cos(angle) * spd,
                vy: Math.sin(angle) * spd,
                r: 2.5 + Math.random() * 3.5,
                color: colors[Math.floor(Math.random() * colors.length)],
                life: 22
            });
        }
    }

    function getCanvasPos(e) {
        const rect = canvas.getBoundingClientRect();
        const clientX = e.touches ? e.touches[0].clientX : e.clientX;
        const clientY = e.touches ? e.touches[0].clientY : e.clientY;
        return {
            x: (clientX - rect.left) * (340 / rect.width),
            y: (clientY - rect.top) * (260 / rect.height)
        };
    }

    function onDown(e) {
        if (bird.isFlying) return;
        const demo = document.getElementById('lb-cursor-demo');
        if (demo) demo.style.display = 'none';
        const pos = getCanvasPos(e);
        const dist = Math.hypot(pos.x - bird.x, pos.y - bird.y);
        if (dist < 36) {
            bird.isDragging = true;
        }
    }

    function onMove(e) {
        if (!bird.isDragging) return;
        const pos = getCanvasPos(e);
        const dx = pos.x - SLING_X;
        const dy = pos.y - SLING_Y;
        const dist = Math.hypot(dx, dy);
        const maxPull = 55;
        if (dist > maxPull) {
            bird.x = SLING_X + (dx / dist) * maxPull;
            bird.y = SLING_Y + (dy / dist) * maxPull;
        } else {
            bird.x = pos.x;
            bird.y = pos.y;
        }
    }

    function onUp() {
        if (!bird.isDragging) return;
        bird.isDragging = false;
        const pullDist = Math.hypot(SLING_X - bird.x, SLING_Y - bird.y);
        if (pullDist > 12) {
            bird.vx = (SLING_X - bird.x) * 0.22;
            bird.vy = (SLING_Y - bird.y) * 0.22;
            bird.isFlying = true;
        } else {
            bird.x = SLING_X;
            bird.y = SLING_Y;
        }
    }

    canvas.addEventListener('mousedown', onDown);
    window.addEventListener('mousemove', onMove);
    window.addEventListener('mouseup', onUp);

    canvas.addEventListener('touchstart', onDown, { passive: true });
    window.addEventListener('touchmove', onMove, { passive: true });
    window.addEventListener('touchend', onUp);

    let advanceTimeout = null;

    function loop() {
        // Physics update
        if (bird.isFlying) {
            bird.x += bird.vx;
            bird.y += bird.vy;
            bird.vy += 0.38; // gravity

            // Collision with targets
            targets.forEach(t => {
                if (!t.hit && bird.x + bird.r > t.x - t.w / 2 && bird.x - bird.r < t.x + t.w / 2 &&
                    bird.y + bird.r > t.y - t.h / 2 && bird.y - bird.r < t.y + t.h / 2) {
                    t.hit = true;
                    t.isPopping = true;
                    t.popScale = 1.36;
                    bird.isFlying = false;

                    const isCorrect = t.text.toLowerCase() === q.target.toLowerCase();
                    spawnLbPopParticles(t.x, t.y, isCorrect);
                    if (isCorrect) {
                        t.popGlow = 1;
                        if (window.playBetulSound) window.playBetulSound();
                        if (window.triggerConfettiEffect) window.triggerConfettiEffect();
                        const blank = document.getElementById('lb-blank');
                        if (blank) { blank.innerText = q.target; blank.style.color = '#10b981'; }

                        let advanced = false;
                        const doAdvance = () => {
                            if (advanced) return;
                            advanced = true;
                            if (advanceTimeout) { clearTimeout(advanceTimeout); advanceTimeout = null; }
                            setTimeout(() => {
                                window.lbCurrent++;
                                window.renderLastikBurungQuestion();
                            }, 450); // gentle pause after audio finishes
                        };

                        // Tunggu sebutan audio selesai sepenuhnya dahulu baru masuk ke soalan seterusnya
                        sebutTeksPermainan(q.audio || q.fullText, null, doAdvance);

                        // Safety fallback timeout in case audio device is muted
                        advanceTimeout = setTimeout(doAdvance, 6500);
                    } else {
                        // Wrong!
                        if (window.playSalahSound) window.playSalahSound();
                        window.clLives--;
                        window.updateCabaranLainHearts();
                        setTimeout(() => {
                            if (window.clLives <= 0) {
                                window.showCabaranLainStarPopup(0, 0);
                            } else {
                                bird.x = SLING_X;
                                bird.y = SLING_Y;
                                bird.vx = 0;
                                bird.vy = 0;
                                t.hit = false;
                                t.isPopping = false;
                                t.popScale = 1.0;
                            }
                        }, 700);
                    }
                }
            });

            // Hit ground or offscreen
            if (bird.y > 230 || bird.x > 340 || bird.x < 0) {
                bird.isFlying = false;
                setTimeout(() => {
                    bird.x = SLING_X;
                    bird.y = SLING_Y;
                    bird.vx = 0;
                    bird.vy = 0;
                }, 400);
            }
        }

        // Render Canvas
        ctx.fillStyle = '#38bdf8';
        ctx.fillRect(0, 0, 340, 260);

        // Clouds & Ground
        ctx.fillStyle = 'rgba(255, 255, 255, 0.7)';
        ctx.beginPath();
        ctx.arc(80, 50, 24, 0, Math.PI * 2);
        ctx.arc(110, 45, 30, 0, Math.PI * 2);
        ctx.arc(140, 50, 22, 0, Math.PI * 2);
        ctx.fill();

        ctx.fillStyle = '#22c55e';
        ctx.fillRect(0, 230, 340, 30);
        ctx.fillStyle = '#15803d';
        ctx.fillRect(0, 230, 340, 4);

        // Slingshot Wood Fork
        ctx.strokeStyle = '#78350f';
        ctx.lineWidth = 6;
        ctx.lineCap = 'round';
        ctx.beginPath();
        ctx.moveTo(SLING_X, 230);
        ctx.lineTo(SLING_X, SLING_Y + 15);
        ctx.lineTo(SLING_X - 12, SLING_Y - 10);
        ctx.moveTo(SLING_X, SLING_Y + 15);
        ctx.lineTo(SLING_X + 12, SLING_Y - 10);
        ctx.stroke();

        // Rubber bands
        if (bird.isDragging) {
            ctx.strokeStyle = '#b45309';
            ctx.lineWidth = 3.5;
            ctx.beginPath();
            ctx.moveTo(SLING_X - 12, SLING_Y - 10);
            ctx.lineTo(bird.x, bird.y);
            ctx.moveTo(SLING_X + 12, SLING_Y - 10);
            ctx.lineTo(bird.x, bird.y);
            ctx.stroke();

            // Dotted Trajectory
            ctx.fillStyle = 'rgba(255, 255, 255, 0.8)';
            let simX = bird.x;
            let simY = bird.y;
            let simVx = (SLING_X - bird.x) * 0.22;
            let simVy = (SLING_Y - bird.y) * 0.22;
            for (let i = 0; i < 9; i++) {
                simX += simVx;
                simY += simVy;
                simVy += 0.38;
                ctx.beginPath();
                ctx.arc(simX, simY, 2.5, 0, Math.PI * 2);
                ctx.fill();
            }
        }

        // Draw Target Crates with Pop Animation Effect
        targets.forEach(t => {
            ctx.save();
            if (t.isPopping) {
                t.popScale += (1.1 - t.popScale) * 0.15;
            } else {
                t.popScale += (1.0 - t.popScale) * 0.2;
            }

            ctx.translate(t.x, t.y);
            ctx.scale(t.popScale, t.popScale);

            if (t.isPopping && t.popGlow > 0) {
                ctx.shadowColor = '#10b981';
                ctx.shadowBlur = 16;
            }

            ctx.fillStyle = t.hit ? (t.popGlow > 0 ? '#dcfce7' : '#fecaca') : '#fed7aa';
            ctx.beginPath();
            ctx.roundRect(-t.w / 2, -t.h / 2, t.w, t.h, 10);
            ctx.fill();
            ctx.strokeStyle = t.hit ? (t.popGlow > 0 ? '#10b981' : '#ef4444') : '#1e293b';
            ctx.lineWidth = t.hit ? 3 : 2.5;
            ctx.stroke();

            ctx.font = '900 13px "AtlantaRoundedBlack", "AtlantaRounded", sans-serif';
            ctx.fillStyle = t.hit ? (t.popGlow > 0 ? '#065f46' : '#991b1b') : '#1e293b';
            ctx.textAlign = 'center';
            ctx.textBaseline = 'middle';
            ctx.fillText(t.text, 0, 1);
            ctx.restore();
        });

        // Draw Pop Particles
        if (typeof lbParticles !== 'undefined') {
            lbParticles = lbParticles.filter(p => p.life > 0);
            lbParticles.forEach(p => {
                p.x += p.vx;
                p.y += p.vy;
                p.vy += 0.15;
                p.life--;
                ctx.save();
                ctx.globalAlpha = p.life / 22;
                ctx.fillStyle = p.color;
                ctx.beginPath();
                ctx.arc(p.x, p.y, p.r, 0, Math.PI * 2);
                ctx.fill();
                ctx.restore();
            });
        }

        // Draw Bird
        ctx.save();
        ctx.fillStyle = '#ef4444';
        ctx.beginPath();
        ctx.arc(bird.x, bird.y, bird.r, 0, Math.PI * 2);
        ctx.fill();
        ctx.strokeStyle = '#1e293b';
        ctx.lineWidth = 2;
        ctx.stroke();

        // Bird eye
        ctx.fillStyle = '#ffffff';
        ctx.beginPath();
        ctx.arc(bird.x + 6, bird.y - 4, 5, 0, Math.PI * 2);
        ctx.fill();
        ctx.fillStyle = '#0f172a';
        ctx.beginPath();
        ctx.arc(bird.x + 8, bird.y - 4, 2.5, 0, Math.PI * 2);
        ctx.fill();

        // Bird beak
        ctx.fillStyle = '#f59e0b';
        ctx.beginPath();
        ctx.moveTo(bird.x + 12, bird.y);
        ctx.lineTo(bird.x + 22, bird.y + 3);
        ctx.lineTo(bird.x + 12, bird.y + 7);
        ctx.closePath();
        ctx.fill();
        ctx.restore();

        window.lbAnimId = requestAnimationFrame(loop);
    }

    loop();
};

