window.initMeriamKataCanvas = function () {
    const canvas = document.getElementById('mk-canvas');
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    if (window.mkAnimId) cancelAnimationFrame(window.mkAnimId);

    const q = window.mkQuestions[window.mkCurrent];
    const choices = [...q.choices].sort(() => Math.random() - 0.5);

    let cannon = {
        x: 170,
        y: 245,
        angle: -Math.PI / 2
    };

    let balloons = [
        { text: choices[0], x: 60, y: 70, baseX: 60, speed: 0.02, popped: false },
        { text: choices[1], x: 170, y: 55, baseX: 170, speed: 0.025, popped: false },
        { text: choices[2], x: 280, y: 70, baseX: 280, speed: 0.018, popped: false }
    ];

    let bullets = [];
    let time = 0;
    let isAdvancing = false;

    window.mkFireCannon = function () {
        if (bullets.length > 2 || isAdvancing) return;
        const speed = 7.5;
        bullets.push({
            x: cannon.x + Math.cos(cannon.angle) * 30,
            y: cannon.y + Math.sin(cannon.angle) * 30,
            vx: Math.cos(cannon.angle) * speed,
            vy: Math.sin(cannon.angle) * speed,
            r: 7
        });
        if (window.playBetulSound) window.playBetulSound();
    };

    function aimAt(pos) {
        const demo = document.getElementById('mk-cursor-demo');
        if (demo) demo.style.display = 'none';
        cannon.angle = Math.atan2(pos.y - cannon.y, pos.x - cannon.x);
        if (cannon.angle > -0.2) cannon.angle = -0.2;
        if (cannon.angle < -Math.PI + 0.2) cannon.angle = -Math.PI + 0.2;
    }

    function getCanvasPos(e) {
        const rect = canvas.getBoundingClientRect();
        const clientX = e.touches ? e.touches[0].clientX : e.clientX;
        const clientY = e.touches ? e.touches[0].clientY : e.clientY;
        return {
            x: (clientX - rect.left) * (340 / rect.width),
            y: (clientY - rect.top) * (260 / rect.height)
        };
    }

    canvas.addEventListener('mousemove', (e) => { aimAt(getCanvasPos(e)); });
    canvas.addEventListener('touchmove', (e) => { aimAt(getCanvasPos(e)); }, { passive: true });
    canvas.addEventListener('click', (e) => {
        aimAt(getCanvasPos(e));
        window.mkFireCannon();
    });

    function loop() {
        time += 0.03;

        // Update balloons swaying
        balloons.forEach((b, idx) => {
            b.x = b.baseX + Math.sin(time + idx * 2) * 25;
        });

        // Update bullets
        for (let i = bullets.length - 1; i >= 0; i--) {
            const bul = bullets[i];
            bul.x += bul.vx;
            bul.y += bul.vy;

            // Check hit with balloons
            balloons.forEach(b => {
                if (!b.popped && Math.hypot(bul.x - b.x, bul.y - b.y) < 32) {
                    b.popped = true;
                    bullets.splice(i, 1);

                    if (b.text.toLowerCase() === q.answer.toLowerCase()) {
                        isAdvancing = true;
                        if (window.playBetulSound) window.playBetulSound();
                        if (window.triggerConfettiEffect) window.triggerConfettiEffect();
                        setTimeout(() => {
                            window.mkCurrent++;
                            window.renderMeriamKataQuestion();
                        }, 1200);
                    } else {
                        if (window.playSalahSound) window.playSalahSound();
                        window.clLives--;
                        window.updateCabaranLainHearts();
                        setTimeout(() => {
                            if (window.clLives <= 0) {
                                window.showCabaranLainStarPopup(0, 0);
                            } else {
                                b.popped = false;
                            }
                        }, 700);
                    }
                }
            });

            if (bul.y < 0 || bul.x < 0 || bul.x > 340) {
                bullets.splice(i, 1);
            }
        }

        // Render Canvas
        ctx.fillStyle = '#cffafe';
        ctx.fillRect(0, 0, 340, 260);

        // Clouds & Hills
        ctx.fillStyle = '#a7f3d0';
        ctx.beginPath();
        ctx.arc(60, 260, 80, 0, Math.PI * 2);
        ctx.arc(280, 260, 90, 0, Math.PI * 2);
        ctx.fill();

        // Draw Attractive Floating Sky Targets (Airship / Hot-Air Balloon with Golden Trim)
        balloons.forEach((b, idx) => {
            if (b.popped) return;
            const themeGradients = [
                ['#fb7185', '#e11d48'],
                ['#38bdf8', '#0284c7'],
                ['#facc15', '#d97706']
            ];
            const theme = themeGradients[idx % 3];

            ctx.save();
            ctx.translate(b.x, b.y);

            // Balloon Oval with Vibrant Gradient
            const bGrad = ctx.createLinearGradient(0, -36, 0, 36);
            bGrad.addColorStop(0, theme[0]);
            bGrad.addColorStop(1, theme[1]);
            ctx.fillStyle = bGrad;
            ctx.beginPath();
            ctx.ellipse(0, 0, 34, 38, 0, 0, Math.PI * 2);
            ctx.fill();
            ctx.strokeStyle = '#1e293b';
            ctx.lineWidth = 2.5;
            ctx.stroke();

            // Decorative Vertical Stripe
            ctx.fillStyle = 'rgba(255, 255, 255, 0.3)';
            ctx.beginPath();
            ctx.ellipse(0, 0, 14, 38, 0, 0, Math.PI * 2);
            ctx.fill();

            // Highlight Dot
            ctx.fillStyle = '#ffffff';
            ctx.beginPath();
            ctx.arc(-13, -13, 3.5, 0, Math.PI * 2);
            ctx.fill();

            // Ropes to Basket
            ctx.strokeStyle = '#78350f';
            ctx.lineWidth = 1.8;
            ctx.beginPath();
            ctx.moveTo(-14, 36);
            ctx.lineTo(-8, 48);
            ctx.moveTo(14, 36);
            ctx.lineTo(8, 48);
            ctx.stroke();

            // Carved Wicker Basket with Gold Rim
            ctx.fillStyle = '#b45309';
            ctx.beginPath();
            ctx.roundRect(-12, 48, 24, 13, 4);
            ctx.fill();
            ctx.strokeStyle = '#78350f';
            ctx.lineWidth = 2;
            ctx.stroke();
            ctx.fillStyle = '#fbbf24';
            ctx.fillRect(-11, 48, 22, 3);

            // Attractive White Word Pill Badge Centered on Balloon
            ctx.font = '900 12px "AtlantaRoundedBlack", "AtlantaRounded", sans-serif';
            const textMetrics = ctx.measureText(b.text);
            const badgeW = Math.max(48, textMetrics.width + 16);
            const badgeH = 22;

            ctx.beginPath();
            ctx.roundRect(-badgeW / 2, -badgeH / 2, badgeW, badgeH, 11);
            ctx.fillStyle = '#ffffff';
            ctx.fill();
            ctx.strokeStyle = '#1e293b';
            ctx.lineWidth = 2;
            ctx.stroke();

            // Word Text
            ctx.fillStyle = '#0f172a';
            ctx.textAlign = 'center';
            ctx.textBaseline = 'middle';
            ctx.fillText(b.text, 0, 1);

            ctx.restore();
        });

        // Draw Bullets (Glowing Stars / Cannonball)
        bullets.forEach(bul => {
            ctx.save();
            ctx.fillStyle = '#f59e0b';
            ctx.beginPath();
            ctx.arc(bul.x, bul.y, bul.r, 0, Math.PI * 2);
            ctx.fill();
            ctx.strokeStyle = '#ffffff';
            ctx.lineWidth = 2;
            ctx.stroke();
            ctx.restore();
        });

        // Draw Royal Pirate Brass Cannon with Wood Carriage & Wheels
        ctx.save();
        ctx.translate(cannon.x, cannon.y);

        // Heavy Wooden Carriage Base
        ctx.fillStyle = '#78350f';
        ctx.beginPath();
        ctx.roundRect(-22, -8, 44, 18, 5);
        ctx.fill();
        ctx.strokeStyle = '#451a03';
        ctx.lineWidth = 2.5;
        ctx.stroke();

        // Carriage Left & Right Wheels
        ctx.fillStyle = '#b45309';
        ctx.beginPath();
        ctx.arc(-18, 2, 8, 0, Math.PI * 2);
        ctx.arc(18, 2, 8, 0, Math.PI * 2);
        ctx.fill();
        ctx.strokeStyle = '#1e293b';
        ctx.lineWidth = 2;
        ctx.stroke();

        // Cannon Pivot & Barrel (Rotated)
        ctx.save();
        ctx.rotate(cannon.angle);

        // Brass Barrel with Ring Details & Flared Muzzle
        const barrelGrad = ctx.createLinearGradient(0, -9, 0, 9);
        barrelGrad.addColorStop(0, '#fde047');
        barrelGrad.addColorStop(0.5, '#f59e0b');
        barrelGrad.addColorStop(1, '#b45309');
        ctx.fillStyle = barrelGrad;

        // Tapered Barrel
        ctx.beginPath();
        ctx.moveTo(0, -10);
        ctx.lineTo(40, -6.5);
        ctx.lineTo(40, 6.5);
        ctx.lineTo(0, 10);
        ctx.closePath();
        ctx.fill();
        ctx.strokeStyle = '#1e293b';
        ctx.lineWidth = 2.5;
        ctx.stroke();

        // Gold Barrel Bands
        ctx.fillStyle = '#fbbf24';
        ctx.fillRect(10, -9, 4, 18);
        ctx.strokeRect(10, -9, 4, 18);
        ctx.fillRect(24, -8, 4, 16);
        ctx.strokeRect(24, -8, 4, 16);

        // Flared Muzzle
        ctx.fillStyle = '#d97706';
        ctx.fillRect(38, -8, 6, 16);
        ctx.strokeRect(38, -8, 6, 16);

        // Breech Knob
        ctx.fillStyle = '#b45309';
        ctx.beginPath();
        ctx.arc(-2, 0, 7, 0, Math.PI * 2);
        ctx.fill();
        ctx.stroke();

        ctx.restore(); // Restore barrel rotation

        // Central Brass Pivot Mount
        ctx.fillStyle = '#fbbf24';
        ctx.beginPath();
        ctx.arc(0, 0, 11, 0, Math.PI * 2);
        ctx.fill();
        ctx.strokeStyle = '#1e293b';
        ctx.lineWidth = 2.5;
        ctx.stroke();

        // Center Bolt
        ctx.fillStyle = '#1e293b';
        ctx.beginPath();
        ctx.arc(0, 0, 3.5, 0, Math.PI * 2);
        ctx.fill();

        ctx.restore();

        window.mkAnimId = requestAnimationFrame(loop);
    }

    loop();
};

