window.bukaModalSenaraiSukuKata = function () {
    const grid = document.getElementById('senarai-sukukata-grid');
    if (!grid) return;
    grid.innerHTML = '';

    const isNumberModule = ['pengenalan_nombor', 'bilang_0_10', 'bilang_siri_nombor', 'konsep_tambah', 'konsep_penolakan'].includes(currentModuleId);
    grid.className = 'perkataan-grid grid-3-col';

    const titleEl = document.getElementById('senarai-sukukata-title');
    if (titleEl) {
        titleEl.innerText = isNumberModule ? "SENARAI NOMBOR" : "SENARAI PERKATAAN";
    }

    activeFlashcards.forEach((item, index) => {
        const btn = document.createElement('div');
        btn.className = 'neo-box perkataan-card';
        btn.onclick = () => {
            currentFlashcardIndex = index;
            renderBelajarSukuKata();
            tutupModalSenaraiSukuKata();
        };

        if (isNumberModule) {
            const textContainer = document.createElement('div');
            textContainer.className = 'perkataan-text-container';
            const textEl = document.createElement('div');
            textEl.className = 'century-gothic-font';
            textEl.style.fontWeight = '900';
            textEl.style.fontSize = '2.5rem';
            textEl.style.color = 'var(--color-dark)';
            textEl.style.lineHeight = '1';
            textEl.innerText = item.back || item.front;
            textContainer.appendChild(textEl);
            btn.appendChild(textContainer);
        } else {
            // Gambar / Icon di bahagian atas kad
            const imgContainer = document.createElement('div');
            imgContainer.className = 'perkataan-img-container';

            let iconContent = item.icon;
            if (!iconContent) {
                iconContent = '<img referrerpolicy="no-referrer" src="https://i.postimg.cc/tJnmbLrt/speaker-icon.png" class="sk-icon-img" alt="audio"/>';
            } else if (iconContent.includes('<img')) {
                iconContent = iconContent.replace('<img', '<img class="sk-icon-img"');
            } else if (iconContent.startsWith('http') || iconContent.startsWith('/') || iconContent.includes('.png')) {
                iconContent = `<img src="${iconContent}" class="sk-icon-img" alt="${item.front}"/>`;
            } else {
                iconContent = `<div style="font-size: 2.4rem;">${iconContent}</div>`;
            }
            imgContainer.innerHTML = iconContent;

            // Perkataan suku kata di bahagian bawah kad (format: 'a - lu', tulisan hitam seperti Screenshot 3)
            const textContainer = document.createElement('div');
            textContainer.className = 'perkataan-text-container';
            const textEl = document.createElement('div');
            textEl.className = 'perkataan-text century-gothic-font';

            let displayText = item.front || '';
            if (displayText.includes('-')) {
                displayText = displayText.split('-').map(p => p.trim()).join(' - ');
            }
            textEl.innerText = displayText;
            textEl.style.color = '#10182f';
            textContainer.appendChild(textEl);

            btn.appendChild(imgContainer);
            btn.appendChild(textContainer);
        }
        grid.appendChild(btn);
    });

    const modal = document.getElementById('modal-senarai-sukukata');
    if (modal) modal.style.display = 'flex';
};

