window.janaDiagnostikAI = function () {
    const container = document.getElementById('ai-diagnostic-content');
    if (!container) return;

    const namaKelas = localStorage.getItem('bunyiKataNamaKelas') || '-';
    const totalStudents = (studentNames && studentNames.length) ? studentNames.length : 0;

    if (totalStudents === 0) {
        container.innerHTML = `<p style="margin:0; color:#64748b;">Tiada data murid dalam kelas ini. Sila tambah murid dalam 'Urus Murid' terlebih dahulu.</p>`;
        return;
    }

    let totalTasksPossible = 0;
    let totalTasksSiap = 0;

    const mapStats = {
        1: { title: "Cabaran Kenal Huruf", siap: 0, total: 0 },
        2: { title: "Cabaran Suku Kata Asas", siap: 0, total: 0 },
        3: { title: "Cabaran Suku Kata Hero", siap: 0, total: 0 },
        4: { title: "Cabaran Bacaan Bergred", siap: 0, total: 0 }
    };

    const moduleStats = {};

    Object.keys(MAP_CHALLENGES).forEach(petaId => {
        const peta = MAP_CHALLENGES[petaId];
        peta.modules.forEach(mod => {
            moduleStats[mod.id] = { title: mod.title, petaId, siap: 0, total: 0 };

            studentNames.forEach(sName => {
                const sData = studentData[sName] || {};
                const isCompleted = Boolean(
                    (sData.scores && sData.scores[mod.id] > 0) ||
                    (sData.latihan && sData.latihan[mod.id]) ||
                    (sData.belajar && sData.belajar[mod.id])
                );

                totalTasksPossible++;
                if (mapStats[petaId]) mapStats[petaId].total++;
                moduleStats[mod.id].total++;

                if (isCompleted) {
                    totalTasksSiap++;
                    if (mapStats[petaId]) mapStats[petaId].siap++;
                    moduleStats[mod.id].siap++;
                }
            });
        });
    });

    const overallPct = totalTasksPossible > 0 ? Math.round((totalTasksSiap / totalTasksPossible) * 100) : 0;

    let hardestMod = null;
    let lowestPct = 101;

    let easiestMap = null;
    let highestMapPct = -1;

    Object.values(moduleStats).forEach(m => {
        const pct = m.total > 0 ? Math.round((m.siap / m.total) * 100) : 0;
        if (pct < lowestPct) {
            lowestPct = pct;
            hardestMod = m;
        }
    });

    Object.entries(mapStats).forEach(([pId, m]) => {
        const pct = m.total > 0 ? Math.round((m.siap / m.total) * 100) : 0;
        if (pct > highestMapPct) {
            highestMapPct = pct;
            easiestMap = m;
        }
    });

    const hardestTitle = hardestMod ? hardestMod.title : 'Suku Kata';
    const hardestSiapCount = hardestMod ? hardestMod.siap : 0;

    let aiAdvice = '';
    if (overallPct >= 80) {
        aiAdvice = `Prestasi cemerlang! Majoriti murid kelas <strong>${namaKelas}</strong> telah menguasai sebahagian besar modul. Teruskan galakan untuk melengkapkan baki tugasan.`;
    } else if (overallPct >= 40) {
        aiAdvice = `Murid telah menunjukkan kemajuan yang baik, namun menghadapi kesukaran khusus pada <strong>${hardestTitle}</strong> (${lowestPct}% siap, ${hardestSiapCount}/${totalStudents} murid). Syor AI: Jalankan bimbingan secara kumpulan kecil untuk modul ini.`;
    } else {
        aiAdvice = `Tahap penyelesaian awal. Cabaran utama murid fokus pada <strong>${hardestTitle}</strong>. Dicadangkan guru memberikan lebih fokus latihan bunyi suku kata interaktif dalam sesi PdP akan datang.`;
    }

    container.innerHTML = `
                <div style="display:flex; flex-direction:column; gap:8px;">
                    <p style="margin:0;"><i class="fa-solid fa-chart-line" style="color:#16a34a; margin-right:6px;"></i><strong>Kadar Penyelesaian Kelas:</strong> ${overallPct}% (${totalTasksSiap} daripada ${totalTasksPossible} tugasan diselesaikan oleh ${totalStudents} orang murid).</p>
                    <p style="margin:0;"><i class="fa-solid fa-triangle-exclamation" style="color:#dc2626; margin-right:6px;"></i><strong>Cabaran Paling Sukar:</strong> <span>${hardestTitle}</span> (Hanya ${lowestPct}% siap).</p>
                    <p style="margin:0;"><i class="fa-solid fa-circle-check" style="color:#2563eb; margin-right:6px;"></i><strong>Kekuatan Terbaik:</strong> <span>${easiestMap ? easiestMap.title : 'Kenal Huruf'}</span> (${highestMapPct}% siap).</p>
                    <div style="margin-top:6px; padding:10px 12px; background:white; border-radius:10px; border:1px solid #cbd5e1; color:#1e293b; font-size:0.8rem; line-height:1.4;">
                        <i class="fa-solid fa-lightbulb" style="color:#eab308; margin-right:6px;"></i><strong>Cadangan Tindakan AI:</strong> ${aiAdvice}
                    </div>
                </div>
            `;
};

window.renderStatistikPieChart = function () {
    const container = document.getElementById('pie-chart-container');
    if (!container) return;

    const totalStudents = (studentNames && studentNames.length) ? studentNames.length : 0;
    if (totalStudents === 0) {
        container.innerHTML = `<div style="text-align:center; color:#94a3b8; padding:20px; font-size:0.8rem;">Tiada data murid.</div>`;
        return;
    }

    let totalTasks = 0;
    let siapCount = 0;

    Object.keys(MAP_CHALLENGES).forEach(petaId => {
        MAP_CHALLENGES[petaId].modules.forEach(mod => {
            studentNames.forEach(sName => {
                totalTasks++;
                const sData = studentData[sName] || {};
                const isCompleted = Boolean(
                    (sData.scores && sData.scores[mod.id] > 0) ||
                    (sData.latihan && sData.latihan[mod.id]) ||
                    (sData.belajar && sData.belajar[mod.id])
                );
                if (isCompleted) siapCount++;
            });
        });
    });

    const belumCount = totalTasks - siapCount;
    const pctSiap = totalTasks > 0 ? Math.round((siapCount / totalTasks) * 100) : 0;
    const pctBelum = 100 - pctSiap;

    const size = 160;
    const strokeWidth = 24;
    const radius = (size - strokeWidth) / 2;
    const circumference = 2 * Math.PI * radius;
    const strokeDasharraySiap = (pctSiap / 100) * circumference;

    container.innerHTML = `
                <div style="display:flex; flex-direction:column; align-items:center; gap:14px; width:100%;">
                    <div style="position:relative; width:${size}px; height:${size}px; display:flex; align-items:center; justify-content:center;">
                        <svg width="${size}" height="${size}" viewBox="0 0 ${size} ${size}" style="transform: rotate(-90deg); overflow:visible;">
                            <circle 
                                cx="${size / 2}" cy="${size / 2}" r="${radius}" 
                                fill="transparent" 
                                stroke="#f87171" 
                                stroke-width="${strokeWidth}" 
                            />
                            <circle 
                                cx="${size / 2}" cy="${size / 2}" r="${radius}" 
                                fill="transparent" 
                                stroke="#22c55e" 
                                stroke-width="${strokeWidth}" 
                                stroke-dasharray="${strokeDasharraySiap} ${circumference}"
                                stroke-linecap="round"
                                style="transition: stroke-dasharray 0.6s ease;"
                            />
                        </svg>
                        <div style="position:absolute; text-align:center; pointer-events:none;">
                            <div style="font-size:1.4rem; font-weight:800; color:var(--color-dark); line-height:1;">${pctSiap}%</div>
                            <div style="font-size:0.68rem; font-weight:bold; color:#64748b; margin-top:2px;">Siap</div>
                        </div>
                    </div>

                    <div style="display:flex; justify-content:center; gap:16px; font-size:0.78rem; font-weight:bold; width:100%; border-top:1px solid #f1f5f9; padding-top:10px;">
                        <div style="display:flex; align-items:center; gap:6px;">
                            <span style="width:12px; height:12px; border-radius:50%; background:#22c55e; display:inline-block; border:1px solid #15803d;"></span>
                            <span>Siap: ${siapCount} (${pctSiap}%)</span>
                        </div>
                        <div style="display:flex; align-items:center; gap:6px;">
                            <span style="width:12px; height:12px; border-radius:50%; background:#f87171; display:inline-block; border:1px solid #b91c1c;"></span>
                            <span>Belum Siap: ${belumCount} (${pctBelum}%)</span>
                        </div>
                    </div>
                </div>
            `;
};

window.renderStatistikBarChart = function () {
    const container = document.getElementById('bar-chart-container');
    const filterEl = document.getElementById('statistik-bar-filter');
    if (!container) return;

    const selectedVal = filterEl ? filterEl.value : 'all';
    const totalStudents = (studentNames && studentNames.length) ? studentNames.length : 0;

    if (totalStudents === 0) {
        container.innerHTML = `<div style="text-align:center; color:#94a3b8; padding:20px; font-size:0.8rem;">Tiada data murid.</div>`;
        return;
    }

    let items = [];

    if (selectedVal === 'all') {
        Object.keys(MAP_CHALLENGES).forEach(petaId => {
            const peta = MAP_CHALLENGES[petaId];
            let petaTotal = 0;
            let petaSiap = 0;

            peta.modules.forEach(mod => {
                studentNames.forEach(sName => {
                    petaTotal++;
                    const sData = studentData[sName] || {};
                    if (
                        (sData.scores && sData.scores[mod.id] > 0) ||
                        (sData.latihan && sData.latihan[mod.id]) ||
                        (sData.belajar && sData.belajar[mod.id])
                    ) {
                        petaSiap++;
                    }
                });
            });

            items.push({
                label: peta.title,
                siap: petaSiap,
                total: petaTotal,
                pct: petaTotal > 0 ? Math.round((petaSiap / petaTotal) * 100) : 0
            });
        });
    } else {
        const peta = MAP_CHALLENGES[selectedVal];
        if (peta) {
            peta.modules.forEach(mod => {
                let modTotal = 0;
                let modSiap = 0;

                studentNames.forEach(sName => {
                    modTotal++;
                    const sData = studentData[sName] || {};
                    if (
                        (sData.scores && sData.scores[mod.id] > 0) ||
                        (sData.latihan && sData.latihan[mod.id]) ||
                        (sData.belajar && sData.belajar[mod.id])
                    ) {
                        modSiap++;
                    }
                });

                items.push({
                    label: mod.title,
                    siap: modSiap,
                    total: modTotal,
                    pct: modTotal > 0 ? Math.round((modSiap / modTotal) * 100) : 0
                });
            });
        }
    }

    let html = '<div style="display:flex; flex-direction:column; gap:10px; width:100%;">';
    items.forEach(item => {
        html += `
                    <div style="display:flex; flex-direction:column; gap:3px;">
                        <div style="display:flex; justify-content:space-between; font-size:0.75rem; font-weight:bold; color:var(--color-dark);">
                            <span style="white-space:nowrap; overflow:hidden; text-overflow:ellipsis; max-width:70%;">${item.label}</span>
                            <span style="color:#0284c7;">${item.siap}/${item.total} (${item.pct}%)</span>
                        </div>
                        <div style="width:100%; height:14px; background:#e2e8f0; border-radius:10px; border:1px solid #cbd5e1; overflow:hidden; position:relative;">
                            <div style="height:100%; width:${item.pct}%; background:linear-gradient(90deg, #38bdf8 0%, #0284c7 100%); border-radius:10px; transition:width 0.5s ease;"></div>
                        </div>
                    </div>
                `;
    });
    html += '</div>';

    container.innerHTML = html;
};

window.tambahMuridBaru = function () {
    const input = document.getElementById('input-nama-murid-baru');
    if (!input) return;
    const rawValue = input.value.trim();
    if (!rawValue) {
        if (typeof window.showAppModalAlert === 'function') {
            window.showAppModalAlert('Nama Murid Diperlukan', '<p style="text-align:center; font-weight:bold; color:#ef4444; margin:10px 0;">Sila masukkan nama murid terlebih dahulu!</p>');
        } else {
            alert('Sila masukkan nama murid!');
        }
        return;
    }

    const activeKelas = window.getKelasAktif();
    if (!activeKelas) {
        if (typeof window.showAppModalAlert === 'function') {
            window.showAppModalAlert('Tetapan Kelas Diperlukan', '<p style="text-align:center; font-weight:bold; color:#ef4444; margin:10px 0;">Sila tetapkan nama kelas terlebih dahulu di bahagian "Tetapan Nama Kelas" di bawah sebelum menambah murid!</p>');
        } else {
            alert('Sila tetapkan nama kelas terlebih dahulu di bahagian "Tetapan Nama Kelas" di bawah sebelum menambah murid!');
        }
        return;
    }
    const namesToAdd = typeof parseStudentNamesInput === 'function'
        ? parseStudentNamesInput(rawValue)
        : rawValue.split(/[\n,]+/).map(n => n.trim().toUpperCase()).filter(n => n.length > 0);

    let addedCount = 0;
    let duplicates = [];

    const GHOST_NAMES = ['TETAMU', 'MURID', 'GUEST', 'STUDENT'];
    namesToAdd.forEach(nama => {
        // Sekat nama sistem/dummy daripada didaftarkan sebagai murid
        if (GHOST_NAMES.includes(nama.toUpperCase())) {
            return;
        }
        if (studentNames.some(n => n && n.toUpperCase() === (nama || '').toUpperCase())) {
            duplicates.push(nama);
        } else {
            studentNames.push(nama);
            if (!studentData[nama]) {
                studentData[nama] = studentRecord();
            }
            studentData[nama].kelas = activeKelas;
            addedCount++;

            // Segerakkan murid ke Firebase dengan guru_id dan kod_kelas lengkap
            if (typeof window.syncStudentToFirebase === 'function') {
                window.syncStudentToFirebase({
                    nama: nama,
                    guruId: localStorage.getItem('bunyiKataUserId') || '',
                    guruEmail: localStorage.getItem('bunyiKataGuruEmail') || '',
                    kodKelas: localStorage.getItem('bunyiKataKodKelas') || '',
                    namaKelas: activeKelas,
                    totalBintang: 0
                }).catch(e => console.warn('Student sync notice:', e));
            }
        }
    });

    if (addedCount > 0) {
        // Pastikan senarai murid sentiasa tersusun mengikut abjad (A-Z)
        studentNames.sort((a, b) => a.localeCompare(b, 'ms', { sensitivity: 'base' }));
        window.studentNames = studentNames;
        saveStudentData();
        input.value = '';
        renderSenaraiMuridUrus();
        updateStudentDropdown();
        if (typeof window.renderTeacherTable === 'function') window.renderTeacherTable();
    }

    if (typeof window.showAppModalAlert === 'function') {
        if (duplicates.length > 0 && addedCount === 0) {
            window.showAppModalAlert('Nama Telah Wujud', '<p style="text-align:center; font-weight:bold; color:#ef4444; margin:10px 0;">Semua nama murid yang dimasukkan sudah wujud dalam senarai kelas!</p>');
        } else if (duplicates.length > 0) {
            window.showAppModalAlert('Maklumat Murid Ditambah', `<p style="text-align:center; font-weight:bold; color:#1e293b; margin:10px 0;"><span style="color:#15803d;">${addedCount} orang murid berjaya ditambah ke kelas "${activeKelas}".</span><br><br><span style="color:#ef4444; font-size:0.9rem;">Nama yang diabaikan (sudah wujud):<br>${duplicates.join(', ')}</span></p>`);
        } else {
            window.showAppModalAlert('Berjaya Ditambah', `<p style="text-align:center; font-weight:bold; color:#15803d; margin:10px 0;"><i class="fa-solid fa-circle-check" style="font-size:2rem; color:#22c55e; display:block; margin-bottom:8px;"></i>${addedCount} orang murid berjaya ditambah ke kelas <strong>"${activeKelas}"</strong>!</p>`);
        }
    } else {
        if (duplicates.length > 0 && addedCount === 0) {
            alert('Semua nama murid tersebut sudah wujud dalam senarai!');
        } else if (duplicates.length > 0) {
            alert(addedCount + ' murid berjaya ditambah ke kelas "' + activeKelas + '".\nTerdapat nama yang diabaikan kerana sudah wujud:\n' + duplicates.join(', '));
        } else {
            alert(addedCount + ' murid berjaya ditambah.');
        }
    }
};

window.padamMurid = function (nama) {
    if (!nama) return;
    window.showAppModalConfirm(
        `Adakah anda pasti untuk memadam data murid "${nama}" daripada senarai?`,
        function () {
            studentNames = studentNames.filter(n => n !== nama);
            window.studentNames = studentNames;
            if (studentData[nama]) delete studentData[nama];
            if (window.studentData && window.studentData[nama]) delete window.studentData[nama];
            saveStudentData();
            if (typeof window.deleteStudentByNameFromFirebase === 'function') {
                window.deleteStudentByNameFromFirebase(nama, {
                    guruId: localStorage.getItem('bunyiKataUserId') || '',
                    kodKelas: localStorage.getItem('bunyiKataKodKelas') || ''
                }).catch(e => console.warn('Delete student remote notice:', e));
            }
            renderSenaraiMuridUrus();
            updateStudentDropdown();
            if (typeof window.renderTeacherTable === 'function') window.renderTeacherTable();
        }
    );
};

