window.resetLatihanSemasa = function (latihanKey, viewId) {
    if (confirm('Adakah anda pasti ingin menetapkan semula progres untuk latihan ini?')) {
        if (window.namaMuridAktif) {
            // clear auto save
            const dataAuto = JSON.parse(localStorage.getItem('bunyiKataAutoSave') || '{}');
            if (dataAuto[window.namaMuridAktif]) {
                delete dataAuto[window.namaMuridAktif][latihanKey];
                localStorage.setItem('bunyiKataAutoSave', JSON.stringify(dataAuto));
            }

            // clear student data
            if (window.studentData && window.studentData[window.namaMuridAktif]) {
                const sData = window.studentData[window.namaMuridAktif];
                if (sData.latihan) sData.latihan[latihanKey] = false;
                if (sData.scores) sData.scores[latihanKey] = 0;

                if (typeof window.saveStudentData === 'function') {
                    window.saveStudentData();
                }
            }

            // Re-initialize view
            if (typeof window.navigate === 'function') {
                document.querySelectorAll('.screen').forEach(s => s.classList.remove('active')); setTimeout(() => window.navigate(viewId, null), 10);
            }
        }
    }
}

window.renderGuruSenaraiPerkataan = function (moduleId, prefix) {
    if (!moduleId) {
        const activeSelect = document.getElementById(`${prefix || 'guru'}-modul-select`) ||
            document.getElementById('guru-modul-select') ||
            document.getElementById('admin-modul-select') ||
            document.getElementById('ibubapa-modul-select');
        moduleId = activeSelect ? activeSelect.value : 'suku_kata_kv';
    }

    const prefixes = ['guru', 'admin', 'ibubapa'];
    prefixes.forEach(p => {
        const selectEl = document.getElementById(`${p}-modul-select`);
        if (selectEl) selectEl.value = moduleId;

        const listContainer = document.getElementById(`${p}-perkataan-list`);
        if (!listContainer) return;

        if (!moduleContentData || !moduleContentData[moduleId] || !moduleContentData[moduleId].flashcards) {
            listContainer.innerHTML = '<p style="color: white; font-weight: bold;">Tiada data untuk modul ini.</p>';
            return;
        }

        const cards = moduleContentData[moduleId].flashcards;

        let html = `<div class="perkataan-grid ${moduleId === 'suku_kata_kv' ? 'grid-kv' : ''}">`;
        cards.forEach(card => {
            let frontText = card.front;
            if (frontText.includes('-')) {
                frontText = frontText.split('-').map((p, i) => `<span style="color: ${i % 2 === 0 ? 'black' : 'red'};">${p.trim()}</span>`).join('');
            } else {
                frontText = `<span style="color: black;">${frontText}</span>`;
            }

            let displayIcon = '';
            if (moduleId !== 'suku_kata_kv') {
                displayIcon = card.icon;
                if (!displayIcon) {
                    displayIcon = '<img referrerpolicy="no-referrer" src="https://i.postimg.cc/tJnmbLrt/speaker-icon.png" class="sk-icon-img" alt="audio"/>';
                } else if (displayIcon.includes('<img')) {
                    displayIcon = displayIcon.replace('<img', '<img class="sk-icon-img"');
                } else if (displayIcon.startsWith('http') || displayIcon.startsWith('/') || displayIcon.includes('.png')) {
                    displayIcon = `<img src="${displayIcon}" class="sk-icon-img" alt="${card.front}"/>`;
                } else if (displayIcon.startsWith('<')) {
                    // already HTML
                } else {
                    displayIcon = `<div style="font-size: 2.8rem;">${displayIcon}</div>`;
                }
                displayIcon = `<div class="perkataan-img-container">${displayIcon}</div>`;
            }

            html += `
            <div class="neo-box perkataan-card">
                ${displayIcon}
                <div class="perkataan-text-container">
                    <div class="perkataan-text century-gothic-font">${frontText}</div>
                </div>
            </div>
            `;
        });
        html += '</div>';
        listContainer.innerHTML = html;
    });
};


function requestSensorPermissionAndStart(type, arg) {
    const existingModal = document.getElementById('sensor-permission-modal');
    if (existingModal) existingModal.remove();

    const modalHtml = `
        <div id="sensor-permission-modal" class="modal-overlay" style="z-index: 100000; display: flex; align-items: center; justify-content: center; background: rgba(0,0,0,0.85); position: fixed; top: 0; left: 0; width: 100vw; height: 100vh;">
            <div class="neo-box" style="text-align: center; max-width: 420px; width: 90%; padding: 24px 20px; padding: 20px 15px; background: white; border-radius: 16px; box-shadow: 0 10px 25px rgba(0,0,0,0.5); margin: 0 auto;">
                <h3 style="margin-bottom: 10px; font-size: 1.2rem; color: #1e293b; font-weight: bold;">Akses Peranti</h3>
                <p style="margin-bottom: 20px; color: #475569; font-size: 0.9rem; line-height: 1.4;">Benarkan akses pergerakan (motion & orientation) untuk mengawal mod 3D/AR.</p>
                <div style="display: flex; gap: 10px; justify-content: center;">
                    <button id="btn-allow-sensor" class="neo-btn bg-green" style="padding: 10px 15px; font-size: 0.95rem; flex: 1;">Benarkan</button>
                    <button id="btn-deny-sensor" class="neo-btn bg-red" style="padding: 10px 15px; font-size: 0.95rem; flex: 1;">Batal</button>
                </div>
            </div>
        </div>
    `;

    document.body.insertAdjacentHTML('beforeend', modalHtml);

    document.getElementById('btn-deny-sensor').onclick = () => {
        const m = document.getElementById('sensor-permission-modal');
        if (m) m.remove();
    };

    document.getElementById('btn-allow-sensor').onclick = () => {
        const m = document.getElementById('sensor-permission-modal');
        if (m) m.remove();

        // Unlock speech synthesis on user interaction!
        if (window.sebutAudio) {
            window.sebutAudio('');
        }

        const startScene = () => {
            console.log('Starting scene:', type);
            if (type === 'vr') startVRScene();
            else if (type === 'vr-bacaan') startVRBacaanScene();
            else if (type === 'vr-nombor') startVRNomborScene();
            else if (type === 'ar') startARScene();
            else if (type === 'ar-abc') {
                if (window.bukaARABCSebenar) {
                    window.bukaARABCSebenar();
                } else {
                    startARScene();
                }
            }
            else if (type === 'ar-sukukata') {
                if (window.bukaARSukuKataKemahiranSebenar) {
                    window.bukaARSukuKataKemahiranSebenar(arg);
                } else {
                    console.error("bukaARSukuKataKemahiranSebenar not found!");
                }
            }
            else if (type === 'ar-kirajari') {
                if (window.bukaARKiraJariSebenar) {
                    window.bukaARKiraJariSebenar(arg);
                } else if (window.bukaARKiraJari) {
                    window.bukaARKiraJari(arg);
                }
            }
            else if (type === 'perpustakaan') {
                if (window.setPerpustakaanHeroMode) {
                    window.setPerpustakaanHeroMode(arg);
                }
                window.paparSkrin('view-perpustakaan');
            }
        };

        if (typeof DeviceOrientationEvent !== 'undefined' && typeof DeviceOrientationEvent.requestPermission === 'function') {
            DeviceOrientationEvent.requestPermission()
                .then(permissionState => {
                    if (permissionState === 'granted') {
                        startScene();
                    } else {
                        alert('Akses penderia ditolak. Pengalaman 3D/AR mungkin terhad.');
                        startScene(); // Fallback
                    }
                })
                .catch(e => {
                    console.error('DeviceOrientationEvent error:', e);
                    startScene();
                });
        } else {
            startScene();
        }
    };
}

window.bukaVR = function () {
    requestSensorPermissionAndStart('vr');
};

window.bukaVRBacaan = function () {
    requestSensorPermissionAndStart('vr-bacaan');
};

// Keep legacy aliases
window.bukaVRABC = window.bukaVR;
window.bukaVRNombor = window.bukaVR;

function startVRScene() {
    startMuseumVRScene();
}

function startVRNomborScene() {
    startMuseumVRScene();
}

window.vrCamYaw = 0;
window.vrCamPitch = 0;
window.vrCameraTouchId = null;
window.vrLastTouchX = 0;
window.vrLastTouchY = 0;
window.vrMouseDragging = false;
window.vrLastMouseX = 0;
window.vrLastMouseY = 0;

window.vrResetInputs = function () {
    window.vrKeysState = {
        w: false, a: false, s: false, d: false,
        ArrowUp: false, ArrowDown: false, ArrowLeft: false, ArrowRight: false
    };
    window.vrJoystickInput = { x: 0, y: 0 };
    window.vrIsJoystickDragging = false;
    window.vrJoystickTouchId = null;
    window.vrCameraTouchId = null;
    window.vrMouseDragging = false;
    const knob = document.querySelector('.vr-joystick-knob');
    if (knob) knob.style.transform = 'translate(0px, 0px)';
};

function initVRInputListeners() {
    window.vrResetInputs();
    window.vrAutoPlayActive = false;

    if (!window.vrKeysInitialized) {
        window.vrKeysInitialized = true;

        const handleKeyDown = (e) => {
            if (e.target instanceof HTMLInputElement || e.target instanceof HTMLTextAreaElement) return;
            const code = e.code;
            const key = e.key ? e.key.toLowerCase() : '';

            if (code === 'KeyW' || key === 'w') window.vrKeysState.w = true;
            if (code === 'KeyS' || key === 's') window.vrKeysState.s = true;
            if (code === 'KeyA' || key === 'a') window.vrKeysState.a = true;
            if (code === 'KeyD' || key === 'd') window.vrKeysState.d = true;
            if (code === 'ArrowUp' || key === 'arrowup') window.vrKeysState.ArrowUp = true;
            if (code === 'ArrowDown' || key === 'arrowdown') window.vrKeysState.ArrowDown = true;
            if (code === 'ArrowLeft' || key === 'arrowleft') window.vrKeysState.ArrowLeft = true;
            if (code === 'ArrowRight' || key === 'arrowright') window.vrKeysState.ArrowRight = true;
        };

        const handleKeyUp = (e) => {
            const code = e.code;
            const key = e.key ? e.key.toLowerCase() : '';

            if (code === 'KeyW' || key === 'w') window.vrKeysState.w = false;
            if (code === 'KeyS' || key === 's') window.vrKeysState.s = false;
            if (code === 'KeyA' || key === 'a') window.vrKeysState.a = false;
            if (code === 'KeyD' || key === 'd') window.vrKeysState.d = false;
            if (code === 'ArrowUp' || key === 'arrowup') window.vrKeysState.ArrowUp = false;
            if (code === 'ArrowDown' || key === 'arrowdown') window.vrKeysState.ArrowDown = false;
            if (code === 'ArrowLeft' || key === 'arrowleft') window.vrKeysState.ArrowLeft = false;
            if (code === 'ArrowRight' || key === 'arrowright') window.vrKeysState.ArrowRight = false;
        };

        window.addEventListener('keydown', handleKeyDown, { passive: false });
        window.addEventListener('keyup', handleKeyUp, { passive: true });

        const isTouchOnInteractiveUI = (el) => {
            if (!el) return false;
            return !!el.closest('#vr-joystick-container, .vr-joystick-container, .map-top-bar, .neo-btn, #vr-station-popup, #vr-buku-prompt-modal, #vr-buku-reader-modal, .vr-guide-overlay');
        };

        // Touch Listeners for Camera Rotation / Screen Orientation (Multi-touch enabled alongside joystick)
        const handleSceneTouchStart = (e) => {
            const vrScreen = document.getElementById('view-vr-abc');
            if (!vrScreen || !vrScreen.classList.contains('active')) return;
            if (isTouchOnInteractiveUI(e.target)) return;

            for (let i = 0; i < e.changedTouches.length; i++) {
                const touch = e.changedTouches[i];
                if (touch.identifier === window.vrJoystickTouchId) continue;
                if (window.vrCameraTouchId == null) {
                    window.vrCameraTouchId = touch.identifier;
                    window.vrLastTouchX = touch.clientX;
                    window.vrLastTouchY = touch.clientY;
                    break;
                }
            }
        };

        const handleSceneTouchMove = (e) => {
            const vrScreen = document.getElementById('view-vr-abc');
            if (!vrScreen || !vrScreen.classList.contains('active')) return;
            if (window.vrCameraTouchId == null) return;

            let touch = null;
            for (let i = 0; i < e.touches.length; i++) {
                if (e.touches[i].identifier === window.vrCameraTouchId) {
                    touch = e.touches[i];
                    break;
                }
            }
            if (!touch) return;

            const deltaX = touch.clientX - window.vrLastTouchX;
            const deltaY = touch.clientY - window.vrLastTouchY;
            window.vrLastTouchX = touch.clientX;
            window.vrLastTouchY = touch.clientY;

            // Dragging left (deltaX < 0) -> camera rotates to the LEFT (vrCamYaw increases)
            // Dragging right (deltaX > 0) -> camera rotates to the RIGHT (vrCamYaw decreases)
            const rotSpeed = 0.0055;
            window.vrCamYaw = (window.vrCamYaw || 0) - deltaX * rotSpeed;
            window.vrCamPitch = Math.max(-0.45, Math.min(0.55, (window.vrCamPitch || 0) + deltaY * rotSpeed * 0.7));
        };

        const handleSceneTouchEnd = (e) => {
            if (window.vrCameraTouchId != null) {
                for (let i = 0; i < e.changedTouches.length; i++) {
                    if (e.changedTouches[i].identifier === window.vrCameraTouchId) {
                        window.vrCameraTouchId = null;
                        break;
                    }
                }
            }
        };

        window.addEventListener('touchstart', handleSceneTouchStart, { passive: true });
        window.addEventListener('touchmove', handleSceneTouchMove, { passive: true });
        window.addEventListener('touchend', handleSceneTouchEnd, { passive: true });
        window.addEventListener('touchcancel', handleSceneTouchEnd, { passive: true });

        // Mouse Drag Listeners for Desktop testing
        const handleSceneMouseDown = (e) => {
            const vrScreen = document.getElementById('view-vr-abc');
            if (!vrScreen || !vrScreen.classList.contains('active')) return;
            if (isTouchOnInteractiveUI(e.target)) return;
            if (e.button !== 0) return;

            window.vrMouseDragging = true;
            window.vrLastMouseX = e.clientX;
            window.vrLastMouseY = e.clientY;
        };

        const handleSceneMouseMove = (e) => {
            if (!window.vrMouseDragging) return;
            const deltaX = e.clientX - window.vrLastMouseX;
            const deltaY = e.clientY - window.vrLastMouseY;
            window.vrLastMouseX = e.clientX;
            window.vrLastMouseY = e.clientY;

            const rotSpeed = 0.0055;
            window.vrCamYaw = (window.vrCamYaw || 0) - deltaX * rotSpeed;
            window.vrCamPitch = Math.max(-0.45, Math.min(0.55, (window.vrCamPitch || 0) + deltaY * rotSpeed * 0.7));
        };

        const handleSceneMouseUp = () => {
            window.vrMouseDragging = false;
        };

        window.addEventListener('mousedown', handleSceneMouseDown, { passive: true });
        window.addEventListener('mousemove', handleSceneMouseMove, { passive: true });
        window.addEventListener('mouseup', handleSceneMouseUp, { passive: true });

        // Ensure character never continues walking when user switches tabs or loses focus
        window.addEventListener('blur', window.vrResetInputs);
        window.addEventListener('focus', window.vrResetInputs);
        document.addEventListener('visibilitychange', () => {
            if (document.hidden) window.vrResetInputs();
        });
    }
}

function checkVrBacaanCollision(x, z, radius) {
    radius = radius || 0.35;
    // 1. Outer boundaries (60x60m complex)
    if (Math.abs(x) > 29.0 - radius || Math.abs(z) > 29.0 - radius) return true;

    function inBox(minX, maxX, minZ, maxZ) {
        return (x >= minX - radius && x <= maxX + radius && z >= minZ - radius && z <= maxZ + radius);
    }

    // Room 1 (Dewan Ayat Pendek - North: X: -7 to +7, Z: -28 to -15.8)
    if (inBox(-7.2, -6.8, -28.2, -15.8)) return true; // West wall
    if (inBox(6.8, 7.2, -28.2, -15.8)) return true; // East wall
    if (inBox(-7.2, 7.2, -28.2, -27.8)) return true; // North back wall
    if (inBox(-4.6, -3.8, -16.2, -15.4)) return true; // Archway post Left
    if (inBox(3.8, 4.6, -16.2, -15.4)) return true; // Archway post Right

    // Room 2 (Dewan Ayat Panjang - North-East: X: 13.8 to 29, Z: -17 to -5)
    if (inBox(13.8, 29.2, -17.2, -16.8)) return true; // North wall
    if (inBox(13.8, 29.2, -5.2, -4.8)) return true; // South wall
    if (inBox(28.8, 29.2, -17.2, -4.8)) return true; // East back wall
    if (inBox(13.4, 14.2, -16.2, -15.4)) return true; // Archway post North
    if (inBox(13.4, 14.2, -6.6, -5.8)) return true; // Archway post South

    // Room 3 (Galeri Petikan Tahap 1 - South-East: X: 13.8 to 29, Z: 5 to 17)
    if (inBox(13.8, 29.2, 4.8, 5.2)) return true; // North wall
    if (inBox(13.8, 29.2, 16.8, 17.2)) return true; // South wall
    if (inBox(28.8, 29.2, 4.8, 17.2)) return true; // East back wall
    if (inBox(13.4, 14.2, 5.8, 6.6)) return true; // Archway post North
    if (inBox(13.4, 14.2, 15.4, 16.2)) return true; // Archway post South

    // Room 4 (Galeri Petikan Tahap 2 - North-West: X: -29 to -13.8, Z: -17 to -5)
    if (inBox(-29.2, -13.8, -17.2, -16.8)) return true; // North wall
    if (inBox(-29.2, -13.8, -5.2, -4.8)) return true; // South wall
    if (inBox(-29.2, -28.8, -17.2, -4.8)) return true; // West back wall
    if (inBox(-14.2, -13.4, -16.2, -15.4)) return true; // Archway post North
    if (inBox(-14.2, -13.4, -6.6, -5.8)) return true; // Archway post South

    // Room 5 (Pavilion Cerita Pendek - South-West: X: -29 to -13.8, Z: 5 to 17)
    if (inBox(-29.2, -13.8, 4.8, 5.2)) return true; // North wall
    if (inBox(-29.2, -13.8, 16.8, 17.2)) return true; // South wall
    // Solid Grand Bookshelves & Reading Furniture (South Gallery)
    if (inBox(-24.8, -22.2, 22.0, 25.0)) return true; // Left Grand Bookshelf
    if (inBox(22.2, 24.8, 22.0, 25.0)) return true; // Right Grand Bookshelf
    if (inBox(-11.2, -8.8, 19.5, 21.5)) return true; // Left Study Table
    if (inBox(8.8, 11.2, 19.5, 21.5)) return true; // Right Study Table
    if (inBox(-19.5, -16.5, 19.5, 21.5)) return true; // Left Reading Sofa
    if (inBox(16.5, 19.5, 19.5, 21.5)) return true; // Right Reading Sofa

    // Solid Corridor Glass Podiums
    if (inBox(20.9, 22.1, -0.6, 0.6)) return true;
    if (inBox(-22.1, -20.9, -0.6, 0.6)) return true;

    return false;
}

function checkVrMuseumCollision(x, z, radius) {
    radius = radius || 0.35;
    // Outer boundaries (60x60m palace complex)
    if (Math.abs(x) > 29.0 - radius || Math.abs(z) > 29.0 - radius) return true;

    function inBox(minX, maxX, minZ, maxZ) {
        return (x >= minX - radius && x <= maxX + radius && z >= minZ - radius && z <= maxZ + radius);
    }

    // 4 Solid Corner Blocks dividing the 4 Wings from the Central Atrium:
    // NW Block: Between West Wing and North Wing
    if (inBox(-29.2, -10.0, -29.2, -10.0)) return true;
    // NE Block: Between North Wing and East Wing
    if (inBox(10.0, 29.2, -29.2, -10.0)) return true;
    // SW Block: Between West Wing and South Wing
    if (inBox(-29.2, -10.0, 10.0, 29.2)) return true;
    // SE Block: Between South Wing and East Wing
    if (inBox(10.0, 29.2, 10.0, 29.2)) return true;

    // Archway posts with generous door openings (~7m wide)
    // North Archway (leading to Dewan Huruf Fonik at Z: -10)
    if (inBox(-5.2, -4.4, -10.4, -9.6)) return true;
    if (inBox(4.4, 5.2, -10.4, -9.6)) return true;

    // South Archway (leading to Dewan Huruf Kecil at Z: 10)
    if (inBox(-5.2, -4.4, 9.6, 10.4)) return true;
    if (inBox(4.4, 5.2, 9.6, 10.4)) return true;

    // West Archway (leading to Galeri Asas Nombor at X: -10)
    if (inBox(-10.4, -9.6, -5.2, -4.4)) return true;
    if (inBox(-10.4, -9.6, 4.4, 5.2)) return true;

    // East Archway (leading to Galeri Siri Nombor at X: 10)
    if (inBox(9.6, 10.4, -5.2, -4.4)) return true;
    if (inBox(9.6, 10.4, 4.4, 5.2)) return true;

    // Center fountain is non-blocking so player can walk freely and never get stuck
    return false;
}

// Interactive 3D Character Movement & Camera-Relative Movement Controller
if (typeof AFRAME !== 'undefined' && !AFRAME.components['vr-player-controller']) {
    AFRAME.registerComponent('vr-player-controller', {
        init: function () {
            const posAttr = this.el.getAttribute('position') || { x: 0, y: 0, z: 4.5 };
            this.charPos = {
                x: (posAttr.x !== undefined && posAttr.x !== null) ? Number(posAttr.x) : 0,
                z: (posAttr.z !== undefined && posAttr.z !== null) ? Number(posAttr.z) : 4.5
            };
            this.charRotation = 0;
            this.animTime = 0;
            this.lastStationTriggered = null;
            this.stationCooldown = 5.0; // 5-second initial grace cooldown on spawn/respawn
            this.armLeft = document.getElementById('vr-arm-left');
            this.armRight = document.getElementById('vr-arm-right');
            this.legLeft = document.getElementById('vr-leg-left');
            this.legRight = document.getElementById('vr-leg-right');
            this.cameraRig = document.getElementById('camera-rig');
            this._wasMoving = false;
            this._footstepTimer = 0;
            this._footstepInterval = 0.32; // seconds between footstep sounds
            this._footstepToggle = false;

            // Audio effects for footsteps & station discovery
            this._playFootstep = () => {
                try {
                    const AudioCtx = window.AudioContext || window.webkitAudioContext;
                    if (AudioCtx) {
                        const ctx = new AudioCtx();
                        const osc = ctx.createOscillator();
                        const gain = ctx.createGain();
                        osc.type = 'sine';
                        this._footstepToggle = !this._footstepToggle;
                        osc.frequency.setValueAtTime(this._footstepToggle ? 140 : 120, ctx.currentTime);
                        osc.frequency.exponentialRampToValueAtTime(50, ctx.currentTime + 0.08);
                        gain.gain.setValueAtTime(0.04, ctx.currentTime);
                        gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.08);
                        osc.connect(gain);
                        gain.connect(ctx.destination);
                        osc.start();
                        osc.stop(ctx.currentTime + 0.08);
                    }
                } catch (e) { }
            };

            this._playStationChime = () => {
                try {
                    const AudioCtx = window.AudioContext || window.webkitAudioContext;
                    if (AudioCtx) {
                        const ctx = new AudioCtx();
                        const notes = [523.25, 659.25, 783.99, 1046.50]; // C5, E5, G5, C6 (cheerful major chord)
                        notes.forEach((freq, idx) => {
                            const osc = ctx.createOscillator();
                            const gain = ctx.createGain();
                            osc.type = 'triangle';
                            osc.frequency.setValueAtTime(freq, ctx.currentTime + idx * 0.08);
                            gain.gain.setValueAtTime(0.09, ctx.currentTime + idx * 0.08);
                            gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + idx * 0.08 + 0.35);
                            osc.connect(gain);
                            gain.connect(ctx.destination);
                            osc.start(ctx.currentTime + idx * 0.08);
                            osc.stop(ctx.currentTime + idx * 0.08 + 0.35);
                        });
                    }
                } catch (e) { }
            };

            // Double tap to jump/cheer animation
            let lastTapTime = 0;
            window.addEventListener('click', (e) => {
                if (e.target.closest('#vr-joystick-container') || e.target.closest('.neo-btn') || e.target.closest('#vr-station-popup')) return;
                const now = Date.now();
                if (now - lastTapTime < 320) {
                    // Double tap cheer
                    const bodyMesh = document.getElementById('vr-player-body');
                    if (bodyMesh) {
                        bodyMesh.setAttribute('animation__cheer', 'property: position; to: 0 1.25 0; dur: 220; dir: alternate; loop: 2; easing: easeOutQuad');
                        setTimeout(() => bodyMesh.removeAttribute('animation__cheer'), 500);
                    }
                }
                lastTapTime = now;
            });

            if (window.vrResetInputs) window.vrResetInputs();
        },

        tick: function (time, delta) {
            if (!delta) delta = 16;
            const dt = Math.min(delta / 1000, 0.05);

            // Check if VR screen is active
            const vrScreen = document.getElementById('view-vr-abc');
            if (!vrScreen || !vrScreen.classList.contains('active')) {
                return;
            }

            // Check if any popup modal is active
            const stationPopup = document.getElementById('vr-station-popup');
            const isStationPopupOpen = stationPopup && stationPopup.classList.contains('active');
            const guideModal = document.getElementById('vr-guide-modal') || document.querySelector('.vr-guide-modal-container') || document.querySelector('.vr-guide-overlay');
            const isGuideModalOpen = guideModal && (guideModal.style.display !== 'none' && !guideModal.classList.contains('hidden'));
            const bookPromptModal = document.getElementById('vr-buku-prompt-modal');
            const isBookPromptOpen = bookPromptModal && bookPromptModal.style.display === 'flex';
            const bookReaderModal = document.getElementById('vr-buku-reader-modal');
            const isBookReaderOpen = bookReaderModal && bookReaderModal.style.display === 'flex';

            if (isStationPopupOpen || isGuideModalOpen || isBookPromptOpen || isBookReaderOpen) {
                if (window.vrResetInputs) window.vrResetInputs();
                if (this.legLeft) this.legLeft.setAttribute('rotation', '0 0 0');
                if (this.legRight) this.legRight.setAttribute('rotation', '0 0 0');
                if (this.armLeft) this.armLeft.setAttribute('rotation', '0 0 0');
                if (this.armRight) this.armRight.setAttribute('rotation', '0 0 0');
                return;
            }

            // Read raw inputs
            let moveX = 0;
            let moveZ = 0;

            // Keyboard (WASD & Arrow Keys)
            if (window.vrKeysState) {
                if (window.vrKeysState.w || window.vrKeysState.ArrowUp) moveZ -= 1;
                if (window.vrKeysState.s || window.vrKeysState.ArrowDown) moveZ += 1;
                if (window.vrKeysState.a || window.vrKeysState.ArrowLeft) moveX -= 1;
                if (window.vrKeysState.d || window.vrKeysState.ArrowRight) moveX += 1;
            }

            // Virtual Joystick
            if (window.vrJoystickInput) {
                const jx = window.vrJoystickInput.x;
                const jy = window.vrJoystickInput.y;
                if (Math.abs(jx) > 0.12) moveX += jx;
                if (Math.abs(jy) > 0.12) moveZ += jy;
            }

            const mag = Math.sqrt(moveX * moveX + moveZ * moveZ);
            const isMoving = mag > 0.12;

            // Read Camera Yaw (rotation around Y-axis) & Pitch
            let camYaw = window.vrCamYaw || 0;
            let camPitch = window.vrCamPitch || 0;
            if (this.cameraRig) {
                const camEl = this.cameraRig.querySelector('a-camera');
                if (camEl && camEl.object3D) {
                    camEl.object3D.rotation.order = 'YXZ';
                    camEl.object3D.rotation.y = camYaw;
                    camEl.object3D.rotation.x = camPitch;
                    camEl.object3D.rotation.z = 0;
                }
            }

            const isBacaanMode = window.vrCurrentMode === 'bacaan';
            const roomLimit = 28.5;

            if (isMoving) {
                const normX = moveX / Math.max(1, mag);
                const normZ = moveZ / Math.max(1, mag);

                // Convert input to world movement vector relative to camera look angle
                const worldX = normX * Math.cos(camYaw) + normZ * Math.sin(camYaw);
                const worldZ = -normX * Math.sin(camYaw) + normZ * Math.cos(camYaw);

                const speed = 5.4; // meters per second

                const tryX = this.charPos.x + worldX * speed * dt;
                const tryZ = this.charPos.z + worldZ * speed * dt;

                // Solid wall collision detection with smooth sliding
                const collisionFunc = isBacaanMode ? checkVrBacaanCollision : checkVrMuseumCollision;
                const radius = 0.35;
                // Test full movement
                if (!collisionFunc(tryX, tryZ, radius)) {
                    this.charPos.x = tryX;
                    this.charPos.z = tryZ;
                } else {
                    // Slide along X axis
                    if (!collisionFunc(tryX, this.charPos.z, radius)) {
                        this.charPos.x = tryX;
                    }
                    // Slide along Z axis
                    if (!collisionFunc(this.charPos.x, tryZ, radius)) {
                        this.charPos.z = tryZ;
                    }
                }

                // Character faces the movement direction
                this.charRotation = Math.atan2(worldX, worldZ) * (180 / Math.PI);

                // Update Character Position & Rotation
                this.el.setAttribute('position', `${this.charPos.x} 0 ${this.charPos.z}`);
                this.el.setAttribute('rotation', `0 ${this.charRotation} 0`);

                // Smooth walk animation
                this.animTime += dt * 14;
                const swing = Math.sin(this.animTime) * 26;
                const bob = Math.abs(Math.sin(this.animTime)) * 0.05;

                if (this.legLeft) this.legLeft.setAttribute('rotation', `${swing} 0 0`);
                if (this.legRight) this.legRight.setAttribute('rotation', `${-swing} 0 0`);
                if (this.armLeft) this.armLeft.setAttribute('rotation', `${-swing * 0.75} 0 0`);
                if (this.armRight) this.armRight.setAttribute('rotation', `${swing * 0.75} 0 0`);

                const bodyMesh = document.getElementById('vr-player-body');
                if (bodyMesh) {
                    bodyMesh.removeAttribute('animation');
                    bodyMesh.setAttribute('position', `0 ${0.72 + bob} 0`);
                }

                // Footstep sound effect
                this._footstepTimer += dt;
                if (this._footstepTimer >= this._footstepInterval) {
                    this._footstepTimer = 0;
                    this._playFootstep();
                }

                this._wasMoving = true;
            } else {
                // Idle pose
                if (this.legLeft) this.legLeft.setAttribute('rotation', '0 0 0');
                if (this.legRight) this.legRight.setAttribute('rotation', '0 0 0');
                if (this.armLeft) this.armLeft.setAttribute('rotation', '0 0 0');
                if (this.armRight) this.armRight.setAttribute('rotation', '0 0 0');

                // Restore idle breathing animation when transitioning from moving to idle
                if (this._wasMoving) {
                    const bodyMesh = document.getElementById('vr-player-body');
                    if (bodyMesh) {
                        bodyMesh.setAttribute('animation', 'property: position; from: 0 0.72 0; to: 0 0.75 0; dir: alternate; loop: true; dur: 1800; easing: easeInOutSine');
                    }
                    this._wasMoving = false;
                    this._footstepTimer = 0;
                }
            }

            // Dynamic 3rd-Person Follower Camera: Stays behind character at any 360° rotation
            if (this.cameraRig) {
                const followDist = 2.6; // distance behind character
                const targetCamX = this.charPos.x + followDist * Math.sin(camYaw);
                const targetCamZ = this.charPos.z + followDist * Math.cos(camYaw);
                const targetCamY = 1.95 - camPitch * 0.8;

                const curPos = this.cameraRig.getAttribute('position') || { x: 0, y: 1.95, z: 2.6 };
                const smoothX = curPos.x + (targetCamX - curPos.x) * 0.22;
                const smoothZ = curPos.z + (targetCamZ - curPos.z) * 0.22;
                const smoothY = curPos.y + (targetCamY - curPos.y) * 0.22;

                // Strictly clamp camera inside room so it never goes outside walls
                const clampedCamX = Math.max(-roomLimit, Math.min(roomLimit, smoothX));
                const clampedCamZ = Math.max(-roomLimit, Math.min(roomLimit, smoothZ));

                this.cameraRig.setAttribute('position', `${clampedCamX} ${smoothY} ${clampedCamZ}`);
            }

            // Check Station Proximity
            if (this.stationCooldown > 0) {
                this.stationCooldown -= dt;
            }

            const stations = isBacaanMode ? [
                { id: 'bilik-ayat-pendek', name: 'Dewan Ayat Pendek', x: 0, z: -22 },
                { id: 'bilik-ayat-panjang', name: 'Dewan Ayat Panjang', x: 21.5, z: -11 },
                { id: 'bilik-petikan-1', name: 'Galeri Petikan Tahap 1', x: 21.5, z: 11 },
                { id: 'bilik-petikan-2', name: 'Galeri Petikan Tahap 2', x: -21.5, z: -11 },
                { id: 'bilik-cerita-pendek', name: 'Pavilion Cerita Pendek', x: -21.5, z: 11 }
            ] : [
                { id: 'front-abc-upper', name: 'Galeri Huruf Fonik (a - z)', x: 0, z: -22 },
                { id: 'back-abc-lower', name: 'Galeri Huruf Kecil (a - z)', x: 0, z: 22 },
                { id: 'left-numbers', name: 'Galeri Asas Nombor (0 - 10)', x: -22, z: 0 },
                { id: 'right-series', name: 'Galeri Siri Nombor (10 - 100)', x: 22, z: 0 }
            ];

            const triggerRadius = 2.6;
            let inRangeStation = null;
            for (let s of stations) {
                const dist = Math.sqrt(Math.pow(this.charPos.x - s.x, 2) + Math.pow(this.charPos.z - s.z, 2));
                if (dist < triggerRadius) {
                    inRangeStation = s.id;
                    break;
                }
            }

            // Check 5 Story Book stations in Bacaan Mode
            let inRangeBook = null;
            if (isBacaanMode) {
                const bookStations = [
                    { id: 'buku_1_kucing_comel', x: -16, z: 27.2 },
                    { id: 'buku_2_hari_sukan_ani', x: -8, z: 27.2 },
                    { id: 'buku_3_pasar_bersama_ibu', x: 0, z: 27.2 },
                    { id: 'buku_4_pokok_mangga_amir', x: 8, z: 27.2 },
                    { id: 'buku_5_kelas_ceria_cikgu_nur', x: 16, z: 27.2 }
                ];
                for (let b of bookStations) {
                    const dist = Math.sqrt(Math.pow(this.charPos.x - b.x, 2) + Math.pow(this.charPos.z - b.z, 2));
                    if (dist < 2.0) {
                        inRangeBook = b.id;
                        break;
                    }
                }
            }

            if (inRangeBook) {
                if (this.lastStationTriggered !== inRangeBook && this.stationCooldown <= 0) {
                    this.lastStationTriggered = inRangeBook;
                    this.stationCooldown = 3.5;
                    this._playStationChime();
                    if (window.bukaVRPromptBuku) {
                        window.bukaVRPromptBuku(inRangeBook);
                    }
                }
            } else if (inRangeStation) {
                if (this.lastStationTriggered !== inRangeStation && this.stationCooldown <= 0) {
                    this.lastStationTriggered = inRangeStation;
                    this.stationCooldown = 3.5;
                    // Station arrival chime!
                    this._playStationChime();
                    if (window.triggerVRStationPopup) {
                        window.triggerVRStationPopup(inRangeStation);
                    }
                }
            } else {
                if (this.lastStationTriggered && !inRangeStation && !inRangeBook) {
                    this.lastStationTriggered = null;
                }
            }
        }
    });
}

// Self-contained Atlanta Rounded @font-face definition for VR SVG Textures
const ATLANTA_ROUNDED_SVG_STYLE = `<defs><style>
@font-face {
    font-family: 'AtlantaRounded';
    src: url('data:font/woff2;base64,') format('woff2');
    font-weight: 100 900;
    font-style: normal;
}
@font-face {
    font-family: 'AtlantaRoundedBlack';
    src: url('data:font/woff2;base64,') format('woff2');
    font-weight: 100 900;
    font-style: normal;
}
</style></defs>`;

// Generator for official Siri Nombor Flashcards (Soft Blue card with bold number)
function makeVrSiriNomborFlashcardSvg(digit) {
    const width = 280;
    const height = 280;
    const fontSize = String(digit).length > 2 ? 105 : 132;
    const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}" viewBox="0 0 ${width} ${height}">
        <defs>
            ${ATLANTA_ROUNDED_SVG_STYLE}
            <linearGradient id="cardGrad_${digit}" x1="0%" y1="0%" x2="0%" y2="100%">
                <stop offset="0%" stop-color="#e0f2fe"/>
                <stop offset="100%" stop-color="#bae6fd"/>
            </linearGradient>
        </defs>
        <!-- 3D Bevel Shadow -->
        <rect x="14" y="18" width="252" height="252" rx="42" fill="#0284c7" opacity="0.45"/>
        <!-- Main Flashcard Body matching Kad Imbasan Siri Nombor -->
        <rect x="10" y="10" width="260" height="260" rx="42" fill="url(#cardGrad_${digit})" stroke="#38bdf8" stroke-width="12"/>
        <!-- Subtle Top Gloss Highlight -->
        <path d="M 32 24 Q 140 14 248 24 Q 236 76 140 76 Q 44 76 32 24 Z" fill="#ffffff" opacity="0.45"/>
        <!-- Big Bold Number Digit matching Kad Imbasan -->
        <text x="50%" y="54%" font-family="AtlantaRounded, AtlantaRoundedBlack, sans-serif" font-weight="900" font-size="${fontSize}px" fill="#10182f" text-anchor="middle" dominant-baseline="central">${digit}</text>
    </svg>`;
    return 'data:image/svg+xml;utf8,' + encodeURIComponent(svg);
}

