window.currentVRStationId = null;
window.currentVRStationItems = [];
window.currentVRStationIndex = 0;
window.vrAutoPlayActive = false;
window.currentVRStationAudio = null;

// Dedicated Ultra-Reliable Voice Engine for 3D Stations
window.playVRStationVoice = function (teks, onEnd) {
    if (!teks) {
        if (typeof onEnd === 'function') onEnd();
        return;
    }

    // Stop existing audio playback
    if (window.currentVRStationAudio) {
        try {
            window.currentVRStationAudio.pause();
            window.currentVRStationAudio.currentTime = 0;
        } catch (e) { }
        window.currentVRStationAudio = null;
    }
    if ('speechSynthesis' in window) {
        try {
            window.speechSynthesis.cancel();
            if (window.speechSynthesis.paused) window.speechSynthesis.resume();
        } catch (e) { }
    }

    let finished = false;
    const finishOnce = () => {
        if (finished) return;
        finished = true;
        if (typeof onEnd === 'function') onEnd();
    };

    // 1. Resolve Audio Path for MP3
    let audioPath = null;
    const rawKey = String(teks).toLowerCase().trim();

    const numAudioMap = {
        '0': '/audio/nombor/sifar.mp3', 'sifar': '/audio/nombor/sifar.mp3',
        '1': '/audio/nombor/satu.mp3', 'satu': '/audio/nombor/satu.mp3',
        '2': '/audio/nombor/dua.mp3', 'dua': '/audio/nombor/dua.mp3',
        '3': '/audio/nombor/tiga.mp3', 'tiga': '/audio/nombor/tiga.mp3',
        '4': '/audio/nombor/empat.mp3', 'empat': '/audio/nombor/empat.mp3',
        '5': '/audio/nombor/lima.mp3', 'lima': '/audio/nombor/lima.mp3',
        '6': '/audio/nombor/enam.mp3', 'enam': '/audio/nombor/enam.mp3',
        '7': '/audio/nombor/tujuh.mp3', 'tujuh': '/audio/nombor/tujuh.mp3',
        '8': '/audio/nombor/lapan.mp3', 'lapan': '/audio/nombor/lapan.mp3',
        '9': '/audio/nombor/sembilan.mp3', 'sembilan': '/audio/nombor/sembilan.mp3',
        '10': '/audio/nombor/sepuluh.mp3', 'sepuluh': '/audio/nombor/sepuluh.mp3',
        '20': '/audio/nombor/dua-puluh.mp3', 'dua puluh': '/audio/nombor/dua-puluh.mp3', 'dua-puluh': '/audio/nombor/dua-puluh.mp3',
        '30': '/audio/nombor/tiga-puluh.mp3', 'tiga puluh': '/audio/nombor/tiga-puluh.mp3', 'tiga-puluh': '/audio/nombor/tiga-puluh.mp3',
        '40': '/audio/nombor/empat-puluh.mp3', 'empat puluh': '/audio/nombor/empat-puluh.mp3', 'empat-puluh': '/audio/nombor/empat-puluh.mp3',
        '50': '/audio/nombor/lima-puluh.mp3', 'lima puluh': '/audio/nombor/lima-puluh.mp3', 'lima-puluh': '/audio/nombor/lima-puluh.mp3',
        '60': '/audio/nombor/enam-puluh.mp3', 'enam puluh': '/audio/nombor/enam-puluh.mp3', 'enam-puluh': '/audio/nombor/enam-puluh.mp3',
        '70': '/audio/nombor/tujuh-puluh.mp3', 'tujuh puluh': '/audio/nombor/tujuh-puluh.mp3', 'tujuh-puluh': '/audio/nombor/tujuh-puluh.mp3',
        '80': '/audio/nombor/lapan-puluh.mp3', 'lapan puluh': '/audio/nombor/lapan-puluh.mp3', 'lapan-puluh': '/audio/nombor/lapan-puluh.mp3',
        '90': '/audio/nombor/sembilan-puluh.mp3', 'sembilan puluh': '/audio/nombor/sembilan-puluh.mp3', 'sembilan-puluh': '/audio/nombor/sembilan-puluh.mp3',
        '100': '/audio/nombor/seratus.mp3', 'seratus': '/audio/nombor/seratus.mp3'
    };

    if (typeof teks === 'string' && (teks.startsWith('/') || teks.endsWith('.mp3') || teks.endsWith('.mp3'))) {
        audioPath = teks;
    } else if (numAudioMap[rawKey]) {
        audioPath = numAudioMap[rawKey];
    } else if (window.currentVRStationId === 'front-abc-upper' || (VR_STATION_DATA[window.currentVRStationId] && VR_STATION_DATA[window.currentVRStationId].isFonik)) {
        audioPath = `/audio/fonik/fonik ${rawKey}.mp3`;
    } else if (typeof window.getAudioPath === 'function') {
        audioPath = window.getAudioPath(teks);
    }

    if (audioPath) {
        try {
            const audio = new Audio(audioPath);
            audio.preload = 'auto';
            window.currentVRStationAudio = audio;
            audio.onended = finishOnce;
            audio.onerror = () => {
                fallbackVoiceSpeech(teks, finishOnce);
            };
            const p = audio.play();
            if (p !== undefined) {
                p.catch(err => {
                    console.warn('3D Audio play promise failed, using TTS fallback:', err);
                    fallbackVoiceSpeech(teks, finishOnce);
                });
            }
        } catch (e) {
            fallbackVoiceSpeech(teks, finishOnce);
        }
    } else {
        fallbackVoiceSpeech(teks, finishOnce);
    }
};

function fallbackVoiceSpeech(teks, onEnd) {
    if (!('speechSynthesis' in window)) {
        if (typeof onEnd === 'function') onEnd();
        return;
    }
    try {
        window.speechSynthesis.cancel();
        if (window.speechSynthesis.paused) window.speechSynthesis.resume();
    } catch (e) { }

    const cleanText = String(teks).replace(/[-_/]/g, ' ').trim();

    setTimeout(() => {
        const utterance = new SpeechSynthesisUtterance(cleanText);
        utterance.lang = 'ms-MY';
        utterance.rate = 0.88;
        utterance.pitch = 1.05;

        // Keep reference to avoid Chrome garbage collection
        window._activeVRUtterance = utterance;

        let called = false;
        let keepAliveTimer = null;
        let safetyTimer = null;

        const done = () => {
            if (called) return;
            called = true;
            if (keepAliveTimer) { clearInterval(keepAliveTimer); keepAliveTimer = null; }
            if (safetyTimer) { clearTimeout(safetyTimer); safetyTimer = null; }
            window._activeVRUtterance = null;
            if (typeof onEnd === 'function') onEnd();
        };

        utterance.onend = () => {
            done();
        };

        utterance.onerror = (e) => {
            if (e && (e.error === 'canceled' || e.error === 'interrupted')) {
                if (!window.vrAutoPlayActive) {
                    called = true;
                    return;
                }
            }
            done();
        };

        // Chrome keep-alive pulse for speech longer than a few seconds
        keepAliveTimer = setInterval(() => {
            if (!called && window.speechSynthesis.speaking) {
                window.speechSynthesis.pause();
                window.speechSynthesis.resume();
            } else {
                clearInterval(keepAliveTimer);
            }
        }, 6000);

        // Calculate safety timeout based on text length (approx 160ms per char + 6s buffer, min 12s, max 60s)
        const safetyDuration = Math.max(12000, Math.min(60000, Math.ceil(cleanText.length * 160) + 6000));
        safetyTimer = setTimeout(() => {
            if (!called) done();
        }, safetyDuration);

        try {
            window.speechSynthesis.speak(utterance);
        } catch (e) {
            done();
        }
    }, 40);
}

window.triggerVRStationPopup = function (stationId) {
    const popup = document.getElementById('vr-station-popup');
    const station = VR_STATION_DATA[stationId];
    if (!popup || !station) return;

    window.currentVRStationId = stationId;
    window.currentVRStationItems = station.items || [];
    window.currentVRStationIndex = 0;
    window.vrAutoPlayActive = false;

    const autoBtn = document.getElementById('vr-auto-btn');
    if (autoBtn) {
        autoBtn.innerHTML = '<i class="fa-solid fa-volume-high"></i> <span>Dengar Semua</span>';
        autoBtn.style.backgroundColor = '#168f81';
    }

    const headerEl = document.getElementById('vr-station-header');
    if (headerEl) {
        headerEl.style.backgroundColor = station.color;
        headerEl.innerHTML = `
            <h2 style="margin: 0; font-size: 1.3rem; font-weight: bold; color: white;">${station.title}</h2>
            <button 
                class="neo-btn bg-red"
                onclick="window.closeVRStationPopup()"
                style="position: absolute; top: 10px; right: 12px; width: 34px; height: 34px; padding: 0; display: flex; align-items: center; justify-content: center; font-size: 1rem; z-index: 10; color: white;"
                title="Tutup"
            >
                <i class="fa-solid fa-xmark"></i>
            </button>
        `;
    }

    renderVRStationShowcaseCard();
    popup.classList.add('active');
};

