function vrRoomPillars(cx, cz, hw, hd) {
    const x1 = cx - hw + 1.2, x2 = cx + hw - 1.2;
    const z1 = cz - hd + 1.2, z2 = cz + hd - 1.2;
    let p = '';
    [[x1, z1], [x2, z1], [x1, z2], [x2, z2]].forEach(([px, pz]) => {
        p += `<a-cylinder position="${px} 3.8 ${pz}" radius="0.35" height="7.6" color="#fef3c7" material="roughness: 0.3;"></a-cylinder>
        <a-box position="${px} 0.1 ${pz}" width="0.9" height="0.2" depth="0.9" color="#b8860b"></a-box>
        <a-box position="${px} 7.6 ${pz}" width="0.9" height="0.2" depth="0.9" color="#b8860b"></a-box>`;
    });
    return p;
}

function vrRoomBeams(cx, cz, w, d) {
    const hw = w / 2, hd = d / 2;
    return `<a-box position="${cx} 7.85 ${cz - hd}" width="${w}" height="0.25" depth="0.25" color="#d4a574"></a-box>
    <a-box position="${cx} 7.85 ${cz + hd}" width="${w}" height="0.25" depth="0.25" color="#d4a574"></a-box>
    <a-box position="${cx - hw} 7.85 ${cz}" width="0.25" height="0.25" depth="${d}" color="#d4a574"></a-box>
    <a-box position="${cx + hw} 7.85 ${cz}" width="0.25" height="0.25" depth="${d}" color="#d4a574"></a-box>`;
}

function makeVrNumberSignSvg(digit, word, color, bgColor) {
    const cleanWord = word ? String(word).toLowerCase().trim() : '';
    const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="320" height="320" viewBox="0 0 320 320">
        ${ATLANTA_ROUNDED_SVG_STYLE}
        <rect width="100%" height="100%" fill="${bgColor || '#ffffff'}" rx="24" stroke="#b8860b" stroke-width="6"/>
        <rect x="0" y="0" width="100%" height="72" fill="${color || '#0284c7'}" rx="20"/>
        <text x="50%" y="46" font-family="AtlantaRounded, AtlantaRoundedBlack, sans-serif" font-weight="bold" font-size="26px" fill="#ffffff" text-anchor="middle">${digit} ${cleanWord ? '• ' + cleanWord : ''}</text>
    </svg>`;
    return 'data:image/svg+xml;utf8,' + encodeURIComponent(svg);
}

function makeVrFonikCardSvg(letter) {
    const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="256" height="256">
        ${ATLANTA_ROUNDED_SVG_STYLE}
        <rect width="100%" height="100%" fill="#ecfdf5" rx="24" stroke="#059669" stroke-width="8"/>
        <circle cx="128" cy="128" r="75" fill="#d1fae5" stroke="#10b981" stroke-width="3" stroke-dasharray="4 3"/>
        <text x="50%" y="54%" font-family="AtlantaRounded, AtlantaRoundedBlack, sans-serif" font-weight="900" font-size="130px" fill="#065f46" text-anchor="middle" dominant-baseline="middle">${letter}</text>
    </svg>`;
    return 'data:image/svg+xml;utf8,' + encodeURIComponent(svg);
}

function makeVrBannerTitleSvg(title, color) {
    const toTitleCase = (str) => {
        if (!str) return '';
        return str.trim().split(/\s+/).map(w => {
            if (!w) return '';
            return w.charAt(0).toUpperCase() + w.slice(1).toLowerCase();
        }).join(' ');
    };
    const titleText = toTitleCase(title);
    const width = 640;
    const height = 120;
    const gradId = 'bannerGrad_' + (title || 'buku').replace(/[^a-zA-Z0-9]/g, '_');
    const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}" viewBox="0 0 ${width} ${height}">
        <defs>
            ${ATLANTA_ROUNDED_SVG_STYLE}
            <linearGradient id="${gradId}" x1="0%" y1="0%" x2="100%" y2="100%">
                <stop offset="0%" stop-color="#ffffff"/>
                <stop offset="100%" stop-color="#f8fafc"/>
            </linearGradient>
        </defs>
        <!-- Highlighted 3D Badge with Theme Accent & Gold Rim -->
        <rect x="6" y="6" width="${width - 12}" height="${height - 12}" rx="28" fill="url(#${gradId})" stroke="#1e293b" stroke-width="7"/>
        <rect x="15" y="15" width="${width - 30}" height="${height - 30}" rx="20" fill="${color || '#047857'}" stroke="#fbbf24" stroke-width="3"/>
        <text x="50%" y="54%" font-family="AtlantaRounded, AtlantaRoundedBlack, sans-serif" font-weight="900" font-size="28px" fill="#ffffff" text-anchor="middle" dominant-baseline="middle">${titleText}</text>
    </svg>`;
    return 'data:image/svg+xml;utf8,' + encodeURIComponent(svg);
}

function generateCreamWallTexture() {
    try {
        const canvas = document.createElement('canvas');
        canvas.width = 256;
        canvas.height = 256;
        const ctx = canvas.getContext('2d');
        if (!ctx) return '';

        // Exact Warm Royal Museum Cream Base (#fef3c7)
        ctx.fillStyle = '#fef3c7';
        ctx.fillRect(0, 0, 256, 256);

        // Very subtle micro-fine plaster grain (clean & uniform, no harsh dark patches)
        const imgData = ctx.getImageData(0, 0, 256, 256);
        const data = imgData.data;
        for (let i = 0; i < data.length; i += 4) {
            const noise = (Math.random() - 0.5) * 8; // gentle smooth grain
            data[i] = Math.min(255, Math.max(0, data[i] + noise));
            data[i + 1] = Math.min(255, Math.max(0, data[i + 1] + noise * 0.9));
            data[i + 2] = Math.min(255, Math.max(0, data[i + 2] + noise * 0.7));
        }
        ctx.putImageData(imgData, 0, 0);

        // Soft seamless warm light gleams (only delicate white highlights, NO dirty brown splotches)
        for (let j = 0; j < 16; j++) {
            const x = Math.random() * 256;
            const y = Math.random() * 256;
            const r = 30 + Math.random() * 50;
            const grad = ctx.createRadialGradient(x, y, 0, x, y, r);
            grad.addColorStop(0, 'rgba(255, 255, 255, 0.12)');
            grad.addColorStop(1, 'transparent');
            ctx.fillStyle = grad;
            ctx.beginPath();
            ctx.arc(x, y, r, 0, Math.PI * 2);
            ctx.fill();
        }

        // Extremely subtle vertical architectural texture striations
        ctx.strokeStyle = 'rgba(254, 243, 199, 0.4)';
        ctx.lineWidth = 1;
        for (let x = 0; x < 256; x += 16) {
            ctx.beginPath();
            ctx.moveTo(x, 0);
            ctx.lineTo(x, 256);
            ctx.stroke();
        }

        return canvas.toDataURL('image/jpeg', 0.92);
    } catch (e) {
        return 'data:image/svg+xml;utf8,' + encodeURIComponent(`<svg xmlns='http://www.w3.org/2000/svg' width='120' height='120'>
            <rect width='120' height='120' fill='#fef3c7'/>
        </svg>`);
    }
}





