    function vrRoomPillars(cx, cz, hw, hd) {
        const x1 = cx - hw + 1.2, x2 = cx + hw - 1.2;
        const z1 = cz - hd + 1.2, z2 = cz + hd - 1.2;
        let p = '';
        [[x1, z1], [x2, z1], [x1, z2], [x2, z2]].forEach(([px, pz]) => {
            p += `<a-cylinder position="${px} 3.8 ${pz}" radius="0.3" height="7.6" material="src: url(${creamWallTexture}); repeat: 2 4; roughness: 0.7;"></a-cylinder>
            <a-box position="${px} 0.1 ${pz}" width="0.8" height="0.2" depth="0.8" color="#b8860b"></a-box>
            <a-box position="${px} 7.6 ${pz}" width="0.8" height="0.2" depth="0.8" color="#b8860b"></a-box>`;
        });
        return p;
    }

    function vrRoomBeams(cx, cz, w, d) {
        const hw = w / 2, hd = d / 2;
        return `<a-box position="${cx} 7.85 ${cz - hd}" width="${w}" height="0.2" depth="0.2" color="#d4a574"></a-box>
        <a-box position="${cx} 7.85 ${cz + hd}" width="${w}" height="0.2" depth="0.2" color="#d4a574"></a-box>
        <a-box position="${cx - hw} 7.85 ${cz}" width="0.2" height="0.2" depth="${d}" color="#d4a574"></a-box>
        <a-box position="${cx + hw} 7.85 ${cz}" width="0.2" height="0.2" depth="${d}" color="#d4a574"></a-box>`;
    }

