window.bukaARABC = function () {
    if (typeof requestSensorPermissionAndStart === 'function') {
        requestSensorPermissionAndStart('ar-abc');
    } else {
        window.bukaARABCSebenar();
    }
};

window.bukaARABCSebenar = function () {
    window.currentARKemahiran = 'abc';
    paparSkrin('view-ar-sukukata');
    if (window.showARGuideModal) {
        window.showARGuideModal();
    }
    const desktopTitle = document.getElementById('ar_desktop_title_label');
    if (desktopTitle) desktopTitle.innerText = 'AR ABC';
    const desktopSkillLabel = document.getElementById('ar_sukukata_kemahiran_label');
    if (desktopSkillLabel) desktopSkillLabel.innerText = 'AR ABC (SEBUTAN HURUF)';
    const mobileSkillLabel = document.getElementById('ar_header_title_mobile_skill');
    if (mobileSkillLabel) mobileSkillLabel.innerText = 'AR ABC';

    const letters = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ'.split('');
    window.arSukuKataWords = letters.map(l => ({
        word: l.toLowerCase(),
        front: l
    }));

    window.arSukuKataWordsRemaining = [...window.arSukuKataWords];
    window.currentARWord = "";
    window.arSukuKataScore = 0;
    window.isARPlaying = false;

    const sc = document.getElementById("ar_speech_box_container");
    if (sc) { sc.style.opacity = 0; sc.style.visibility = "hidden"; }
    const scoreDisplay = document.getElementById('score_display_ar_sukukata');
    if (scoreDisplay) scoreDisplay.innerText = "0";
    const mobileStarsCount = document.getElementById('ar_header_stars_count');
    if (mobileStarsCount) mobileStarsCount.innerText = "0";
    const wordDisplay = document.getElementById('word_display_ar_sukukata');
    if (wordDisplay) wordDisplay.innerText = "?";

    const startBtn = document.getElementById('start_btn_ar_sukukata');
    if (startBtn) {
        startBtn.innerText = "MULA";
        startBtn.className = "neo-btn ar-start-btn";
    }
    const speechStatus = document.getElementById('speech_status_ar_sukukata');
    if (speechStatus) {
        speechStatus.innerText = 'Tekan "MULA"';
        speechStatus.className = 'ar-speech-text';
    }
    const starPopup = document.getElementById('ar_star_popup');
    if (starPopup) {
        starPopup.classList.remove('animate-star');
        starPopup.style.opacity = '0';
    }
    const cameraOverlay = document.getElementById('camera_status_ar_sukukata');
    if (cameraOverlay) {
        cameraOverlay.style.display = 'none';
        cameraOverlay.classList.add('hidden');
    }

    initARCamera();
    initSpeechRecognition();
};

function startARScene() {
    paparSkrin('view-ar-abc');

    if (typeof AFRAME !== 'undefined' && !AFRAME.components['play-on-hover']) {
        AFRAME.registerComponent('play-on-hover', {
            schema: { type: 'string' },
            init: function () {
                this.el.addEventListener('mouseenter', () => {
                    if (window.sebutAudio) window.sebutAudio(this.data);
                });
            }
        });
    }

    const container = document.getElementById('ar-container');

    const startCam = () => {
        navigator.mediaDevices.getUserMedia({ video: { facingMode: 'environment' } })
            .then(stream => {
                const video = document.getElementById('ar-camera-bg');
                if (video) {
                    video.srcObject = stream;
                    video.style.transform = 'none'; // reset mirror for environment camera
                }
            })
            .catch(err => {
                console.error("Environment camera error, falling back to front:", err);
                navigator.mediaDevices.getUserMedia({ video: true })
                    .then(stream => {
                        const video = document.getElementById('ar-camera-bg');
                        if (video) video.srcObject = stream;
                    }).catch(e => console.log('No camera found'));
            });
    };

    if (container.innerHTML.trim() !== '') {
        startCam();
        return; // Already initialized
    }

    let buttons = '';
    for (let i = 0; i < 26; i++) {
        const letter = String.fromCharCode(65 + i);
        const x = (i % 6) * 1 - 2.5;
        const y = -Math.floor(i / 6) * 1 + 3;
        const z = -4;
        buttons += `<a-box position="${x} ${y} ${z}" depth="0.1" height="0.8" width="0.8" color="#3b82f6"
            class="clickable"
            animation__mouseenter="property: scale; to: 1.2 1.2 1.2; startEvents: mouseenter; dur: 200"
            animation__mouseleave="property: scale; to: 1 1 1; startEvents: mouseleave; dur: 200"
            play-on-hover="${letter.toLowerCase()}">
            <a-text value="${letter}" align="center" color="#fff" position="0 0 0.06" scale="2 2 2"></a-text>
        </a-box>`;
    }

    container.innerHTML = `
        <video id="ar-camera-bg" autoplay playsinline style="position: absolute; top: 0; left: 0; width: 100vw; height: 100dvh; object-fit: cover; z-index: -1; transform: scaleX(-1);"></video>
        <a-scene embedded style="width: 100vw; height: 100dvh;" renderer="alpha: true" device-orientation-permission-ui="enabled: false">
            <a-entity position="0 0 0">
                ${buttons}
            </a-entity>
            
            <a-entity camera look-controls="touchEnabled: false; magicWindowTrackingEnabled: true;">
                <a-cursor raycaster="objects: .clickable" color="yellow"></a-cursor>
            </a-entity>
        </a-scene>
    `;

    navigator.mediaDevices.getUserMedia({ video: { facingMode: 'environment' } })
        .then(stream => {
            const video = document.getElementById('ar-camera-bg');
            if (video) {
                video.srcObject = stream;
                video.style.transform = 'none'; // reset mirror for environment camera
            }
        })
        .catch(err => {
            console.error("Environment camera error, falling back to front:", err);
            navigator.mediaDevices.getUserMedia({ video: true })
                .then(stream => {
                    const video = document.getElementById('ar-camera-bg');
                    if (video) video.srcObject = stream;
                }).catch(e => console.log('No camera found'));
        });
}

