window.bukaPerpustakaan = function (isHero) {
    if (typeof isHero === 'undefined') {
        isHero = (window.currentPeta === 3);
    }
    if (window.setPerpustakaanHeroMode) {
        window.setPerpustakaanHeroMode(isHero);
    }
    if (typeof requestSensorPermissionAndStart === 'function') {
        requestSensorPermissionAndStart('perpustakaan', isHero);
    } else {
        window.paparSkrin('view-perpustakaan');
    }
};



