window.pilihPeta = function (nomborPeta) {
    const currentMod = window.modSemasa || modSemasa || 'belajar';
    const isTrial = typeof checkIsTrial === 'function' ? checkIsTrial() : false;
    if (isTrial && nomborPeta > 1) {
        if (typeof window.playBubble === 'function') window.playBubble();
        if (typeof window.openPakejProModal === 'function') {
            const role = localStorage.getItem('bunyiKataUserRole') || 'guru';
            window.openPakejProModal(role === 'ibubapa' ? 'ibubapa' : 'guru');
        }
        return;
    }
    const pModal = document.getElementById('modal-pilih-peta');
    if (pModal) pModal.style.display = 'none';

    // Terus buka peta kembara untuk mod Belajar
    if (currentMod === 'belajar') {
        window.bukaPeta(nomborPeta);
        return;
    }

    const info = PETA_INFO[nomborPeta];
    if (!info) {
        window.bukaPeta(nomborPeta);
        return;
    }

    const ALL_BADGES = [
        { id: 1, title: "Penjelajah Alfabet", image: "/images/lencana/lencana-penjelajah-alfabet.png" },
        { id: 2, title: "Pemburu Suku Kata", image: "/images/lencana/lencana-pemburu-suku-kata.png" },
        { id: 3, title: "Wira Pulau", image: "/images/lencana/lencana-wira-pulau.png" },
        { id: 4, title: "Naib Raja Bacaan", image: "/images/lencana/lencana-naib-raja-bacaan.png" },
        { id: 5, title: "Kapten Harta Karun", image: "/images/lencana/lencana-kapten-harta-karun.png" }
    ];

    const targetIdx = Math.max(0, Math.min(nomborPeta - 1, 3));

    let modalInfo = document.getElementById('modal-info-peta');
    if (!modalInfo) {
        modalInfo = document.createElement('div');
        modalInfo.id = 'modal-info-peta';
        modalInfo.className = 'modal-overlay';
        modalInfo.style.cssText = 'display: flex; z-index: 3100; background: rgba(0,0,0,0.85); align-items: center; justify-content: center; padding: 15px;';
        document.body.appendChild(modalInfo);
    }

    modalInfo.innerHTML = `
    <div class="modal-content" style="max-width: 450px; width: 100%; background-color: #ffffff; background-image: radial-gradient(circle, rgba(16, 24, 47, .11) 1.5px, transparent 1.5px); background-size: 20px 20px; text-align: center; position: relative; overflow: hidden; padding: 25px 20px 20px 20px;">
        <button class="neo-btn bg-red close-btn" onclick="document.getElementById('modal-info-peta').style.display='none'; const pm = document.getElementById('modal-pilih-peta'); if(pm) pm.style.display='flex';" aria-label="Tutup"><i class="fa-solid fa-xmark"></i></button>
        
        <div class="century-gothic-font" style="font-size: 1.3rem; font-weight: 800; color: white; background-color: var(--color-purple); margin: 0 auto 15px auto; padding: 10px 20px; border-radius: 12px; display: inline-block;   0 var(--color-dark); border: 2.5px solid var(--color-dark);">
            ${info.title}
        </div>
        
        <div class="century-gothic-font" style="font-size: 0.95rem; color: #475569; margin-bottom: 20px; line-height: 1.4;">
            ${info.desc}
        </div>
        
        <div style="font-size: 0.95rem; font-weight: 800; color: var(--color-dark); margin-bottom: 10px; text-transform: uppercase; letter-spacing: 0.5px;">LENCANA GANJARAN:</div>
        
        <!-- 3D CAROUSEL ORBIT STAGE -->
        <div id="badge-3d-carousel-stage" style="perspective: 800px; width: 100%; height: 165px; display: flex; align-items: center; justify-content: center; position: relative; margin: 10px 0 20px 0; overflow: visible; user-select: none;">
            ${ALL_BADGES.map((b, i) => `
                <div id="badge-orbit-item-${i}" class="badge-orbit-card" style="position: absolute; left: 50%; top: 50%; width: 105px; height: 115px; margin-left: -52.5px; margin-top: -57.5px; transition: transform 0.05s linear, opacity 0.3s ease, filter 0.3s ease; pointer-events: none; z-index: 1;">
                    <div class="badge-card-item" style="position: relative; background: #ffffff; border: 3.5px solid var(--color-dark); border-radius: 20px; padding: 10px; box-shadow: 0 5px 0 var(--color-dark); display: flex; flex-direction: column; align-items: center; text-align: center; width: 100%;">
                        <div class="badge-top-tape" style="width: 34px; height: 9px; background: var(--color-purple); border: 2.5px solid var(--color-dark); border-radius: 4px; position: absolute; top: -6px; left: 50%; transform: translateX(-50%); z-index: 5;"></div>
                        <div class="badge-inner-frame" style="position: relative; width: 100%; aspect-ratio: 1 / 1; background: radial-gradient(circle, #ffffff 40%, #f1f5f9 100%); border: 3px solid #94a3b8; border-radius: 14px; overflow: hidden; display: flex; align-items: center; justify-content: center;">
                            <div class="shine-sweep-slow" style="position: absolute; top: 0; left: 0; width: 100%; height: 100%; background: linear-gradient(90deg, transparent, rgba(255,255,255,0.85), transparent); z-index: 5;"></div>
                            <img src="${b.image}" style="width: 86%; height: 86%; margin: auto; object-fit: contain; position: relative; z-index: 2;" />
                        </div>
                    </div>
                </div>
            `).join('')}
        </div>
        
        <button class="neo-btn" onclick="document.getElementById('modal-info-peta').style.display='none'; window.bukaPeta(${nomborPeta});" style="width: 100%; background-color: #168f81; color: white; font-size: 1.15rem; padding: 14px; display: flex; align-items: center; justify-content: center; gap: 8px; box-shadow: 0 4px 0 #0d5c53;">
            <i class="fa-solid fa-play"></i> Mula Cabaran
        </button>
    </div>
    `;

    modalInfo.style.display = 'flex';

    // 3D ORBIT CAROUSEL ROTATION ANIMATION (360 degrees smoothly decelerating to target)
    const radius = 135; // px 3D radius
    const totalItems = ALL_BADGES.length;
    const stepAngle = (2 * Math.PI) / totalItems; // 72 deg in radians

    // We want targetIdx to end up at angle = 0 (Front center)
    // Target position angle offset: offsetAngle = - (targetIdx * stepAngle)
    const targetOffset = - (targetIdx * stepAngle);
    // Start 360 deg (2*PI) before targetOffset for 1 smooth full 360 rotation
    const startOffset = targetOffset - (2 * Math.PI);

    let startTime = null;
    const duration = 1800; // 1.8 seconds smooth rotation

    function updateOrbitPositions(currentOffset) {
        ALL_BADGES.forEach((b, i) => {
            const el = document.getElementById(`badge-orbit-item-${i}`);
            if (!el) return;

            const angle = (i * stepAngle) + currentOffset;
            const x = Math.sin(angle) * radius;
            const z = Math.cos(angle) * radius;

            // Normalize z for scaling and opacity: z ranges from -radius (back) to +radius (front)
            const normZ = (z + radius) / (2 * radius); // 0 at back, 1 at front

            const scale = 0.65 + (normZ * 0.45); // 0.65 back to 1.1 front
            const opacity = 0.35 + (normZ * 0.65); // 0.35 back to 1.0 front
            const zIndex = Math.round(normZ * 100);

            // Is this the front center item?
            const isCenter = Math.abs(x) < 25 && z > 50;

            const cardBox = el.querySelector('.badge-card-item');
            const topTape = el.querySelector('.badge-top-tape');
            const innerFrame = el.querySelector('.badge-inner-frame');
            const badgeImg = el.querySelector('img');

            if (isCenter) {
                if (cardBox) {
                    cardBox.style.border = '3.5px solid var(--color-dark)';
                    cardBox.style.boxShadow = '0 6px 0 var(--color-dark)';
                }
                if (topTape) {
                    topTape.style.background = 'var(--color-purple)';
                    topTape.style.border = '2.5px solid var(--color-dark)';
                }
                if (innerFrame) {
                    innerFrame.style.border = '3px solid #94a3b8';
                }
                if (badgeImg) {
                    badgeImg.style.filter = 'none';
                }
            } else {
                if (cardBox) {
                    cardBox.style.border = '3px solid #cbd5e1';
                    cardBox.style.boxShadow = '0 4px 0 #cbd5e1';
                }
                if (topTape) {
                    topTape.style.background = '#cbd5e1';
                    topTape.style.border = '2px solid #cbd5e1';
                }
                if (innerFrame) {
                    innerFrame.style.border = '2px solid #cbd5e1';
                }
                if (badgeImg) {
                    badgeImg.style.filter = 'grayscale(100%) opacity(0.45)';
                }
            }

            el.style.transform = `translate3d(${x}px, 0, ${z}px) scale(${scale})`;
            el.style.opacity = opacity;
            el.style.zIndex = zIndex;
        });
    }

    // Cubic-bezier ease-out function for smooth deceleration
    function easeOutCubic(t) {
        return 1 - Math.pow(1 - t, 3);
    }

    function renderFrame(timestamp) {
        if (!startTime) startTime = timestamp;
        const elapsed = timestamp - startTime;
        const progress = Math.min(elapsed / duration, 1);

        const easedProgress = easeOutCubic(progress);
        const currentOffset = startOffset + (easedProgress * (2 * Math.PI));

        updateOrbitPositions(currentOffset);

        if (progress < 1) {
            requestAnimationFrame(renderFrame);
        } else {
            // STOPPING LANDING EFFECT ON MAIN TARGET BADGE
            updateOrbitPositions(targetOffset);
            const targetEl = document.getElementById(`badge-orbit-item-${targetIdx}`);
            if (targetEl) {
                targetEl.style.transition = 'transform 0.35s cubic-bezier(0.175, 0.885, 0.32, 1.275), filter 0.35s ease';
                targetEl.style.transform = `translate3d(0, 0, ${radius}px) scale(1.2)`;
                targetEl.style.filter = 'drop-shadow(0 0 25px rgba(234, 179, 8, 0.95)) drop-shadow(0 10px 15px rgba(0,0,0,0.35))';

                const innerBox = targetEl.querySelector('.badge-inner-frame');
                if (innerBox) {
                    innerBox.style.borderColor = '#eab308';
                    innerBox.style.boxShadow = '0 0 20px rgba(234, 179, 8, 0.8), inset 0 0 12px rgba(254, 240, 138, 0.9)';
                }

                setTimeout(() => {
                    targetEl.style.transform = `translate3d(0, 0, ${radius}px) scale(1.1)`;
                }, 400);
            }
        }
    }

    requestAnimationFrame(renderFrame);
};

function initAppLogicOnReady() {
    mengendaliNavigasiURL();

    // Pulihkan dan sync data murid aktif jika pengguna sedang dalam sesi murid/anak
    const curStudent = window.namaMuridAktif || localStorage.getItem('muridAktif') || localStorage.getItem('bunyiKataCurrentMurid') || localStorage.getItem('bunyiKataNamaMurid') || '';
    if (curStudent && curStudent !== 'Tetamu' && curStudent !== 'Murid') {
        const sTarget = (typeof window.studentData !== 'undefined') ? window.studentData : (typeof studentData !== 'undefined' ? studentData : null);
        if (sTarget && sTarget[curStudent]) {
            const sObj = sTarget[curStudent];
            if (sObj.stars && typeof sObj.stars === 'object') {
                Object.keys(sObj.stars).forEach(modKey => {
                    const st = Number(sObj.stars[modKey] || 0);
                    if (st > 0) localStorage.setItem('stars_' + modKey, String(st));
                });
            }
            if (sObj.scores && typeof sObj.scores === 'object') {
                Object.keys(sObj.scores).forEach(modKey => {
                    const sc = Number(sObj.scores[modKey] || 0);
                    if (sc > 0) localStorage.setItem('score_' + modKey, String(sc));
                });
            }
        }

        if (typeof window.fetchStudentProgressFromFirebase === 'function') {
            const explicitId = localStorage.getItem('bunyiKataStudentId') || '';
            window.fetchStudentProgressFromFirebase(curStudent, explicitId).then(remote => {
                if (remote) {
                    const target = (typeof window.studentData !== 'undefined') ? window.studentData : (typeof studentData !== 'undefined' ? studentData : null);
                    if (target) {
                        if (!target[curStudent]) {
                            target[curStudent] = typeof studentRecord === 'function' ? studentRecord() : { coins: 0, badges: [], mapsUnlocked: 1, avatar: window.selectedAvatarIcon || '/images/avatar/avatar1.png' };
                        }
                        if (remote.id) {
                            target[curStudent].id = remote.id;
                            localStorage.setItem('bunyiKataStudentId', remote.id);
                        }
                        if (remote.badges && Array.isArray(remote.badges) && remote.badges.length > 0) {
                            target[curStudent].badges = Array.from(new Set([...(target[curStudent].badges || []), ...remote.badges]));
                        }
                        if (remote.scores && typeof remote.scores === 'object') {
                            target[curStudent].scores = { ...(target[curStudent].scores || {}), ...remote.scores };
                        }
                        if (remote.stars && typeof remote.stars === 'object') {
                            target[curStudent].stars = { ...(target[curStudent].stars || {}), ...remote.stars };
                            Object.keys(remote.stars).forEach(modKey => {
                                const st = Number(remote.stars[modKey] || 0);
                                if (st > 0) localStorage.setItem('stars_' + modKey, String(st));
                            });
                        }
                        if (remote.latihan && typeof remote.latihan === 'object') {
                            target[curStudent].latihan = { ...(target[curStudent].latihan || {}), ...remote.latihan };
                        }
                        if (remote.totalBintang !== undefined && remote.totalBintang > 0) {
                            target[curStudent].totalBintang = remote.totalBintang;
                            target[curStudent].coins = remote.totalBintang;
                        }
                        if (typeof kiraLencanaMurid === 'function') {
                            const earned = kiraLencanaMurid(target[curStudent]);
                            if (Array.isArray(earned) && earned.length > 0) {
                                target[curStudent].badges = Array.from(new Set([...(target[curStudent].badges || []), ...earned]));
                            }
                        }
                        try {
                            localStorage.setItem('bunyiKataStudentData', JSON.stringify(target));
                        } catch (e) { }

                        if (typeof updateProfilUI === 'function') {
                            try { updateProfilUI(); } catch (e) { }
                        }
                        window.dispatchEvent(new CustomEvent('kemaskini-profil'));
                    }
                }
            }).catch(e => console.warn('Startup student sync notice:', e));
        }
    }

    setTimeout(() => {
        let nKelas = localStorage.getItem('bunyiKataNamaKelas') || '-';
        let nGuru = localStorage.getItem('pdf_guru') || '';
        let elKelas = document.getElementById('guru-dashboard-nama-kelas-title');
        if (elKelas) elKelas.innerText = nKelas;
        let ibEl = document.getElementById('ibubapa-nama-kelas-title');
        if (ibEl) ibEl.innerText = nKelas;
        let elGuru = document.getElementById('guru-dashboard-nama-guru-title');
        if (elGuru) elGuru.innerText = nGuru || '-';
    }, 500);
}

if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initAppLogicOnReady);
} else {
    initAppLogicOnReady();
}

window.padamProfilAnakIbuBapa = function (namaAnak) {
    const childName = namaAnak || window.anakTerpilih;
    if (!childName || childName === 'Murid') return;

    window.showAppModalConfirm(
        `Adakah anda pasti untuk memadam profil anak "${childName}"?`,
        function () {
            parentChildNames = parentChildNames.filter(n => n !== childName);
            window.parentChildNames = parentChildNames;
            localStorage.setItem('bunyiKataParentChildNames', JSON.stringify(parentChildNames));
            if (studentData[childName]) delete studentData[childName];
            if (window.studentData && window.studentData[childName]) delete window.studentData[childName];
            saveStudentData();

            if (typeof window.deleteParentChildFromFirebase === 'function') {
                window.deleteParentChildFromFirebase({
                    namaAnak: childName,
                    parentIdOrEmail: localStorage.getItem('bunyiKataUserId') || ''
                }).catch(function (e) { console.warn('Ralat padam anak di Firebase:', e); });
            }

            if (window.anakTerpilih === childName) {
                window.anakTerpilih = parentChildNames.length > 0 ? parentChildNames[0] : '';
                localStorage.setItem('ibubapaAnakTerpilih', window.anakTerpilih);
                if (window.renderParentDashboard) window.renderParentDashboard();
            }

            const modal = document.getElementById('modal-pilih-anak');
            if (modal && modal.style.display !== 'none' && window.bukaModalPilihAnak) {
                window.bukaModalPilihAnak(window.__isTukarDashboardTemp);
            }
        }
    );
};


// ==========================================
// AR SUKU KATA LOGIC
// ==========================================
window.arSukuKataWords = [];
window.arSukuKataWordsRemaining = [];
window.currentARWord = "";
window.arSukuKataScore = 0;
window.isARPlaying = false;
window.arCamera = null;
window.arFaceMesh = null;
window.arRecognition = null;

window.bukaARSukuKataKemahiran = function (kemahiran) {
    if (typeof requestSensorPermissionAndStart === 'function') {
        requestSensorPermissionAndStart('ar-sukukata', kemahiran);
    } else {
        window.bukaARSukuKataKemahiranSebenar(kemahiran);
    }
};

window.bukaARSukuKataKemahiranSebenar = function (kemahiran) {
    window.currentARKemahiran = kemahiran;
    paparSkrin('view-ar-sukukata');
    if (window.showARGuideModal) {
        window.showARGuideModal();
    }
    const desktopTitle = document.getElementById('ar_desktop_title_label');
    if (desktopTitle) desktopTitle.innerText = 'AR Suku Kata';
    const formattedSkill = (kemahiran || 'kv').toUpperCase().replace(/_/g, ' + ');
    const desktopSkillLabel = document.getElementById('ar_sukukata_kemahiran_label');
    if (desktopSkillLabel) desktopSkillLabel.innerText = 'Suku Kata ' + formattedSkill;
    const mobileSkillLabel = document.getElementById('ar_header_title_mobile_skill');
    if (mobileSkillLabel) mobileSkillLabel.innerText = 'AR Suku Kata';

    // Map kemahiran to flashcard keys
    const flashcardKeyMap = {
        'kv': 'suku_kata_kv',
        'kvkv': 'suku_kata_kv_kv',
        'v_kv': 'suku_kata_v_kv',
        'kvkvkv': 'suku_kata_kv_kv_kv',
        'kvk': 'suku_kata_kvk',
        'v_kvk': 'suku_kata_v_kvk',
        'kv_kvk': 'suku_kata_kv_kvk',
        'kvk_kv': 'suku_kata_kvk_kv',
        'kvk_kvk': 'suku_kata_kvk_kvk',
        'kvkk': 'suku_kata_kvkk',
        'kv_kv_kvk': 'suku_kata_kv_kv_kvk',
        'kvk_kv_kvk': 'suku_kata_kvk_kv_kvk'
    };

    const fcKey = flashcardKeyMap[kemahiran] || 'suku_kata_kv';
    const fcData = window.moduleContentData && window.moduleContentData[fcKey] ? window.moduleContentData[fcKey].flashcards : [];

    if (fcData && fcData.length > 0) {
        window.arSukuKataWords = fcData.map(item => {
            const rawFront = item.front || item.back || '';
            const rawBack = item.back || item.front || '';
            const wordStr = rawBack.toString().replace(/[\s-]+/g, '').toLowerCase().trim();
            return {
                word: wordStr,
                front: rawFront
            };
        }).filter(item => item.word.length > 0);
    } else {
        window.arSukuKataWords = [
            { word: "baju", front: "ba - ju" },
            { word: "buku", front: "bu - ku" },
            { word: "bola", front: "bo - la" }
        ];
    }

    window.arSukuKataWordsRemaining = [...window.arSukuKataWords];
    window.currentARWord = "";
    window.arSukuKataScore = 0;
    window.isARPlaying = false;
    const sc = document.getElementById("ar_speech_box_container");
    if (sc) { sc.style.opacity = 0; sc.style.visibility = "hidden"; }
    document.getElementById('score_display_ar_sukukata').innerText = "0";
    const mobileStarsCount = document.getElementById('ar_header_stars_count');
    if (mobileStarsCount) mobileStarsCount.innerText = "0";
    document.getElementById('word_display_ar_sukukata').innerText = "?";

    const startBtn = document.getElementById('start_btn_ar_sukukata');
    startBtn.innerText = "MULA";
    startBtn.className = "neo-btn ar-start-btn";
    document.getElementById('speech_status_ar_sukukata').innerText = 'Tekan "MULA"';
    document.getElementById('speech_status_ar_sukukata').className = 'ar-speech-text';
    const starPopup = document.getElementById('ar_star_popup');
    if (starPopup) {
        starPopup.classList.remove('animate-star');
        starPopup.style.opacity = '0';
    }
    const cameraOverlay = document.getElementById('camera_status_ar_sukukata');
    if (cameraOverlay) {
        cameraOverlay.style.display = 'none';
        cameraOverlay.classList.add('hidden');
    }

    initARCamera();
    initSpeechRecognition();
};

window.tutupARSukuKata = function () {
    if (window.isARPlaying) {
        document.getElementById('start_btn_ar_sukukata').click();
    }
    if (window.arCamera) {
        window.arCamera.stop();
        window.arCamera = null;
    }
    if (window.arFaceMesh) {
        window.arFaceMesh.close();
        window.arFaceMesh = null;
    }
    paparSkrin('map-screen');
};

function hideARCameraOverlay() {
    const overlay = document.getElementById('camera_status_ar_sukukata');
    if (overlay) {
        overlay.classList.add('opacity-0', 'hidden');
        overlay.style.setProperty('display', 'none', 'important');
        overlay.style.setProperty('opacity', '0', 'important');
        overlay.style.setProperty('visibility', 'hidden', 'important');
        overlay.style.setProperty('pointer-events', 'none', 'important');
    }
}

function initARCamera() {
    const videoElement = document.getElementById('input_video_ar_sukukata');
    const canvasElement = document.getElementById('output_canvas_ar_sukukata');
    if (!canvasElement) return;
    const canvasCtx = canvasElement.getContext('2d');

    const overlay = document.getElementById('camera_status_ar_sukukata');

    if (window.arCamera) {
        hideARCameraOverlay();
        return;
    }

    if (navigator.mediaDevices && navigator.mediaDevices.getUserMedia) {
        navigator.mediaDevices.getUserMedia({ video: { facingMode: 'user', width: { ideal: 640 }, height: { ideal: 480 } } }).catch(() => {
            return navigator.mediaDevices.getUserMedia({ video: true });
        }).then(stream => {
            hideARCameraOverlay();

            const faceMesh = new FaceMesh({
                locateFile: (file) => {
                    return `https://cdn.jsdelivr.net/npm/@mediapipe/face_mesh/${file}`;
                }
            });

            faceMesh.setOptions({
                maxNumFaces: 1,
                refineLandmarks: true,
                minDetectionConfidence: 0.6,
                minTrackingConfidence: 0.6
            });

            faceMesh.onResults((results) => {
                hideARCameraOverlay();

                if (canvasElement.width !== (videoElement.videoWidth || 640)) {
                    canvasElement.width = videoElement.videoWidth || 640;
                    canvasElement.height = videoElement.videoHeight || 480;
                }

                canvasCtx.save();
                canvasCtx.clearRect(0, 0, canvasElement.width, canvasElement.height);
                canvasCtx.drawImage(results.image, 0, 0, canvasElement.width, canvasElement.height);

                if (results.multiFaceLandmarks && results.multiFaceLandmarks.length > 0) {
                    for (const landmarks of results.multiFaceLandmarks) {
                        const getPt = (idx) => ({
                            x: landmarks[idx].x * canvasElement.width,
                            y: landmarks[idx].y * canvasElement.height
                        });

                        const nose = getPt(1);
                        const leftFH = getPt(54);
                        const rightFH = getPt(284);
                        const leftCheek = getPt(205);
                        const rightCheek = getPt(425);

                        const filterMode = window.currentARFilter || 'bear';

                        if (filterMode === 'bear') {
                            // 🐻 BEAR FILTER
                            // Telinga Luar
                            canvasCtx.fillStyle = '#f472b6';
                            canvasCtx.beginPath();
                            canvasCtx.arc(leftFH.x - 10, leftFH.y - 30, 35, 0, 2 * Math.PI);
                            canvasCtx.fill();
                            canvasCtx.beginPath();
                            canvasCtx.arc(rightFH.x + 10, rightFH.y - 30, 35, 0, 2 * Math.PI);
                            canvasCtx.fill();

                            // Telinga Dalam
                            canvasCtx.fillStyle = '#fdf2f8';
                            canvasCtx.beginPath();
                            canvasCtx.arc(leftFH.x - 10, leftFH.y - 30, 18, 0, 2 * Math.PI);
                            canvasCtx.fill();
                            canvasCtx.beginPath();
                            canvasCtx.arc(rightFH.x + 10, rightFH.y - 30, 18, 0, 2 * Math.PI);
                            canvasCtx.fill();

                            // Hidung
                            canvasCtx.fillStyle = '#1f2937';
                            canvasCtx.beginPath();
                            canvasCtx.ellipse(nose.x, nose.y, 15, 10, 0, 0, 2 * Math.PI);
                            canvasCtx.fill();

                            canvasCtx.fillStyle = '#ffffff';
                            canvasCtx.beginPath();
                            canvasCtx.ellipse(nose.x - 4, nose.y - 3, 4, 2, 0, 0, 2 * Math.PI);
                            canvasCtx.fill();

                            // Blush Pipi
                            canvasCtx.fillStyle = 'rgba(251, 113, 133, 0.5)';
                            canvasCtx.beginPath();
                            canvasCtx.ellipse(leftCheek.x - 10, leftCheek.y, 25, 15, 0, 0, 2 * Math.PI);
                            canvasCtx.fill();
                            canvasCtx.beginPath();
                            canvasCtx.ellipse(rightCheek.x + 10, rightCheek.y, 25, 15, 0, 0, 2 * Math.PI);
                            canvasCtx.fill();

                        } else if (filterMode === 'cat') {
                            // 🐱 CAT FILTER
                            // Left Ear
                            canvasCtx.fillStyle = '#fb923c';
                            canvasCtx.beginPath();
                            canvasCtx.moveTo(leftFH.x - 35, leftFH.y);
                            canvasCtx.lineTo(leftFH.x - 20, leftFH.y - 75);
                            canvasCtx.lineTo(leftFH.x + 10, leftFH.y - 15);
                            canvasCtx.closePath();
                            canvasCtx.fill();

                            // Left Inner Ear
                            canvasCtx.fillStyle = '#fef08a';
                            canvasCtx.beginPath();
                            canvasCtx.moveTo(leftFH.x - 27, leftFH.y - 5);
                            canvasCtx.lineTo(leftFH.x - 20, leftFH.y - 55);
                            canvasCtx.lineTo(leftFH.x + 2, leftFH.y - 15);
                            canvasCtx.closePath();
                            canvasCtx.fill();

                            // Right Ear
                            canvasCtx.fillStyle = '#fb923c';
                            canvasCtx.beginPath();
                            canvasCtx.moveTo(rightFH.x - 10, rightFH.y - 15);
                            canvasCtx.lineTo(rightFH.x + 20, rightFH.y - 75);
                            canvasCtx.lineTo(rightFH.x + 35, rightFH.y);
                            canvasCtx.closePath();
                            canvasCtx.fill();

                            // Right Inner Ear
                            canvasCtx.fillStyle = '#fef08a';
                            canvasCtx.beginPath();
                            canvasCtx.moveTo(rightFH.x - 2, rightFH.y - 15);
                            canvasCtx.lineTo(rightFH.x + 20, rightFH.y - 55);
                            canvasCtx.lineTo(rightFH.x + 27, rightFH.y - 5);
                            canvasCtx.closePath();
                            canvasCtx.fill();

                            // Cat Nose
                            canvasCtx.fillStyle = '#f43f5e';
                            canvasCtx.beginPath();
                            canvasCtx.moveTo(nose.x - 12, nose.y - 6);
                            canvasCtx.lineTo(nose.x + 12, nose.y - 6);
                            canvasCtx.lineTo(nose.x, nose.y + 10);
                            canvasCtx.closePath();
                            canvasCtx.fill();

                            // Cat Whiskers
                            canvasCtx.strokeStyle = '#1e293b';
                            canvasCtx.lineWidth = 3;
                            canvasCtx.lineCap = 'round';

                            canvasCtx.beginPath();
                            canvasCtx.moveTo(leftCheek.x, leftCheek.y - 8);
                            canvasCtx.lineTo(leftCheek.x - 45, leftCheek.y - 18);
                            canvasCtx.moveTo(leftCheek.x, leftCheek.y);
                            canvasCtx.lineTo(leftCheek.x - 50, leftCheek.y);
                            canvasCtx.moveTo(leftCheek.x, leftCheek.y + 8);
                            canvasCtx.lineTo(leftCheek.x - 45, leftCheek.y + 18);
                            canvasCtx.stroke();

                            canvasCtx.beginPath();
                            canvasCtx.moveTo(rightCheek.x, rightCheek.y - 8);
                            canvasCtx.lineTo(rightCheek.x + 45, rightCheek.y - 18);
                            canvasCtx.moveTo(rightCheek.x, rightCheek.y);
                            canvasCtx.lineTo(rightCheek.x + 50, rightCheek.y);
                            canvasCtx.moveTo(rightCheek.x, rightCheek.y + 8);
                            canvasCtx.lineTo(rightCheek.x + 45, rightCheek.y + 18);
                            canvasCtx.stroke();

                            // Blush
                            canvasCtx.fillStyle = 'rgba(251, 113, 133, 0.4)';
                            canvasCtx.beginPath();
                            canvasCtx.ellipse(leftCheek.x, leftCheek.y, 20, 12, 0, 0, 2 * Math.PI);
                            canvasCtx.fill();
                            canvasCtx.beginPath();
                            canvasCtx.ellipse(rightCheek.x, rightCheek.y, 20, 12, 0, 0, 2 * Math.PI);
                            canvasCtx.fill();

                        } else if (filterMode === 'dog') {
                            // 🐶 DOG FILTER
                            // Floppy Dog Ears
                            canvasCtx.fillStyle = '#b45309';
                            canvasCtx.beginPath();
                            canvasCtx.ellipse(leftFH.x - 30, leftFH.y + 20, 22, 50, -0.2, 0, 2 * Math.PI);
                            canvasCtx.fill();

                            canvasCtx.fillStyle = '#fde68a';
                            canvasCtx.beginPath();
                            canvasCtx.ellipse(leftFH.x - 30, leftFH.y + 20, 12, 35, -0.2, 0, 2 * Math.PI);
                            canvasCtx.fill();

                            canvasCtx.fillStyle = '#b45309';
                            canvasCtx.beginPath();
                            canvasCtx.ellipse(rightFH.x + 30, rightFH.y + 20, 22, 50, 0.2, 0, 2 * Math.PI);
                            canvasCtx.fill();

                            canvasCtx.fillStyle = '#fde68a';
                            canvasCtx.beginPath();
                            canvasCtx.ellipse(rightFH.x + 30, rightFH.y + 20, 12, 35, 0.2, 0, 2 * Math.PI);
                            canvasCtx.fill();

                            // Dog Snout & Nose
                            canvasCtx.fillStyle = '#78350f';
                            canvasCtx.beginPath();
                            canvasCtx.ellipse(nose.x, nose.y + 2, 18, 14, 0, 0, 2 * Math.PI);
                            canvasCtx.fill();

                            canvasCtx.fillStyle = '#1e293b';
                            canvasCtx.beginPath();
                            canvasCtx.ellipse(nose.x, nose.y - 2, 12, 9, 0, 0, 2 * Math.PI);
                            canvasCtx.fill();

                            canvasCtx.fillStyle = '#ffffff';
                            canvasCtx.beginPath();
                            canvasCtx.ellipse(nose.x - 3, nose.y - 4, 3, 2, 0, 0, 2 * Math.PI);
                            canvasCtx.fill();

                            // Dog Tongue
                            const lipBottom = getPt(14);
                            canvasCtx.fillStyle = '#f43f5e';
                            canvasCtx.beginPath();
                            canvasCtx.ellipse(lipBottom.x, lipBottom.y + 12, 10, 16, 0, 0, 2 * Math.PI);
                            canvasCtx.fill();

                            canvasCtx.strokeStyle = '#be123c';
                            canvasCtx.lineWidth = 2;
                            canvasCtx.beginPath();
                            canvasCtx.moveTo(lipBottom.x, lipBottom.y + 2);
                            canvasCtx.lineTo(lipBottom.x, lipBottom.y + 18);
                            canvasCtx.stroke();
                        }
                    }
                }
                canvasCtx.restore();
            });

            window.arFaceMesh = faceMesh;

            let isARActive = true;
            window.arCamera = {
                stop: () => {
                    isARActive = false;
                    stream.getTracks().forEach(t => t.stop());
                },
                start: async () => { } // Dummy start
            };

            const videoStream = new MediaStream(stream.getVideoTracks());
            videoElement.srcObject = videoStream;
            videoElement.play().then(() => hideARCameraOverlay()).catch(() => hideARCameraOverlay());
            hideARCameraOverlay();

            let hasLoadedModel = false;
            async function processVideo() {
                if (!isARActive) return;
                if (videoElement.readyState >= 2) {
                    try {
                        // console.log("[AR Suku Kata] Menghantar frame ke FaceMesh...");
                        await faceMesh.send({ image: videoElement });
                        if (!hasLoadedModel) {
                            hasLoadedModel = true;
                            console.log("[AR Suku Kata] Frame berjaya diproses oleh FaceMesh!");
                            hideARCameraOverlay();
                        }
                    } catch (e) {
                        if (!hasLoadedModel) {
                            console.error("[AR Suku Kata] FaceMesh ralat semasa memproses frame:", e);
                            if (overlay) {
                                overlay.innerHTML = '<i class="fa-solid fa-circle-exclamation fa-3x mb-3 text-red-500"></i><p class="text-xl font-bold text-white text-center">Ralat pemprosesan AR.</p><p class="text-sm text-center text-white">Sila muat semula halaman.</p>';
                                setTimeout(() => hideARCameraOverlay(), 3000);
                            }
                            hasLoadedModel = true; // Stop spamming error
                        }
                    }
                }
                requestAnimationFrame(processVideo);
            }

            console.log("[AR Suku Kata] Mula memuatkan FaceMesh (initialize)...");
            faceMesh.initialize().then(() => {
                console.log("[AR Suku Kata] FaceMesh berjaya dimuatkan!");
                processVideo();
            }).catch(e => {
                console.error("[AR Suku Kata] Gagal memuatkan FaceMesh:", e);
                if (overlay) {
                    overlay.innerHTML = '<i class="fa-solid fa-circle-exclamation fa-3x mb-3 text-red-500"></i><p class="text-xl font-bold text-white text-center">Gagal memuatkan model AR.</p><p class="text-sm text-center text-white">Sila pastikan sambungan internet stabil.</p>';
                }
                setTimeout(() => {
                    hideARCameraOverlay();
                }, 3000);
            });

        }).catch(err => {
            console.error("Camera access denied: ", err);
            if (overlay) {
                overlay.innerHTML = '<i class="fa-solid fa-triangle-exclamation fa-3x mb-3 text-red-500"></i><p class="text-xl font-bold text-red-500 text-center">Kamera diperlukan.</p><p class="text-sm text-center">Sila benarkan akses kamera untuk AR.</p>';
            }
        });
    }
}


function getARPromptText() {
    return window.currentARKemahiran === 'abc' ? "Sila sebut huruf..." : "Sila sebut perkataan...";
}

// Pop Confetti Sound effect matching Tanduk Kata
window.playPopConfettiSound = function () {
    try {
        const AudioContextClass = window.AudioContext || window.webkitAudioContext;
        if (!AudioContextClass) return;
        if (!window.globalAudioCtx) {
            window.globalAudioCtx = new AudioContextClass();
        }
        const ctx = window.globalAudioCtx;
        if (ctx.state === 'suspended') {
            ctx.resume().catch(() => { });
        }
        const now = ctx.currentTime;

        // Cork / balloon pop sound
        const popOsc = ctx.createOscillator();
        const popGain = ctx.createGain();
        popOsc.type = 'sine';
        popOsc.frequency.setValueAtTime(650, now);
        popOsc.frequency.exponentialRampToValueAtTime(110, now + 0.09);

        popGain.gain.setValueAtTime(0.45, now);
        popGain.gain.exponentialRampToValueAtTime(0.01, now + 0.09);

        popOsc.connect(popGain);
        popGain.connect(ctx.destination);

        popOsc.start(now);
        popOsc.stop(now + 0.09);

        // Chimes
        [523.25, 659.25, 783.99].forEach((freq, idx) => {
            const chimeOsc = ctx.createOscillator();
            const chimeGain = ctx.createGain();
            chimeOsc.type = 'triangle';
            chimeOsc.frequency.setValueAtTime(freq, now + 0.04 + idx * 0.06);
            chimeGain.gain.setValueAtTime(0.3, now + 0.04 + idx * 0.06);
            chimeGain.gain.exponentialRampToValueAtTime(0.001, now + 0.4 + idx * 0.06);
            chimeOsc.connect(chimeGain);
            chimeGain.connect(ctx.destination);
            chimeOsc.start(now + 0.04 + idx * 0.06);
            chimeOsc.stop(now + 0.45 + idx * 0.06);
        });
    } catch (e) { }
};

function initSpeechRecognition() {
    const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
    if (SpeechRecognition) {
        if (window.arRecognition) {
            try { window.arRecognition.abort(); } catch (e) { }
            window.arRecognition = null;
        }
        const recognition = new SpeechRecognition();
        recognition.lang = 'ms-MY';
        recognition.continuous = true;
        recognition.interimResults = true;
        recognition.maxAlternatives = 10;

        recognition.onstart = () => {
            const micIcon = document.getElementById('mic_icon_ar_sukukata');
            if (micIcon) {
                micIcon.classList.remove('hidden');
                micIcon.style.display = 'inline-block';
            }
            const statusEl = document.getElementById('speech_status_ar_sukukata');
            if (statusEl && window.isARPlaying) {
                statusEl.innerText = getARPromptText();
                statusEl.className = "ar-speech-text";
                statusEl.style.color = "var(--color-dark, #10182f)";
            }
        };

        recognition.onaudiostart = () => {
            const micIcon = document.getElementById('mic_icon_ar_sukukata');
            if (micIcon) {
                micIcon.classList.remove('hidden');
                micIcon.style.display = 'inline-block';
            }
        };

        let lastMatchedTime = 0;

        recognition.onresult = (event) => {
            if (!window.isARPlaying || !window.currentARWord || (typeof window.currentARWord === 'string' && window.currentARWord.trim() === '')) return;

            const now = Date.now();
            if (now - lastMatchedTime < 1600) return; // Prevent double-trigger during success animation

            const candidates = [];
            let isFinalResult = false;
            let latestTranscript = '';

            if (event.results) {
                const startIndex = (event.resultIndex !== undefined && event.resultIndex >= 0) ? event.resultIndex : 0;
                for (let r = startIndex; r < event.results.length; r++) {
                    const res = event.results[r];
                    if (!res) continue;
                    if (res.isFinal) isFinalResult = true;
                    for (let i = 0; i < res.length; i++) {
                        if (res[i] && res[i].transcript) {
                            const t = res[i].transcript.trim();
                            candidates.push(t);
                            latestTranscript = t;
                        }
                    }
                }
                // Also check the latest result item
                const lastItem = event.results[event.results.length - 1];
                if (lastItem && lastItem[0] && lastItem[0].transcript) {
                    latestTranscript = lastItem[0].transcript.trim();
                }
            }

            if (candidates.length === 0) return;

            console.log("[AR Speech Heard]", candidates, "Target:", window.currentARWord);

            const statusEl = document.getElementById('speech_status_ar_sukukata');
            const speechBox = document.querySelector('.ar-speech-box');

            const isMatch = window.checkMalayWordMatch(candidates, window.currentARWord);
            if (isMatch) {
                lastMatchedTime = Date.now();
                if (statusEl) {
                    statusEl.innerHTML = `<span style="color: #16a34a; font-weight: 800;">🎉 Hebat! Tepat!</span>`;
                }
                arCorrectAnswer();
            } else {
                if (statusEl && latestTranscript) {
                    const cleanDisplay = (typeof transliterateJawiToRumi === 'function' ? transliterateJawiToRumi(latestTranscript) : latestTranscript)
                        .replace(/[\u0600-\u06FF\u0750-\u077F\u08A0-\u08FF\uFB50-\uFDFF\uFE70-\uFEFF]/g, '')
                        .trim() || latestTranscript;

                    if (isFinalResult) {
                        if (window.playOops) window.playOops();
                        statusEl.innerHTML = `Awak sebut: <b style="color: #dc2626; display: inline-block;">"${cleanDisplay}"</b>. Cuba lagi!`;
                        statusEl.className = "ar-speech-text text-red-700";
                        statusEl.style.color = "#dc2626";
                        if (speechBox) {
                            speechBox.style.backgroundColor = "#fee2e2";
                            speechBox.style.borderColor = "#ef4444";
                        }
                        setTimeout(() => {
                            if (speechBox) {
                                speechBox.style.backgroundColor = "#ffffff";
                                speechBox.style.borderColor = "#10182f";
                            }
                            if (window.isARPlaying && statusEl) {
                                statusEl.innerText = getARPromptText();
                                statusEl.className = "ar-speech-text";
                                statusEl.style.color = "var(--color-dark, #10182f)";
                            }
                        }, 1800);
                    } else {
                        statusEl.innerHTML = `Mendengar: <b style="color: #2563eb; display: inline-block;">"${cleanDisplay}"</b>...`;
                        statusEl.className = "ar-speech-text";
                        statusEl.style.color = "var(--color-dark, #10182f)";
                    }
                }
            }
        };

        recognition.onerror = (event) => {
            console.warn("[AR Speech Recognition Error]", event.error);
            if (event.error === 'not-allowed' || event.error === 'service-not-allowed') {
                const statusEl = document.getElementById('speech_status_ar_sukukata');
                if (statusEl) {
                    statusEl.innerHTML = '<span style="color:#dc2626;font-weight:bold;font-size:0.85rem;">⚠️ Akses Mikrofon disekat! Sila klik ikon kunci di URL browser dan benarkan Mikrofon.</span>';
                }
                if (window.showAppModalAlert) {
                    window.showAppModalAlert("Akses Mikrofon Diperlukan", "Pelayar anda menyekat akses mikrofon. Sila klik ikon kunci di bar alamat pelayar (sebelah URL) dan tukar tetapan Mikrofon kepada 'Benarkan' (Allow).");
                }
            } else if (event.error === 'no-speech' || event.error === 'audio-capture' || event.error === 'network' || event.error === 'aborted') {
                if (window.isARPlaying) {
                    setTimeout(() => {
                        if (window.isARPlaying) {
                            try { recognition.start(); } catch (e) { }
                        }
                    }, 150);
                }
            }
        };

        recognition.onend = () => {
            const micIcon = document.getElementById('mic_icon_ar_sukukata');
            if (micIcon && !window.isARPlaying) {
                micIcon.classList.add('hidden');
                micIcon.style.display = 'none';
            }
            if (window.isARPlaying) {
                setTimeout(() => {
                    if (window.isARPlaying) {
                        try { recognition.start(); } catch (e) { }
                    }
                }, 100);
            }
        };

        window.arRecognition = recognition;
    } else {
        const statusEl = document.getElementById('speech_status_ar_sukukata');
        if (statusEl) {
            statusEl.innerText = "Maaf, pelayar tidak menyokong fungsi suara.";
            statusEl.classList.add('text-red-500');
        }
        const startBtn = document.getElementById('start_btn_ar_sukukata');
        if (startBtn) {
            startBtn.disabled = true;
            startBtn.classList.add('opacity-50', 'cursor-not-allowed');
        }
    }
}

function startARSpeechRecognition() {
    if (!window.isARPlaying) return;
    if (!window.arRecognition) {
        initSpeechRecognition();
    }
    if (window.arRecognition) {
        try {
            window.arRecognition.start();
        } catch (e) {
            console.log("[AR Speech Start Notice]", e.message);
        }
    }
}

window.toggleARPlay = function () {
    const startBtn = document.getElementById('start_btn_ar_sukukata');
    const statusEl = document.getElementById('speech_status_ar_sukukata');
    const sc = document.getElementById("ar_speech_box_container");

    if (!window.isARPlaying) {
        window.isARPlaying = true;
        if (sc) { sc.style.visibility = "visible"; sc.style.opacity = 1; }
        if (startBtn) {
            startBtn.innerHTML = '<i class="fa-solid fa-pause"></i>';
            startBtn.className = "neo-btn bg-red ar-start-btn";
            startBtn.style.backgroundColor = "#ef4444";
            startBtn.style.color = "#ffffff";
        }
        if (statusEl) {
            statusEl.innerText = getARPromptText();
            statusEl.className = "ar-speech-text";
            statusEl.style.color = "var(--color-dark, #10182f)";
        }

        if (!window.currentARWord) {
            nextARWord();
        }

        if (navigator.mediaDevices && navigator.mediaDevices.getUserMedia) {
            navigator.mediaDevices.getUserMedia({ audio: true }).then((stream) => {
                // Immediately stop track so Web Speech API has exclusive access
                if (stream && stream.getTracks) {
                    stream.getTracks().forEach(t => t.stop());
                }
                startARSpeechRecognition();
            }).catch((err) => {
                console.warn("[Mic Permission Notice]", err);
                startARSpeechRecognition();
            });
        } else {
            startARSpeechRecognition();
        }
    } else {
        window.isARPlaying = false;
        if (startBtn) {
            startBtn.innerHTML = 'MULA';
            startBtn.className = "neo-btn ar-start-btn";
            startBtn.style.backgroundColor = "#ffe24a";
            startBtn.style.color = "#10182f";
        }
        if (window.arRecognition) {
            try { window.arRecognition.stop(); } catch (e) { }
        }
        if (statusEl) {
            statusEl.innerText = 'Tekan "MULA" untuk sambung.';
            statusEl.className = "ar-speech-text";
            statusEl.style.color = "var(--color-dark, #10182f)";
        }
        const micIcon = document.getElementById('mic_icon_ar_sukukata');
        if (micIcon) {
            micIcon.classList.add('hidden');
            micIcon.style.display = 'none';
        }
    }
};

// Bind event listener on start button
setTimeout(() => {
    const startBtn = document.getElementById('start_btn_ar_sukukata');
    if (startBtn) {
        startBtn.onclick = window.toggleARPlay;
    }
}, 500);

function nextARWord() {
    if (!window.arSukuKataWordsRemaining || window.arSukuKataWordsRemaining.length === 0) {
        window.isARPlaying = false;
        const startBtn = document.getElementById('start_btn_ar_sukukata');
        if (startBtn) {
            startBtn.innerText = "MULA";
            startBtn.className = "neo-btn ar-start-btn";
        }
        window.currentARWord = "";
        const isABC = window.currentARKemahiran === 'abc';

        if (window.showARResultModal) {
            window.showARResultModal(window.arSukuKataScore, window.currentARKemahiran);
        } else {
            const congratsMsg = isABC
                ? "Tahniah! Anda berjaya menyebut semua huruf A hingga Z dengan tepat."
                : "Tahniah! Anda berjaya menyebut semua perkataan dengan tepat.";

            triggerSuccessAnimation(congratsMsg, () => {
                if (isABC) {
                    window.bukaARABCSebenar();
                } else if (window.showARSukuKataModal) {
                    window.showARSukuKataModal();
                } else {
                    const m = document.getElementById('modal-pilih-ar-sukukata');
                    if (m) m.style.display = 'flex';
                }
            }, null, Math.min(window.arSukuKataScore || 3, 3));
        }
        return;
    }
    const randomIndex = Math.floor(Math.random() * window.arSukuKataWordsRemaining.length);
    const selected = window.arSukuKataWordsRemaining[randomIndex];
    window.currentARWord = typeof selected === 'object' ? selected.word : selected;
    window.currentARWordObj = selected;

    let syllables = [];
    const frontText = typeof selected === 'object' ? (selected.front || selected.word) : selected;
    if (frontText && typeof frontText === 'string') {
        syllables = frontText.split(/[\s-|]+/).filter(s => s.trim() !== '');
    }
    if (syllables.length === 0) {
        syllables = [window.currentARWord];
    }

    let html = syllables.map((s, i) => `<span style="color: ${i % 2 === 0 ? 'var(--color-dark, #10182f)' : '#dc2626'};">${s.toLowerCase()}</span>`).join('');

    const wordDisplay = document.getElementById('word_display_ar_sukukata');
    if (wordDisplay) {
        wordDisplay.style.opacity = '0';
        wordDisplay.style.transform = "scale(0.4)";
        wordDisplay.style.transition = "all 0.25s cubic-bezier(0.175, 0.885, 0.32, 1.275)";

        setTimeout(() => {
            wordDisplay.innerHTML = html;
            wordDisplay.style.opacity = '1';
            wordDisplay.style.transform = "scale(1)";
        }, 180);
    }
}

function arCorrectAnswer() {
    if (!window.isARPlaying || !window.currentARWord || (typeof window.currentARWord === 'string' && window.currentARWord.trim() === '')) return;

    if (typeof window.playPopConfettiSound === 'function') {
        window.playPopConfettiSound();
    }

    confetti({
        particleCount: 150,
        spread: 80,
        origin: { y: 0.5 },
        colors: ['#f472b6', '#fb923c', '#fbbf24', '#a78bfa'],
        zIndex: 99999
    });

    window.arSukuKataScore += 1;
    if (window.showStarPopupAR) window.showStarPopupAR('view-ar-sukukata');
    const scoreDisp = document.getElementById('score_display_ar_sukukata');
    if (scoreDisp) scoreDisp.innerText = window.arSukuKataScore;
    const mobileStarsCount = document.getElementById('ar_header_stars_count');
    if (mobileStarsCount) mobileStarsCount.innerText = window.arSukuKataScore;

    // Automatically update student profile stars & records immediately!
    const arKemahiran = window.currentARKemahiran || 'umum';
    const activityKey = arKemahiran === 'abc' ? 'ar_abc' : ('arSukuKata_' + arKemahiran);
    if (typeof window.tambahBintangGlobal === 'function') {
        window.tambahBintangGlobal(activityKey, 1);
    } else {
        const logFn = window.logProgress || (typeof logProgress === 'function' ? logProgress : null);
        if (logFn) {
            logFn(activityKey, 'latihan', window.arSukuKataScore, 'arSukuKata');
        }
    }
    if (typeof updateProfilUI === 'function') {
        updateProfilUI();
    }

    const wordCard = document.getElementById('word_card_ar_sukukata');
    const speechBox = document.querySelector('.ar-speech-box');
    if (wordCard) {
        wordCard.style.borderColor = "#22c55e";
        wordCard.style.backgroundColor = "#dcfce7";
    }

    const statusEl = document.getElementById('speech_status_ar_sukukata');
    if (statusEl) {
        statusEl.innerText = "Betul! Hebatnya! 🎉";
        statusEl.className = "ar-speech-text";
    }

    if (speechBox) {
        speechBox.style.backgroundColor = "#dcfce7";
        speechBox.style.borderColor = "#22c55e";
    }

    setTimeout(() => {
        if (wordCard) {
            wordCard.style.borderColor = "#10182f";
            wordCard.style.backgroundColor = "#ffffff";
        }
        if (speechBox) {
            speechBox.style.backgroundColor = "#ffffff";
            speechBox.style.borderColor = "#10182f";
        }
        if (window.isARPlaying) {
            // Remove the correctly answered word
            const index = window.arSukuKataWordsRemaining.findIndex(item => {
                const w = typeof item === 'object' ? item.word : item;
                return w === window.currentARWord;
            });
            if (index > -1) {
                window.arSukuKataWordsRemaining.splice(index, 1);
            }
            nextARWord();
            if (window.isARPlaying && statusEl) {
                statusEl.innerText = getARPromptText();
                statusEl.className = "ar-speech-text";
                statusEl.style.color = "var(--color-dark, #10182f)";
            }
        }
    }, 1800);
}

window.showStarPopupAR = function (targetViewId) {
    if (typeof window.playPopConfettiSound === 'function') {
        window.playPopConfettiSound();
    }

    const oldPopups = document.querySelectorAll('.ar-star-popup-dynamic');
    oldPopups.forEach(p => p.remove());

    const popup = document.createElement('div');
    popup.className = 'ar-star-popup ar-star-popup-dynamic animate-star';
    popup.innerHTML = '+1 Bintang! 🌟';
    popup.style.cssText = `
        position: fixed !important;
        top: 35% !important;
        left: 50% !important;
        transform: translate(-50%, -50%);
        z-index: 99999999 !important;
        font-size: clamp(2.2rem, 7.5vw, 4rem) !important;
        font-family: 'AtlantaRoundedBlack', 'AtlantaRounded', sans-serif !important;
        font-weight: 900 !important;
        color: #fbbf24 !important;
        text-shadow: 0 4px 14px rgba(0, 0, 0, 0.95), 0 0 24px rgba(251, 191, 36, 0.9) !important;
        pointer-events: none !important;
        white-space: nowrap !important;
        display: inline-flex !important;
        align-items: center !important;
        justify-content: center !important;
        animation: popStarTandukStyle 1.85s cubic-bezier(0.175, 0.885, 0.32, 1.275) forwards !important;
    `;
    document.body.appendChild(popup);

    setTimeout(() => {
        if (popup && popup.parentNode) {
            popup.parentNode.removeChild(popup);
        }
    }, 1900);
};
window.showStarPopup = window.showStarPopupAR;

window.showARResultModal = function (scoreVal, kemahiranVal, customContinue, customRetry) {
    const stars = scoreVal !== undefined ? scoreVal : (window.arSukuKataScore || 0);
    const kemahiran = kemahiranVal || window.currentARKemahiran || 'abc';
    const isABC = (kemahiran === 'abc');

    const onRetry = customRetry || function () {
        if (isABC) {
            if (window.bukaARABCSebenar) window.bukaARABCSebenar();
        } else {
            if (window.bukaARSukuKataKemahiran) window.bukaARSukuKataKemahiran(kemahiran);
        }
    };

    const onContinue = customContinue || function () {
        if (window.tutupARSukuKata) window.tutupARSukuKata();
        else if (window.paparSkrin) window.paparSkrin('map-screen');
    };

    triggerSuccessAnimation(`Anda berjaya mendapat ${stars} bintang.`, onContinue, onRetry, stars);
};

