// Levenshtein distance for fuzzy matching
function computeLevenshtein(a, b) {
    if (!a || !b) return (a || '').length + (b || '').length;
    const dp = Array.from({ length: a.length + 1 }, () => new Array(b.length + 1).fill(0));
    for (let i = 0; i <= a.length; i++) dp[i][0] = i;
    for (let j = 0; j <= b.length; j++) dp[0][j] = j;
    for (let i = 1; i <= a.length; i++) {
        for (let j = 1; j <= b.length; j++) {
            const cost = a[i - 1] === b[j - 1] ? 0 : 1;
            dp[i][j] = Math.min(
                dp[i - 1][j] + 1,
                dp[i][j - 1] + 1,
                dp[i - 1][j - 1] + cost
            );
        }
    }
    return dp[a.length][b.length];
}

function transliterateJawiToRumi(text) {
    if (!text) return '';
    const jawiMap = {
        'ا': 'a', 'أ': 'a', 'إ': 'i', 'آ': 'a',
        'ب': 'b', 'ت': 't', 'ث': 's', 'ج': 'j', 'ح': 'h', 'خ': 'kh',
        'د': 'd', 'ذ': 'z', 'ر': 'r', 'ز': 'z', 'س': 's', 'ش': 'sy',
        'ص': 's', 'ض': 'd', 'ط': 't', 'ظ': 'z', 'ع': 'a', 'غ': 'gh',
        'ف': 'f', 'ڤ': 'p', 'ق': 'q', 'ك': 'k', 'ک': 'k', 'ݢ': 'g',
        'ل': 'l', 'م': 'm', 'ن': 'n', 'و': 'u', 'ۏ': 'v', 'ه': 'h',
        'ة': 't', 'ي': 'i', 'ى': 'i', 'ی': 'i', 'ء': '', 'ئ': 'i',
        'ڽ': 'ny', 'چ': 'c', 'ڠ': 'ng'
    };
    return text.split('').map(ch => jawiMap[ch] !== undefined ? jawiMap[ch] : ch).join('');
}
window.transliterateJawiToRumi = transliterateJawiToRumi;

function normalizePhoneticMalay(str) {
    if (!str) return '';
    let s = transliterateJawiToRumi(str).toLowerCase().trim();
    s = s.replace(/[\s\-_.,!?]+/g, '');
    s = s.replace(/oo|uu/g, 'u');
    s = s.replace(/ee|ii/g, 'i');
    s = s.replace(/aa/g, 'a');
    s = s.replace(/ow/g, 'o');
    s = s.replace(/ch/g, 'c');
    s = s.replace(/kh/g, 'k');
    s = s.replace(/ny/g, 'n');
    s = s.replace(/ng/g, 'n');
    s = s.replace(/sy/g, 's');
    if (s.length > 3 && s.endsWith('h')) {
        s = s.slice(0, -1);
    }
    return s;
}

window.checkMalayWordMatch = function (candidateTranscripts, target) {
    if (!target || !candidateTranscripts || candidateTranscripts.length === 0) return false;

    const targetStr = typeof target === 'object' ? (target.word || target.front || '') : target;
    const cleanTarget = targetStr.toString().toLowerCase().replace(/[\s\-_.,!?]+/g, '').trim();
    if (!cleanTarget) return false;

    // 1. Single Letter Recognition (Alphabet & Phonics only)
    if (cleanTarget.length === 1) {
        const letterMap = {
            'a': ['a', 'ah', 'aa', 'ei', 'ey', 'ae', 'alif', 'ا', 'e', 'eh', 'ha', 'ar', 'aye', 'u', 'o', 'a.'],
            'b': ['b', 'bi', 'be', 'bee', 'bii', 'beh', 'ba', 'ب', 'b.'],
            'c': ['c', 'si', 'se', 'ce', 'see', 'ci', 'cee', 'ca', 'چ', 'c.'],
            'd': ['d', 'di', 'de', 'dee', 'dii', 'deh', 'da', 'د', 'd.'],
            'e': ['e', 'eh', 'ee', 'ih', 'ea', 'a', 'e.'],
            'f': ['f', 'ef', 'eff', 'fe', 'fa', 'ف', 'f.'],
            'g': ['g', 'ji', 'ge', 'gee', 'gi', 'jee', 'ga', 'ݢ', 'g.'],
            'h': ['h', 'hech', 'he', 'aitch', 'ech', 'ha', 'eich', 'ح', 'ه', 'h.'],
            'i': ['i', 'ai', 'eye', 'aye', 'ih', 'ee', 'i.'],
            'j': ['j', 'je', 'jay', 'ji', 'jei', 'ja', 'jim', 'ج', 'j.'],
            'k': ['k', 'ka', 'ke', 'kay', 'kei', 'keh', 'kaf', 'ك', 'k.'],
            'l': ['l', 'el', 'ell', 'le', 'la', 'lam', 'ل', 'l.'],
            'm': ['m', 'em', 'emm', 'mm', 'mmm', 'hmm', 'hm', 'mim', 'م', 'm.'],
            'n': ['n', 'en', 'enn', 'nn', 'nnn', 'ne', 'na', 'nun', 'ن', 'n.'],
            'o': ['o', 'oh', 'ow', 'ou', 'ooh', 'u', 'o.'],
            'p': ['p', 'pi', 'pe', 'pee', 'pii', 'peh', 'pa', 'ڤ', 'p.'],
            'q': ['q', 'kiu', 'kiw', 'cue', 'kew', 'queue', 'kyu', 'qiu', 'qaf', 'ق', 'q.'],
            'r': ['r', 'ar', 'are', 'er', 'err', 're', 'ra', 'ro', 'air', 'hour', 'ear', 'or', 'ur', 'ر', 'و', 'r.'],
            's': ['s', 'es', 'ess', 'se', 'sa', 'sin', 'س', 's.'],
            't': ['t', 'ti', 'te', 'tee', 'tii', 'teh', 'ta', 'ت', 'ط', 't.'],
            'u': ['u', 'you', 'yu', 'oo', 'uuh', 'uh', 'uu', 'o', 'u.'],
            'v': ['v', 'vi', 've', 'vee', 'vii', 'veh', 'va', 'ۏ', 'v.'],
            'w': ['w', 'dabelu', 'double u', 'dabelyu', 'dableu', 'doubleyou', 'dabel u', 'wau', 'و', 'w.'],
            'x': ['x', 'eks', 'ex', 'iks', 'x.'],
            'y': ['y', 'wai', 'why', 'way', 'waii', 'ye', 'ya', 'ي', 'y.'],
            'z': ['z', 'zed', 'zet', 'zee', 'zeh', 'za', 'zai', 'set', 'sed', 'sat', 'zi', 'ze', 'zat', 'zack', 'zah', 'the', 'that', 'ز', 'ذ', 'ظ', 'ض', 'z.']
        };
        const validList = letterMap[cleanTarget] || [cleanTarget];

        for (const rawCandidate of candidateTranscripts) {
            if (!rawCandidate) continue;

            const candVariants = [
                rawCandidate.toLowerCase().trim(),
                transliterateJawiToRumi(rawCandidate).toLowerCase().trim()
            ];

            for (const variant of candVariants) {
                let stripped = variant.replace(/^(huruf|sebut|perkataan|sebutan|letter|fonik)\s+/gi, '');
                const candClean = stripped.replace(/[\s\-_.,!?]+/g, '').trim();

                if (candClean === cleanTarget || validList.includes(candClean)) return true;

                const words = variant.split(/[\s\-_.,!?]+/);
                for (const w of words) {
                    const wClean = w.trim();
                    if (wClean === cleanTarget || validList.includes(wClean)) return true;
                }
            }
        }
        return false;
    }

    // 2. Multi-letter Words & Suku Kata Recognition (Only exact target words / joined syllables)
    const normTarget = normalizePhoneticMalay(cleanTarget);
    if (!normTarget) return false;

    for (const rawCandidate of candidateTranscripts) {
        if (!rawCandidate) continue;

        const candVariants = [
            rawCandidate.toLowerCase().trim(),
            transliterateJawiToRumi(rawCandidate).toLowerCase().trim()
        ];

        for (const variant of candVariants) {
            let cleanRaw = variant.replace(/^(huruf|sebut|perkataan|sebutan|ini|saya)\s+/gi, '');

            // 2a. Direct clean match
            const candClean = cleanRaw.replace(/[\s\-_.,!?]+/g, '').trim();
            if (candClean === cleanTarget) return true;

            // 2b. Phonetic normalized match
            const normCand = normalizePhoneticMalay(cleanRaw);
            if (normCand === normTarget) return true;

            // 2c. Tokenized word checks (e.g. "sebut bola" -> "bola")
            const rawWords = cleanRaw.replace(/[\-_.,!?]+/g, ' ').split(/\s+/).filter(w => w.length > 0);
            for (const w of rawWords) {
                const wClean = w.replace(/[\s\-_.,!?]+/g, '').trim();
                if (wClean === cleanTarget) return true;
                const normW = normalizePhoneticMalay(w);
                if (normW === normTarget) return true;
            }

            // 2d. Sub-phrase joined check for syllables (e.g. "ba tu" -> "batu", "ke re ta" -> "kereta")
            const joinedNorm = rawWords.map(normalizePhoneticMalay).join('');
            if (joinedNorm === normTarget) return true;

            if (rawWords.length > 1) {
                for (let i = 0; i < rawWords.length - 1; i++) {
                    const subJoined = normalizePhoneticMalay(rawWords[i] + rawWords[i + 1]);
                    if (subJoined === normTarget) return true;
                }
            }

            // 2e. Strict minor phonetic tolerance ONLY for long words (length >= 5 e.g. "kerete" for "kereta")
            if (normTarget.length >= 5 && normCand.length >= 5 && normCand[0] === normTarget[0]) {
                const dist = computeLevenshtein(normCand, normTarget);
                if (dist <= 1) return true;
            }
        }
    }

    return false;
};

