function drawGlowingHandSkeleton(ctx, landmarks, width, height) {
    const CONNECTIONS = [
        [0, 1], [1, 2], [2, 3], [3, 4], // Thumb
        [0, 5], [5, 6], [6, 7], [7, 8], // Index
        [0, 9], [9, 10], [10, 11], [11, 12], // Middle
        [0, 13], [13, 14], [14, 15], [15, 16], // Ring
        [0, 17], [17, 18], [18, 19], [19, 20], // Pinky
        [5, 9], [9, 13], [13, 17] // Palm Base
    ];

    const pts = landmarks.map(lm => ({ x: lm.x * width, y: lm.y * height }));

    // Neon Glow Outer Line
    ctx.save();
    ctx.shadowColor = '#38bdf8';
    ctx.shadowBlur = 14;
    ctx.strokeStyle = '#38bdf8';
    ctx.lineWidth = 4;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';

    for (const [start, end] of CONNECTIONS) {
        ctx.beginPath();
        ctx.moveTo(pts[start].x, pts[start].y);
        ctx.lineTo(pts[end].x, pts[end].y);
        ctx.stroke();
    }

    // Bright Core Line
    ctx.shadowBlur = 0;
    ctx.strokeStyle = '#ffffff';
    ctx.lineWidth = 2;
    for (const [start, end] of CONNECTIONS) {
        ctx.beginPath();
        ctx.moveTo(pts[start].x, pts[start].y);
        ctx.lineTo(pts[end].x, pts[end].y);
        ctx.stroke();
    }

    // Joints & Fingertips
    for (let i = 0; i < pts.length; i++) {
        const isFingertip = [4, 8, 12, 16, 20].includes(i);
        const radius = isFingertip ? 7 : (i === 0 ? 8 : 4.5);

        ctx.beginPath();
        ctx.arc(pts[i].x, pts[i].y, radius, 0, 2 * Math.PI);
        ctx.fillStyle = isFingertip ? '#f59e0b' : '#38bdf8';
        ctx.shadowColor = isFingertip ? '#f59e0b' : '#38bdf8';
        ctx.shadowBlur = 10;
        ctx.fill();

        ctx.beginPath();
        ctx.arc(pts[i].x, pts[i].y, radius - 2, 0, 2 * Math.PI);
        ctx.fillStyle = '#ffffff';
        ctx.shadowBlur = 0;
        ctx.fill();
    }
    ctx.restore();
}

function countOpenFingersOnHand(landmarks, handedness) {
    const wrist = landmarks[0];
    const middleMcp = landmarks[9];
    const palmScale = Math.hypot(middleMcp.x - wrist.x, middleMcp.y - wrist.y);
    if (palmScale === 0) return 0;

    let openCount = 0;

    // 1. Thumb (Tip [4], IP [3], MCP [2], Pinky MCP [17], Index MCP [5])
    const thumbTip = landmarks[4];
    const thumbIp = landmarks[3];
    const thumbMcp = landmarks[2];
    const pinkyMcp = landmarks[17];
    const indexMcp = landmarks[5];

    const distTipToPinky = Math.hypot(thumbTip.x - pinkyMcp.x, thumbTip.y - pinkyMcp.y);
    const distIpToPinky = Math.hypot(thumbIp.x - pinkyMcp.x, thumbIp.y - pinkyMcp.y);
    const distTipToIndex = Math.hypot(thumbTip.x - indexMcp.x, thumbTip.y - indexMcp.y);
    const distMcpToIndex = Math.hypot(thumbMcp.x - indexMcp.x, thumbMcp.y - indexMcp.y);

    if (distTipToPinky > distIpToPinky + 0.04 * palmScale && distTipToIndex > distMcpToIndex + 0.04 * palmScale) {
        openCount++;
    }

    // 2. Four Fingers (Index: 8, Middle: 12, Ring: 16, Pinky: 20)
    const fingerTips = [8, 12, 16, 20];
    const fingerPips = [6, 10, 14, 18];
    const fingerMcps = [5, 9, 13, 17];

    for (let f = 0; f < 4; f++) {
        const tip = landmarks[fingerTips[f]];
        const pip = landmarks[fingerPips[f]];
        const mcp = landmarks[fingerMcps[f]];

        const distTipWrist = Math.hypot(tip.x - wrist.x, tip.y - wrist.y);
        const distPipWrist = Math.hypot(pip.x - wrist.x, pip.y - wrist.y);
        const distMcpWrist = Math.hypot(mcp.x - wrist.x, mcp.y - wrist.y);

        if (distTipWrist > distPipWrist + 0.06 * palmScale && distTipWrist > distMcpWrist + 0.12 * palmScale) {
            openCount++;
        }
    }

    return openCount;
}

function initARKiraJariCamera() {
    const videoElement = document.getElementById('input_video_ar_kirajari');
    const canvasElement = document.getElementById('output_canvas_ar_kirajari');
    const overlay = document.getElementById('camera_status_ar_kirajari');
    if (!videoElement || !canvasElement) return;

    const canvasCtx = canvasElement.getContext('2d');

    const hideOverlay = () => {
        if (overlay) {
            overlay.classList.add('hidden');
            overlay.classList.add('opacity-0');
            overlay.style.setProperty('display', 'none', 'important');
        }
    };

    if (window.arKiraJariCameraStream) {
        try { window.arKiraJariCameraStream.getTracks().forEach(t => t.stop()); } catch (e) { }
    }

    let hands = null;
    if (typeof Hands !== 'undefined') {
        hands = new Hands({
            locateFile: (file) => `https://cdn.jsdelivr.net/npm/@mediapipe/hands/${file}`
        });

        hands.setOptions({
            maxNumHands: 2,
            modelComplexity: 1,
            minDetectionConfidence: 0.5,
            minTrackingConfidence: 0.5
        });

        let holdTarget = -1;
        let holdStartTime = 0;
        let isSuccessTriggered = false;

        hands.onResults((results) => {
            if (!document.getElementById('view-ar-kirajari')?.classList.contains('active')) return;
            hideOverlay();

            canvasCtx.save();
            canvasCtx.clearRect(0, 0, canvasElement.width, canvasElement.height);

            if (videoElement.videoWidth && canvasElement.width !== videoElement.videoWidth) {
                canvasElement.width = videoElement.videoWidth;
                canvasElement.height = videoElement.videoHeight;
            }

            // Draw Mirror Flip Camera Frame
            canvasCtx.translate(canvasElement.width, 0);
            canvasCtx.scale(-1, 1);
            canvasCtx.drawImage(results.image, 0, 0, canvasElement.width, canvasElement.height);

            let totalFingersCount = 0;

            if (results.multiHandLandmarks && results.multiHandLandmarks.length > 0) {
                for (let h = 0; h < results.multiHandLandmarks.length; h++) {
                    const landmarks = results.multiHandLandmarks[h];
                    const handedness = results.multiHandedness && results.multiHandedness[h] ? results.multiHandedness[h].label : 'Right';

                    drawGlowingHandSkeleton(canvasCtx, landmarks, canvasElement.width, canvasElement.height);
                    totalFingersCount += countOpenFingersOnHand(landmarks, handedness);
                }
            }

            canvasCtx.restore();

            // Update Live Detector Badge
            const liveCountEl = document.getElementById('ar_kirajari_live_count');
            if (liveCountEl) liveCountEl.innerText = totalFingersCount.toString();

            if (!window.isARKiraJariPlaying || !window.currentARKiraJariQuestion) return;

            const targetCount = window.currentARKiraJariQuestion.count;
            const holdRingContainer = document.getElementById('ar_kirajari_hold_ring_container');
            const progressCircle = document.getElementById('ar_kirajari_progress_circle');
            const statusText = document.getElementById('ar_kirajari_status_text');
            const statusBox = document.getElementById('ar_kirajari_status_box');

            if (totalFingersCount === targetCount && targetCount > 0) {
                if (holdTarget !== targetCount) {
                    holdTarget = targetCount;
                    holdStartTime = Date.now();
                    isSuccessTriggered = false;
                }

                const elapsed = Date.now() - holdStartTime;
                const HOLD_DURATION = 1100;
                const progressRatio = Math.min(1, elapsed / HOLD_DURATION);

                if (holdRingContainer) holdRingContainer.style.display = 'flex';
                if (progressCircle) {
                    const circumference = 201.06;
                    progressCircle.style.strokeDashoffset = (circumference * (1 - progressRatio)).toString();
                }

                if (statusText) {
                    statusText.innerText = `Hebat! Tahan ${targetCount} jari (${Math.ceil((HOLD_DURATION - elapsed) / 100) / 10}s)...`;
                    statusText.className = "ar-speech-text text-green-700 font-bold";
                }
                if (statusBox) {
                    statusBox.style.backgroundColor = "#dcfce7";
                    statusBox.style.borderColor = "#22c55e";
                }

                if (elapsed >= HOLD_DURATION && !isSuccessTriggered) {
                    isSuccessTriggered = true;
                    if (holdRingContainer) holdRingContainer.style.display = 'none';
                    arKiraJariCorrectAnswer();
                }
            } else {
                holdTarget = -1;
                holdStartTime = 0;
                if (holdRingContainer) holdRingContainer.style.display = 'none';
                if (progressCircle) progressCircle.style.strokeDashoffset = '201.06';

                if (statusText && window.isARKiraJariPlaying) {
                    if (totalFingersCount > 0) {
                        statusText.innerText = `Jari dikesan: ${totalFingersCount}. Sasaran: ${targetCount} jari!`;
                        statusText.className = "ar-speech-text text-amber-700";
                    } else {
                        statusText.innerText = `Tunjukkan ${targetCount} jari anda ke arah kamera!`;
                        statusText.className = "ar-speech-text";
                    }
                }
                if (statusBox) {
                    statusBox.style.backgroundColor = "#ffffff";
                    statusBox.style.borderColor = "var(--color-dark)";
                }
            }
        });
    }

    navigator.mediaDevices.getUserMedia({
        video: { facingMode: 'user', width: { ideal: 640 }, height: { ideal: 480 } },
        audio: false
    }).then((stream) => {
        window.arKiraJariCameraStream = stream;
        videoElement.srcObject = stream;
        videoElement.play().then(() => {
            hideOverlay();
        }).catch(() => {
            hideOverlay();
        });

        async function sendFrame() {
            if (!document.getElementById('view-ar-kirajari')?.classList.contains('active')) return;
            if (videoElement.readyState >= 2 && hands) {
                try {
                    await hands.send({ image: videoElement });
                } catch (e) { }
            }
            requestAnimationFrame(sendFrame);
        }
        requestAnimationFrame(sendFrame);
    }).catch((err) => {
        console.error("Camera access error:", err);
        if (overlay) {
            overlay.innerHTML = '<i class="fa-solid fa-camera-slash fa-3x mb-3 text-red-500"></i><p class="text-xl font-bold text-white">Kamera tidak dapat diakses.</p><p class="text-xs text-gray-300 mt-1">Sila benarkan kebenaran kamera pada pelayar anda.</p>';
        }
    });
}


